#[derive(Clone, Copy, Default)]
struct UringRecvStats {
    bytes: usize,
    data_cqes: usize,
    full_chunk_cqes: usize,
    partial_cqes: usize,
    min_cqe_len: usize,
    max_cqe_len: usize,
    ring: RawRingStats,
}

impl UringRecvStats {
    fn record_cqe(&mut self, len: usize, requested_len: usize) {
        if self.data_cqes == 0 || len < self.min_cqe_len {
            self.min_cqe_len = len;
        }
        self.max_cqe_len = self.max_cqe_len.max(len);
        self.bytes = self.bytes.saturating_add(len);
        self.data_cqes = self.data_cqes.saturating_add(1);
        if len == requested_len {
            self.full_chunk_cqes = self.full_chunk_cqes.saturating_add(1);
        } else {
            self.partial_cqes = self.partial_cqes.saturating_add(1);
        }
    }

    fn merge(&mut self, other: &Self) {
        if other.data_cqes != 0 && (self.data_cqes == 0 || other.min_cqe_len < self.min_cqe_len) {
            self.min_cqe_len = other.min_cqe_len;
        }
        self.max_cqe_len = self.max_cqe_len.max(other.max_cqe_len);
        self.bytes = self.bytes.saturating_add(other.bytes);
        self.data_cqes = self.data_cqes.saturating_add(other.data_cqes);
        self.full_chunk_cqes = self.full_chunk_cqes.saturating_add(other.full_chunk_cqes);
        self.partial_cqes = self.partial_cqes.saturating_add(other.partial_cqes);
        self.ring.sqes_queued = self.ring.sqes_queued.saturating_add(other.ring.sqes_queued);
        self.ring.submit_syscalls = self
            .ring
            .submit_syscalls
            .saturating_add(other.ring.submit_syscalls);
        self.ring.wait_syscalls = self
            .ring
            .wait_syscalls
            .saturating_add(other.ring.wait_syscalls);
        self.ring.sqes_submitted = self
            .ring
            .sqes_submitted
            .saturating_add(other.ring.sqes_submitted);
        self.ring.cqes_popped = self.ring.cqes_popped.saturating_add(other.ring.cqes_popped);
        self.ring.try_pop_empty = self
            .ring
            .try_pop_empty
            .saturating_add(other.ring.try_pop_empty);
        self.ring.wait_cqe_calls = self
            .ring
            .wait_cqe_calls
            .saturating_add(other.ring.wait_cqe_calls);
        self.ring.submit_short = self
            .ring
            .submit_short
            .saturating_add(other.ring.submit_short);
        self.ring.cqe_spin_loops = self
            .ring
            .cqe_spin_loops
            .saturating_add(other.ring.cqe_spin_loops);
        self.ring.cqe_hot_poll_waits = self
            .ring
            .cqe_hot_poll_waits
            .saturating_add(other.ring.cqe_hot_poll_waits);
        self.ring.cqe_adaptive_grows = self
            .ring
            .cqe_adaptive_grows
            .saturating_add(other.ring.cqe_adaptive_grows);
        self.ring.cqe_adaptive_shrinks = self
            .ring
            .cqe_adaptive_shrinks
            .saturating_add(other.ring.cqe_adaptive_shrinks);
        self.ring.cqe_adaptive_spin_max_seen = self
            .ring
            .cqe_adaptive_spin_max_seen
            .max(other.ring.cqe_adaptive_spin_max_seen);
    }

    fn avg_cqe_len(&self) -> usize {
        if self.data_cqes == 0 {
            0
        } else {
            self.bytes / self.data_cqes
        }
    }
}

