#[derive(Clone, Copy, PartialEq, Eq)]
enum ZcWalFramingMode {
    Extent,
    Stream,
}

impl ZcWalFramingMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value.to_ascii_lowercase().as_str() {
            "extent" | "extent-header" | "per-extent" => Ok(Self::Extent),
            "stream" | "bulk" | "stream-header" | "per-stream" => Ok(Self::Stream),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown WAL framing mode {other:?}; use extent or stream"),
            )),
        }
    }

    fn from_env(default: Self) -> io::Result<Self> {
        match env::var("URING_PLAY_ZCWAL_FRAMING") {
            Ok(value) if !value.trim().is_empty() => Self::parse(&value),
            _ => Ok(default),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Extent => "extent",
            Self::Stream => "stream",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ZcWalDataPath {
    Blocking,
    Uring,
}

impl ZcWalDataPath {
    fn parse(value: &str) -> io::Result<Self> {
        match value.to_ascii_lowercase().as_str() {
            "blocking" | "block" | "std" | "readwrite" | "read-write" => Ok(Self::Blocking),
            "uring" | "io-uring" | "iouring" => Ok(Self::Uring),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown WAL data path {other:?}; use blocking or uring"),
            )),
        }
    }

    fn from_env(default: Self) -> io::Result<Self> {
        match env::var("URING_PLAY_ZCWAL_DATA_PATH") {
            Ok(value) if !value.trim().is_empty() => Self::parse(&value),
            _ => Ok(default),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Blocking => "blocking",
            Self::Uring => "uring",
        }
    }
}

fn zcwal_put_u16(out: &mut [u8], offset: usize, value: u16) {
    out[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
}

fn zcwal_put_u32(out: &mut [u8], offset: usize, value: u32) {
    out[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

fn zcwal_put_u64(out: &mut [u8], offset: usize, value: u64) {
    out[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
}

fn zcwal_read_u16(input: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([input[offset], input[offset + 1]])
}

fn zcwal_read_u32(input: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([
        input[offset],
        input[offset + 1],
        input[offset + 2],
        input[offset + 3],
    ])
}

fn zcwal_read_u64(input: &[u8], offset: usize) -> u64 {
    u64::from_le_bytes([
        input[offset],
        input[offset + 1],
        input[offset + 2],
        input[offset + 3],
        input[offset + 4],
        input[offset + 5],
        input[offset + 6],
        input[offset + 7],
    ])
}

impl ZcWalExtentHeader {
    fn encode(self) -> [u8; ZC_WAL_EXTENT_HEADER_LEN] {
        let mut out = [0u8; ZC_WAL_EXTENT_HEADER_LEN];
        out[0..8].copy_from_slice(ZC_WAL_EXTENT_MAGIC);
        zcwal_put_u16(&mut out, 0x08, ZC_WAL_EXTENT_VERSION);
        zcwal_put_u16(&mut out, 0x0a, ZC_WAL_EXTENT_HEADER_LEN as u16);
        zcwal_put_u32(&mut out, 0x0c, self.flags);
        zcwal_put_u32(&mut out, 0x10, self.lane_id);
        zcwal_put_u32(&mut out, 0x14, self.lane_count);
        zcwal_put_u32(&mut out, 0x18, self.shard_id);
        zcwal_put_u32(&mut out, 0x1c, self.record_size);
        zcwal_put_u32(&mut out, 0x20, self.record_count);
        zcwal_put_u32(&mut out, 0x24, self.payload_len);
        zcwal_put_u32(&mut out, 0x28, self.table_len);
        zcwal_put_u64(&mut out, 0x30, self.base_logical_index);
        zcwal_put_u64(&mut out, 0x38, self.extent_sequence);
        zcwal_put_u64(&mut out, 0x40, self.base_wal_offset);
        zcwal_put_u64(&mut out, 0x48, self.wal_epoch);
        zcwal_put_u64(&mut out, 0x50, self.descriptor_id);
        zcwal_put_u32(&mut out, 0x58, self.payload_crc32c);
        out
    }

    fn decode(input: &[u8; ZC_WAL_EXTENT_HEADER_LEN]) -> io::Result<Self> {
        if &input[0..8] != ZC_WAL_EXTENT_MAGIC {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "missing ZCWALX1 extent magic",
            ));
        }
        let version = zcwal_read_u16(input, 0x08);
        let header_len = zcwal_read_u16(input, 0x0a) as usize;
        if version != ZC_WAL_EXTENT_VERSION || header_len != ZC_WAL_EXTENT_HEADER_LEN {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("unsupported WAL extent header version={version} len={header_len}"),
            ));
        }
        Ok(Self {
            flags: zcwal_read_u32(input, 0x0c),
            lane_id: zcwal_read_u32(input, 0x10),
            lane_count: zcwal_read_u32(input, 0x14),
            shard_id: zcwal_read_u32(input, 0x18),
            record_size: zcwal_read_u32(input, 0x1c),
            record_count: zcwal_read_u32(input, 0x20),
            payload_len: zcwal_read_u32(input, 0x24),
            table_len: zcwal_read_u32(input, 0x28),
            base_logical_index: zcwal_read_u64(input, 0x30),
            extent_sequence: zcwal_read_u64(input, 0x38),
            base_wal_offset: zcwal_read_u64(input, 0x40),
            wal_epoch: zcwal_read_u64(input, 0x48),
            descriptor_id: zcwal_read_u64(input, 0x50),
            payload_crc32c: zcwal_read_u32(input, 0x58),
        })
    }
}

impl ZcWalAckHeader {
    fn encode(self) -> [u8; ZC_WAL_ACK_HEADER_LEN] {
        let mut out = [0u8; ZC_WAL_ACK_HEADER_LEN];
        out[0..8].copy_from_slice(ZC_WAL_ACK_MAGIC);
        zcwal_put_u16(&mut out, 0x08, ZC_WAL_EXTENT_VERSION);
        zcwal_put_u16(&mut out, 0x0a, ZC_WAL_ACK_HEADER_LEN as u16);
        zcwal_put_u32(&mut out, 0x10, self.lane_id);
        zcwal_put_u32(&mut out, 0x14, self.shard_id);
        zcwal_put_u32(&mut out, 0x18, self.status);
        zcwal_put_u32(&mut out, 0x1c, self.record_size);
        zcwal_put_u64(&mut out, 0x20, self.first_logical_index);
        zcwal_put_u64(&mut out, 0x28, self.last_logical_index);
        zcwal_put_u64(&mut out, 0x30, self.extent_sequence);
        zcwal_put_u64(&mut out, 0x38, self.durable_wal_offset);
        out
    }

    fn decode(input: &[u8; ZC_WAL_ACK_HEADER_LEN]) -> io::Result<Self> {
        if &input[0..8] != ZC_WAL_ACK_MAGIC {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "missing ZCWALA1 ack magic",
            ));
        }
        let version = zcwal_read_u16(input, 0x08);
        let header_len = zcwal_read_u16(input, 0x0a) as usize;
        if version != ZC_WAL_EXTENT_VERSION || header_len != ZC_WAL_ACK_HEADER_LEN {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("unsupported WAL ack header version={version} len={header_len}"),
            ));
        }
        Ok(Self {
            lane_id: zcwal_read_u32(input, 0x10),
            shard_id: zcwal_read_u32(input, 0x14),
            status: zcwal_read_u32(input, 0x18),
            record_size: zcwal_read_u32(input, 0x1c),
            first_logical_index: zcwal_read_u64(input, 0x20),
            last_logical_index: zcwal_read_u64(input, 0x28),
            extent_sequence: zcwal_read_u64(input, 0x30),
            durable_wal_offset: zcwal_read_u64(input, 0x38),
        })
    }
}

fn zcwal_validate_extent_shape(bytes_per_connection: usize, extent_bytes: usize) -> io::Result<()> {
    if bytes_per_connection == 0 || extent_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "WAL extent bytes-per-connection and extent-bytes must be non-zero",
        ));
    }
    if extent_bytes % ZC_WAL_RECORD_SIZE != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "WAL extent bytes must be a multiple of 4096",
        ));
    }
    if bytes_per_connection % extent_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "WAL extent bytes-per-connection must be a multiple of extent-bytes",
        ));
    }
    if extent_bytes / ZC_WAL_RECORD_SIZE > u32::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "WAL extent record count must fit in u32",
        ));
    }
    if extent_bytes > u32::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "WAL extent payload length must fit in u32",
        ));
    }
    Ok(())
}

fn zcwal_validate_framing_shape(
    framing_mode: ZcWalFramingMode,
    bytes_per_connection: usize,
    extent_bytes: usize,
) -> io::Result<()> {
    zcwal_validate_extent_shape(bytes_per_connection, extent_bytes)?;
    if framing_mode == ZcWalFramingMode::Stream && bytes_per_connection > u32::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "stream-framed WAL payload length must fit in u32",
        ));
    }
    Ok(())
}

fn zcwal_uring_pipeline() -> usize {
    env_usize_or("URING_PLAY_ZCWAL_URING_PIPELINE", 32).max(1)
}

fn zcwal_uring_recv_pipeline() -> usize {
    env_usize_or("URING_PLAY_ZCWAL_URING_RECV_PIPELINE", 1).max(1)
}

fn zcwal_uring_entries() -> u32 {
    u32::try_from(env_usize_or("URING_PLAY_ZCWAL_URING_ENTRIES", 64).max(64)).unwrap_or(u32::MAX)
}

fn zcwal_uring_chunk_from_env(
    side_name: &str,
    side_env: &str,
    extent_bytes: usize,
    bytes_per_connection: usize,
    default_bytes: usize,
) -> io::Result<usize> {
    let shared = env_size_opt("URING_PLAY_ZCWAL_FRAME_BYTES")?;
    let side = env_size_opt(side_env)?;
    let value = side.or(shared).unwrap_or(default_bytes);
    if value == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{side_name} transport frame bytes must be non-zero"),
        ));
    }
    if value % ZC_WAL_RECORD_SIZE != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{side_name} transport frame bytes must be a multiple of {ZC_WAL_RECORD_SIZE}"),
        ));
    }
    if value > u32::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{side_name} transport frame bytes must fit in u32"),
        ));
    }
    if value > bytes_per_connection {
        eprintln!(
            "PERF WARNING: {side_name} transport frame bytes {value} exceeds bytes_per_connection={bytes_per_connection}; clamping to connection length"
        );
    }
    if value % extent_bytes != 0 && extent_bytes % value != 0 {
        eprintln!(
            "PERF WARNING: {side_name} transport frame bytes {value} is not aligned with logical extent_bytes={extent_bytes}; benchmark accounting remains correct, but WAL extent/frame boundaries are harder to reason about"
        );
    }
    Ok(value.min(bytes_per_connection))
}

fn zcwal_uring_send_bytes(extent_bytes: usize, bytes_per_connection: usize) -> io::Result<usize> {
    zcwal_uring_chunk_from_env(
        "zcwal send",
        "URING_PLAY_ZCWAL_SEND_BYTES",
        extent_bytes,
        bytes_per_connection,
        extent_bytes,
    )
}

fn zcwal_uring_recv_bytes_for_stream(
    extent_bytes: usize,
    bytes_per_connection: usize,
) -> io::Result<usize> {
    zcwal_uring_chunk_from_env(
        "zcwal recv",
        "URING_PLAY_ZCWAL_RECV_BYTES",
        extent_bytes,
        bytes_per_connection,
        extent_bytes.min(4 * 1024 * 1024).max(4096),
    )
}

fn zcwal_sync_acks() -> bool {
    env_enabled_or("URING_PLAY_ZCWAL_SYNC_ACKS", false)
}

fn zcwal_extent_partition_accepted_streams(
    streams: Vec<TcpBenchAcceptedStream>,
    workers: usize,
    policy: TcpMuxShardPolicy,
    label: &str,
) -> Vec<Vec<ZcWalExtentAcceptedStream>> {
    let mut shards = (0..workers).map(|_| Vec::new()).collect::<Vec<_>>();
    let mut counts = vec![0usize; workers];
    for (idx, accepted) in streams.into_iter().enumerate() {
        let worker = policy.choose_worker(&accepted, idx, workers);
        println!(
            "{label}-mux-assignment: worker={worker} policy={} peer={} listener_lane={} \
             listener_port={} conn={} {}",
            policy.label(),
            accepted.peer_addr,
            accepted.lane,
            accepted.port,
            accepted.conn_index,
            socket_locality_label(accepted.locality)
        );
        counts[worker] += 1;
        shards[worker].push(ZcWalExtentAcceptedStream {
            meta: accepted.meta(),
            stream: accepted.stream,
        });
    }
    println!(
        "{label}-mux-assignment-summary: policy={} workers={workers} streams_by_worker={}",
        policy.label(),
        tcp_mux_counts_label(&counts)
    );
    shards
}

fn zcwal_extent_sender_worker(
    worker: usize,
    addr: Arc<String>,
    specs: Vec<TcpBenchConnectSpec>,
    lane_count: usize,
    bytes_per_connection: usize,
    extent_bytes: usize,
    send_bytes: usize,
    framing_mode: ZcWalFramingMode,
    data_path: ZcWalDataPath,
    ack_enabled: bool,
    ready_barrier: Arc<Barrier>,
    start_barrier: Arc<Barrier>,
) -> io::Result<ZcWalExtentStats> {
    let affinity = maybe_pin_current_thread("zcwal-extent-send-worker", worker);
    let tid = current_tid();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let start_cpu = current_cpu();
    let start_switches = read_thread_context_switches(tid).unwrap_or_default();
    let mut streams = Vec::with_capacity(specs.len());
    for spec in &specs {
        let stream =
            tcp_bench_connect(addr.as_str(), spec.port, spec.source_port).map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!(
                        "zcwal extent connect {}:{} lane={} conn={}: {err}",
                        addr.as_str(),
                        spec.port,
                        spec.lane,
                        spec.conn_index
                    ),
                )
            })?;
        set_tcp_nodelay_from_env(&stream)?;
        set_tcp_bench_buffers(&stream);
        println!(
            "zcwal-extent-send-stream: worker={worker} lane={} port={} conn={}",
            spec.lane, spec.port, spec.conn_index
        );
        streams.push((*spec, stream));
    }

    let mut payload = vec![0u8; extent_bytes];
    SendPayloadPattern::from_env(extent_bytes)?.fill(&mut payload);
    let record_count = u32::try_from(extent_bytes / ZC_WAL_RECORD_SIZE).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "WAL extent record count overflow",
        )
    })?;
    let extents_per_stream = bytes_per_connection / extent_bytes;

    ready_barrier.wait();
    start_barrier.wait();
    let started = Instant::now();
    let mut payload_bytes = 0usize;
    let mut wire_bytes = 0usize;
    let mut extents = 0usize;
    let mut records = 0usize;
    let mut acks = 0usize;
    let sync_acks = ack_enabled && zcwal_sync_acks();
    let mut ack_buf = [0u8; ZC_WAL_ACK_HEADER_LEN];
    let mut ack_latency = LatencyHistogram::new();

    for (spec, mut stream) in streams {
        match framing_mode {
            ZcWalFramingMode::Extent => {
                for seq in 0..extents_per_stream {
                    let issued_at = sync_acks.then(Instant::now);
                    let base_logical_index = (seq * record_count as usize) as u64;
                    let header = ZcWalExtentHeader {
                        flags: 0,
                        lane_id: spec.lane as u32,
                        lane_count: lane_count as u32,
                        shard_id: spec.lane as u32,
                        record_size: ZC_WAL_RECORD_SIZE as u32,
                        record_count,
                        payload_len: extent_bytes as u32,
                        table_len: 0,
                        base_logical_index,
                        extent_sequence: seq as u64,
                        base_wal_offset: (seq * extent_bytes) as u64,
                        wal_epoch: 0,
                        descriptor_id: ((spec.lane as u64) << 32) | seq as u64,
                        payload_crc32c: 0,
                    }
                    .encode();
                    let mut bufs = [IoSlice::new(&header), IoSlice::new(&payload)];
                    tcp_write_all_vectored(&mut stream, &mut bufs, "WAL extent TCP send")?;
                    payload_bytes += extent_bytes;
                    wire_bytes += ZC_WAL_EXTENT_HEADER_LEN + extent_bytes;
                    extents += 1;
                    records += record_count as usize;

                    if sync_acks {
                        stream.read_exact(&mut ack_buf)?;
                        let ack = ZcWalAckHeader::decode(&ack_buf)?;
                        if ack.status != 0
                            || ack.lane_id as usize != spec.lane
                            || ack.extent_sequence != seq as u64
                            || ack.record_size != ZC_WAL_RECORD_SIZE as u32
                        {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "WAL extent ack mismatch lane={} seq={} got lane={} seq={} status={}",
                                    spec.lane, seq, ack.lane_id, ack.extent_sequence, ack.status
                                ),
                            ));
                        }
                        if let Some(issued_at) = issued_at {
                            ack_latency.record_duration(issued_at.elapsed());
                        }
                        acks += 1;
                    }
                }
                stream.shutdown(Shutdown::Write)?;

                if ack_enabled && !sync_acks {
                    for seq in 0..extents_per_stream {
                        stream.read_exact(&mut ack_buf)?;
                        let ack = ZcWalAckHeader::decode(&ack_buf)?;
                        if ack.status != 0
                            || ack.lane_id as usize != spec.lane
                            || ack.extent_sequence != seq as u64
                            || ack.record_size != ZC_WAL_RECORD_SIZE as u32
                        {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "WAL extent ack mismatch lane={} seq={} got lane={} seq={} status={}",
                                    spec.lane, seq, ack.lane_id, ack.extent_sequence, ack.status
                                ),
                            ));
                        }
                        acks += 1;
                    }
                }
            }
            ZcWalFramingMode::Stream => {
                let total_records = u32::try_from(bytes_per_connection / ZC_WAL_RECORD_SIZE)
                    .map_err(|_| {
                        io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "stream-framed WAL record count overflow",
                        )
                    })?;
                let issued_at = ack_enabled.then(Instant::now);
                let header = ZcWalExtentHeader {
                    flags: ZC_WAL_EXTENT_F_STREAM_FRAME,
                    lane_id: spec.lane as u32,
                    lane_count: lane_count as u32,
                    shard_id: spec.lane as u32,
                    record_size: ZC_WAL_RECORD_SIZE as u32,
                    record_count: total_records,
                    payload_len: bytes_per_connection as u32,
                    table_len: 0,
                    base_logical_index: 0,
                    extent_sequence: 0,
                    base_wal_offset: 0,
                    wal_epoch: 0,
                    descriptor_id: (spec.lane as u64) << 32,
                    payload_crc32c: 0,
                }
                .encode();
                stream.write_all(&header)?;
                match data_path {
                    ZcWalDataPath::Blocking => {
                        let mut remaining = bytes_per_connection;
                        while remaining != 0 {
                            let len = remaining.min(payload.len());
                            stream.write_all(&payload[..len])?;
                            remaining -= len;
                        }
                        stream.shutdown(Shutdown::Write)?;
                        if ack_enabled {
                            stream.read_exact(&mut ack_buf)?;
                            let ack = ZcWalAckHeader::decode(&ack_buf)?;
                            if ack.status != 0
                                || ack.lane_id as usize != spec.lane
                                || ack.extent_sequence != 0
                                || ack.record_size != ZC_WAL_RECORD_SIZE as u32
                            {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    format!(
                                        "stream-framed WAL ack mismatch lane={} got lane={} seq={} status={}",
                                        spec.lane, ack.lane_id, ack.extent_sequence, ack.status
                                    ),
                                ));
                            }
                            if let Some(issued_at) = issued_at {
                                ack_latency.record_duration(issued_at.elapsed());
                            }
                            acks += 1;
                        }
                    }
                    ZcWalDataPath::Uring => {
                        let mut ack_stream = if ack_enabled {
                            Some(stream.try_clone()?)
                        } else {
                            None
                        };
                        let uring_stats = uring_send_worker(
                            worker,
                            affinity,
                            vec![stream],
                            bytes_per_connection,
                            send_bytes,
                            zcwal_uring_pipeline(),
                            zcwal_uring_entries(),
                            UringSendMode::Send,
                            SendPayloadPattern::from_env(send_bytes)?,
                            false,
                        )?;
                        if uring_stats.bytes != bytes_per_connection {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "stream-framed WAL uring sender wrote {} bytes, expected {bytes_per_connection}",
                                    uring_stats.bytes
                                ),
                            ));
                        }
                        if let Some(ack_stream) = ack_stream.as_mut() {
                            ack_stream.read_exact(&mut ack_buf)?;
                            let ack = ZcWalAckHeader::decode(&ack_buf)?;
                            if ack.status != 0
                                || ack.lane_id as usize != spec.lane
                                || ack.extent_sequence != 0
                                || ack.record_size != ZC_WAL_RECORD_SIZE as u32
                            {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    format!(
                                        "stream-framed WAL ack mismatch lane={} got lane={} seq={} status={}",
                                        spec.lane, ack.lane_id, ack.extent_sequence, ack.status
                                    ),
                                ));
                            }
                            if let Some(issued_at) = issued_at {
                                ack_latency.record_duration(issued_at.elapsed());
                            }
                            acks += 1;
                        }
                    }
                }
                payload_bytes += bytes_per_connection;
                wire_bytes += ZC_WAL_EXTENT_HEADER_LEN + bytes_per_connection;
                extents += extents_per_stream;
                records += total_records as usize;
            }
        }
    }

    let end_thread_cpu = thread_cpu_time().unwrap_or(start_thread_cpu);
    let end_cpu = current_cpu();
    let end_switches = read_thread_context_switches(tid).unwrap_or(start_switches);
    Ok(ZcWalExtentStats {
        worker,
        streams: specs.len(),
        payload_bytes,
        wire_bytes,
        extents,
        records,
        acks,
        wall: started.elapsed(),
        cpu: end_thread_cpu.saturating_sub(start_thread_cpu),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        voluntary_switches: end_switches
            .voluntary
            .saturating_sub(start_switches.voluntary),
        involuntary_switches: end_switches
            .involuntary
            .saturating_sub(start_switches.involuntary),
        migrations: end_switches
            .migrations
            .saturating_sub(start_switches.migrations),
        ack_latency,
        uring_recv: UringRecvStats::default(),
    })
}

fn zcwal_extent_recv_worker(
    worker: usize,
    streams: Vec<ZcWalExtentAcceptedStream>,
    lane_count: usize,
    bytes_per_connection: usize,
    extent_bytes: usize,
    recv_bytes: usize,
    framing_mode: ZcWalFramingMode,
    data_path: ZcWalDataPath,
    ack_enabled: bool,
) -> io::Result<ZcWalExtentStats> {
    let affinity = maybe_pin_current_thread("zcwal-extent-recv-worker", worker);
    let tid = current_tid();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let start_cpu = current_cpu();
    let start_switches = read_thread_context_switches(tid).unwrap_or_default();
    let stream_count = streams.len();
    let mut payload = vec![0u8; extent_bytes];
    let extents_per_stream = bytes_per_connection / extent_bytes;
    let mut payload_bytes = 0usize;
    let mut wire_bytes = 0usize;
    let mut extents = 0usize;
    let mut records = 0usize;
    let mut acks = 0usize;
    let mut uring_recv = UringRecvStats::default();
    let started = Instant::now();

    for accepted in streams {
        let meta = accepted.meta;
        let mut stream = accepted.stream;
        match framing_mode {
            ZcWalFramingMode::Extent => {
                let mut expected_logical = 0u64;
                for expected_seq in 0..extents_per_stream {
                    let mut header_buf = [0u8; ZC_WAL_EXTENT_HEADER_LEN];
                    stream.read_exact(&mut header_buf)?;
                    let header = ZcWalExtentHeader::decode(&header_buf)?;
                    if header.flags & ZC_WAL_EXTENT_F_STREAM_FRAME != 0
                        || header.lane_id as usize != meta.lane
                        || header.lane_count as usize != lane_count
                        || header.shard_id != header.lane_id
                        || header.record_size != ZC_WAL_RECORD_SIZE as u32
                        || header.payload_len as usize != extent_bytes
                        || header.record_count as usize != extent_bytes / ZC_WAL_RECORD_SIZE
                        || header.table_len != 0
                        || header.extent_sequence != expected_seq as u64
                        || header.base_logical_index != expected_logical
                    {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!(
                                "WAL extent header mismatch stream_lane={} seq={} got flags=0x{:x} lane={} lane_count={} shard={} records={} payload={} table={} base={} seq={}",
                                meta.lane,
                                expected_seq,
                                header.flags,
                                header.lane_id,
                                header.lane_count,
                                header.shard_id,
                                header.record_count,
                                header.payload_len,
                                header.table_len,
                                header.base_logical_index,
                                header.extent_sequence
                            ),
                        ));
                    }
                    stream.read_exact(&mut payload)?;
                    payload_bytes += extent_bytes;
                    wire_bytes += ZC_WAL_EXTENT_HEADER_LEN + extent_bytes;
                    extents += 1;
                    records += header.record_count as usize;
                    expected_logical += header.record_count as u64;

                    if ack_enabled {
                        let first = header.base_logical_index;
                        let last = first + header.record_count as u64 - 1;
                        let ack = ZcWalAckHeader {
                            lane_id: header.lane_id,
                            shard_id: header.shard_id,
                            status: 0,
                            record_size: header.record_size,
                            first_logical_index: first,
                            last_logical_index: last,
                            extent_sequence: header.extent_sequence,
                            durable_wal_offset: header.base_wal_offset,
                        }
                        .encode();
                        stream.write_all(&ack)?;
                        acks += 1;
                    }
                }
            }
            ZcWalFramingMode::Stream => {
                let mut header_buf = [0u8; ZC_WAL_EXTENT_HEADER_LEN];
                stream.read_exact(&mut header_buf)?;
                let header = ZcWalExtentHeader::decode(&header_buf)?;
                let expected_records = bytes_per_connection / ZC_WAL_RECORD_SIZE;
                if header.flags & ZC_WAL_EXTENT_F_STREAM_FRAME == 0
                    || header.lane_id as usize != meta.lane
                    || header.lane_count as usize != lane_count
                    || header.shard_id != header.lane_id
                    || header.record_size != ZC_WAL_RECORD_SIZE as u32
                    || header.payload_len as usize != bytes_per_connection
                    || header.record_count as usize != expected_records
                    || header.table_len != 0
                    || header.extent_sequence != 0
                    || header.base_logical_index != 0
                {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        format!(
                            "stream-framed WAL header mismatch stream_lane={} got flags=0x{:x} lane={} lane_count={} shard={} records={} payload={} table={} base={} seq={}",
                            meta.lane,
                            header.flags,
                            header.lane_id,
                            header.lane_count,
                            header.shard_id,
                            header.record_count,
                            header.payload_len,
                            header.table_len,
                            header.base_logical_index,
                            header.extent_sequence
                        ),
                    ));
                }
                match data_path {
                    ZcWalDataPath::Blocking => {
                        let mut remaining = bytes_per_connection;
                        while remaining != 0 {
                            let len = remaining.min(payload.len());
                            stream.read_exact(&mut payload[..len])?;
                            remaining -= len;
                        }
                        if ack_enabled {
                            let ack = ZcWalAckHeader {
                                lane_id: header.lane_id,
                                shard_id: header.shard_id,
                                status: 0,
                                record_size: header.record_size,
                                first_logical_index: 0,
                                last_logical_index: header.record_count as u64 - 1,
                                extent_sequence: 0,
                                durable_wal_offset: 0,
                            }
                            .encode();
                            stream.write_all(&ack)?;
                            acks += 1;
                        }
                    }
                    ZcWalDataPath::Uring => {
                        let mut ack_stream = if ack_enabled {
                            Some(stream.try_clone()?)
                        } else {
                            None
                        };
                        let recv_stats = uring_recv_worker(
                            vec![stream],
                            bytes_per_connection,
                            recv_bytes,
                            zcwal_uring_entries(),
                        )?;
                        if recv_stats.bytes != bytes_per_connection {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "stream-framed WAL uring receiver read {} bytes, expected {bytes_per_connection}",
                                    recv_stats.bytes
                                ),
                            ));
                        }
                        uring_recv.merge(&recv_stats);
                        if let Some(ack_stream) = ack_stream.as_mut() {
                            let ack = ZcWalAckHeader {
                                lane_id: header.lane_id,
                                shard_id: header.shard_id,
                                status: 0,
                                record_size: header.record_size,
                                first_logical_index: 0,
                                last_logical_index: header.record_count as u64 - 1,
                                extent_sequence: 0,
                                durable_wal_offset: 0,
                            }
                            .encode();
                            ack_stream.write_all(&ack)?;
                            acks += 1;
                        }
                    }
                }
                payload_bytes += bytes_per_connection;
                wire_bytes += ZC_WAL_EXTENT_HEADER_LEN + bytes_per_connection;
                extents += extents_per_stream;
                records += expected_records;
            }
        }
    }

    let end_thread_cpu = thread_cpu_time().unwrap_or(start_thread_cpu);
    let end_cpu = current_cpu();
    let end_switches = read_thread_context_switches(tid).unwrap_or(start_switches);
    Ok(ZcWalExtentStats {
        worker,
        streams: stream_count,
        payload_bytes,
        wire_bytes,
        extents,
        records,
        acks,
        wall: started.elapsed(),
        cpu: end_thread_cpu.saturating_sub(start_thread_cpu),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        voluntary_switches: end_switches
            .voluntary
            .saturating_sub(start_switches.voluntary),
        involuntary_switches: end_switches
            .involuntary
            .saturating_sub(start_switches.involuntary),
        migrations: end_switches
            .migrations
            .saturating_sub(start_switches.migrations),
        ack_latency: LatencyHistogram::new(),
        uring_recv,
    })
}

fn zcwal_extent_print_worker(label: &str, stats: &ZcWalExtentStats) {
    let secs = stats.wall.as_secs_f64().max(f64::MIN_POSITIVE);
    let cpu_secs = stats.cpu.as_secs_f64();
    println!(
        "{label}-worker: worker={} streams={} payload_bytes={} wire_bytes={} extents={} \
         logical_records={} acks={} seconds={secs:.6} payload_Gbitps={:.3} \
         logical_iops={:.0} thread_cpu_seconds={cpu_secs:.6} cpu_wall_pct={:.1} \
         target_cpu={} affinity_applied={} start_cpu={} end_cpu={} \
         voluntary_ctxt_switches={} involuntary_ctxt_switches={} migrations={}",
        stats.worker,
        stats.streams,
        stats.payload_bytes,
        stats.wire_bytes,
        stats.extents,
        stats.records,
        stats.acks,
        stats.payload_bytes as f64 * 8.0 / 1_000_000_000.0 / secs,
        stats.records as f64 / secs,
        cpu_secs / secs * 100.0,
        stats.target_cpu,
        stats.affinity_applied,
        stats.start_cpu,
        stats.end_cpu,
        stats.voluntary_switches,
        stats.involuntary_switches,
        stats.migrations,
    );
    if stats.ack_latency.count != 0 {
        println!(
            "{label}-worker-latency: worker={} {}",
            stats.worker,
            zcwal_extent_latency_fields("ack", &stats.ack_latency)
        );
    }
    if stats.uring_recv.data_cqes != 0 {
        println!(
            "{label}-worker-uring-recv: worker={} bytes={} data_cqes={} avg_cqe_len={} \
             min_cqe_len={} max_cqe_len={} full_chunk_cqes={} partial_cqes={} \
             ring_sqes_queued={} ring_sqes_submitted={} ring_submit_syscalls={} \
             ring_wait_cqe_calls={} ring_wait_syscalls={} ring_cqes_popped={} \
             ring_try_pop_empty={} ring_cqe_spin_loops={} ring_cqe_hot_poll_waits={} \
             ring_cqe_adaptive_grows={} ring_cqe_adaptive_shrinks={} \
             ring_cqe_adaptive_spin_max_seen={} ring_submit_short={}",
            stats.worker,
            stats.uring_recv.bytes,
            stats.uring_recv.data_cqes,
            stats.uring_recv.avg_cqe_len(),
            stats.uring_recv.min_cqe_len,
            stats.uring_recv.max_cqe_len,
            stats.uring_recv.full_chunk_cqes,
            stats.uring_recv.partial_cqes,
            stats.uring_recv.ring.sqes_queued,
            stats.uring_recv.ring.sqes_submitted,
            stats.uring_recv.ring.submit_syscalls,
            stats.uring_recv.ring.wait_cqe_calls,
            stats.uring_recv.ring.wait_syscalls,
            stats.uring_recv.ring.cqes_popped,
            stats.uring_recv.ring.try_pop_empty,
            stats.uring_recv.ring.cqe_spin_loops,
            stats.uring_recv.ring.cqe_hot_poll_waits,
            stats.uring_recv.ring.cqe_adaptive_grows,
            stats.uring_recv.ring.cqe_adaptive_shrinks,
            stats.uring_recv.ring.cqe_adaptive_spin_max_seen,
            stats.uring_recv.ring.submit_short,
        );
    }
}

fn zcwal_extent_latency_fields(prefix: &str, latency: &LatencyHistogram) -> String {
    format!(
        "{prefix}_count={} {prefix}_avg_ns={} {prefix}_min_ns={} \
         {prefix}_p50_ns={} {prefix}_p95_ns={} {prefix}_p99_ns={} \
         {prefix}_p999_ns={} {prefix}_max_ns={}",
        latency.count,
        latency.avg_ns(),
        latency.min_ns(),
        latency.percentile_ns(50, 100),
        latency.percentile_ns(95, 100),
        latency.percentile_ns(99, 100),
        latency.percentile_ns(999, 1000),
        latency.max_ns(),
    )
}

fn zcwal_extent_sum(results: &[ZcWalExtentStats]) -> ZcWalExtentStats {
    let mut total = ZcWalExtentStats::default();
    for stats in results {
        total.streams += stats.streams;
        total.payload_bytes += stats.payload_bytes;
        total.wire_bytes += stats.wire_bytes;
        total.extents += stats.extents;
        total.records += stats.records;
        total.acks += stats.acks;
        total.wall = total.wall.max(stats.wall);
        total.cpu += stats.cpu;
        total.voluntary_switches += stats.voluntary_switches;
        total.involuntary_switches += stats.involuntary_switches;
        total.migrations += stats.migrations;
        total.ack_latency.merge(&stats.ack_latency);
        total.uring_recv.merge(&stats.uring_recv);
    }
    total
}

fn zcwal_extent_perf_warnings(
    label: &str,
    lanes: usize,
    connections_per_lane: usize,
    workers: usize,
) -> io::Result<()> {
    if !env_truthy("URING_PLAY_PIN_CPUS") {
        zc_topology_issue(
            label,
            "running without URING_PLAY_PIN_CPUS=1; lane/CPU topology is not pinned",
        )?;
    }
    if env::var("URING_PLAY_PIN_CPU_LIST")
        .map(|value| value.trim().is_empty())
        .unwrap_or(true)
    {
        zc_topology_issue(
            label,
            "running without URING_PLAY_PIN_CPU_LIST; state the lane-to-CPU map for real IOPS numbers",
        )?;
    }
    if workers < lanes {
        zc_topology_issue(
            label,
            format!("workers={workers} lanes={lanes}; at least one worker will own multiple lanes"),
        )?;
    }
    if connections_per_lane != 1 {
        zc_topology_issue(
            label,
            format!(
                "connections_per_lane={connections_per_lane}; lane-locality is easiest to interpret with one connection per lane"
            ),
        )?;
    }
    Ok(())
}

fn zcofi_rma_perf_warnings(label: &str, lanes: usize, workers: usize) -> io::Result<()> {
    if !env_truthy("URING_PLAY_PIN_CPUS") {
        zc_topology_issue(
            label,
            "running without URING_PLAY_PIN_CPUS=1; lane/CPU topology is not pinned",
        )?;
    }
    if env::var("URING_PLAY_PIN_CPU_LIST")
        .map(|value| value.trim().is_empty())
        .unwrap_or(true)
    {
        zc_topology_issue(
            label,
            "running without URING_PLAY_PIN_CPU_LIST; state the lane-to-CPU map for real IOPS numbers",
        )?;
    }
    if workers < lanes {
        println!(
            "{label}-topology: workers={workers} lanes={lanes} multi_lane_workers=yes scheduling=event-driven-interleave representative_eligible=yes"
        );
    }
    Ok(())
}

fn zcofi_estimated_registered_bytes(
    lane_count: usize,
    endpoints_per_lane: usize,
    message_bytes: usize,
) -> io::Result<usize> {
    let tx_depth = env_usize_or("URING_PLAY_OFI_TX_QUEUE_DEPTH", 64).max(1);
    let rx_depth = env_usize_or("URING_PLAY_OFI_RX_QUEUE_DEPTH", 64).max(1);
    let read_depth = env_usize_or("URING_PLAY_OFI_RMA_READ_QD", 1).max(1);
    let write_depth = env_usize_or("URING_PLAY_OFI_RMA_WRITE_QD", 1).max(1);
    let slots = tx_depth
        .checked_add(rx_depth)
        .and_then(|depth| depth.checked_add(read_depth))
        .and_then(|depth| depth.checked_add(write_depth))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "OFI queue depth overflow"))?;
    lane_count
        .checked_mul(endpoints_per_lane.max(1))
        .and_then(|count| count.checked_mul(slots))
        .and_then(|count| count.checked_mul(message_bytes.max(ZC_WAL_ACK_HEADER_LEN)))
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "OFI registered-memory estimate overflow",
            )
        })
}

fn zcofi_registered_working_set(
    label: &str,
    lane_count: usize,
    bytes_per_lane: usize,
) -> io::Result<usize> {
    lane_count.checked_mul(bytes_per_lane).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{label} registered working-set size overflow"),
        )
    })
}

fn zcofi_perf_contract_warnings(
    label: &str,
    provider: &str,
    lane_count: usize,
    endpoints_per_lane: usize,
    message_bytes: usize,
    minimum_registered_bytes: usize,
    domain_mapping_explicit: bool,
) -> io::Result<()> {
    let cq_sleep_ns = env_usize_or("URING_PLAY_OFI_CQ_SLEEP_NS", 50_000);
    if cq_sleep_ns != 0 {
        zc_topology_issue(
            label,
            format!(
                "URING_PLAY_OFI_CQ_SLEEP_NS={cq_sleep_ns}; representative low-latency OFI runs require a non-sleeping CQ progress loop"
            ),
        )?;
    }
    let efa = provider == "efa" || provider == "efa-direct";
    if !efa {
        return Ok(());
    }
    if !domain_mapping_explicit {
        zc_topology_issue(
            label,
            "EFA lane-to-NIC/domain mapping is implicit; set URING_PLAY_OFI_DOMAIN or provide every branch fabric_domain in the zcplan topology",
        )?;
    }
    if env::var("FI_EFA_IFACE")
        .map(|value| value.trim().is_empty())
        .unwrap_or(true)
    {
        zc_topology_issue(
            label,
            "FI_EFA_IFACE is unset; explicitly name the EFA NIC(s) before treating lane/domain locality as representative",
        )?;
    }
    if env::var("FI_EFA_USE_HUGE_PAGE")
        .map(|value| matches!(value.trim(), "0" | "false" | "no" | "off"))
        .unwrap_or(false)
    {
        zc_topology_issue(
            label,
            "FI_EFA_USE_HUGE_PAGE disables the provider huge-page path",
        )?;
    }
    let queue_estimate =
        zcofi_estimated_registered_bytes(lane_count, endpoints_per_lane, message_bytes)?;
    let estimated = queue_estimate.max(minimum_registered_bytes);
    let (huge_total, huge_free, huge_size) = hugepage_meminfo()?;
    let needed_pages = estimated.div_ceil(huge_size.max(1));
    let memlock_limit = memlock_rlimit_bytes()?;
    println!(
        "{label}-memory-preflight: queue_registered_estimate_bytes={queue_estimate} minimum_working_set_registered_bytes={minimum_registered_bytes} conservative_registered_bytes={estimated} hugepages_total={huge_total} hugepages_free={huge_free} hugepage_size_bytes={huge_size} needed_hugepages={needed_pages} memlock_bytes={}",
        memlock_limit
            .map(|limit| limit.to_string())
            .unwrap_or_else(|| "unlimited".to_string()),
    );
    if huge_total == 0 || huge_free < needed_pages {
        zc_topology_issue(
            label,
            format!(
                "hugetlb headroom is insufficient for the conservative registered-arena estimate: estimated={} needed_pages={needed_pages} HugePages_Free={huge_free} HugePages_Total={huge_total} Hugepagesize={}",
                format_mib(estimated),
                format_mib(huge_size),
            ),
        )?;
    }
    if let Some(limit) = memlock_limit
        && limit < estimated as u64
    {
        zc_topology_issue(
            label,
            format!(
                "RLIMIT_MEMLOCK={} is below the conservative registered-arena estimate={}",
                format_mib(limit as usize),
                format_mib(estimated),
            ),
        )?;
    }
    Ok(())
}

fn zcofi_print_lane_worker_cpu_map(label: &str, lanes: &[usize], workers: usize, domain: &str) {
    let workers = workers.max(1);
    for &lane in lanes {
        let worker = lane % workers;
        let cpu = affinity_target_cpu(worker)
            .map(|cpu| cpu.to_string())
            .unwrap_or_else(|| "unpinned".to_string());
        println!(
            "{label}-lane-map: lane={lane} worker={worker} cpu={cpu} domain={domain} scheduling={} aggregate_mapping_declared=yes",
            if workers < lanes.len() {
                "multi-lane-worker"
            } else {
                "one-worker-per-lane"
            },
        );
    }
}

fn zcofi_queue_depth_preflight(
    label: &str,
    required_tx: usize,
    required_rx: usize,
) -> io::Result<()> {
    let tx_depth = env_usize_or("URING_PLAY_OFI_TX_QUEUE_DEPTH", 64).max(1);
    let rx_depth = env_usize_or("URING_PLAY_OFI_RX_QUEUE_DEPTH", 64).max(1);
    if tx_depth < required_tx {
        zc_topology_issue(
            label,
            format!(
                "OFI TX ring depth={tx_depth} is below the protocol window={required_tx}; completions will force early credit recycling"
            ),
        )?;
    }
    if rx_depth < required_rx {
        zc_topology_issue(
            label,
            format!(
                "OFI RX ring depth={rx_depth} is below the required preposted window={required_rx}"
            ),
        )?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn zcwal_extent_send(
    addr: &str,
    base_port: u16,
    lanes: usize,
    connections_per_lane: usize,
    bytes_per_connection: usize,
    extent_bytes: usize,
    workers: usize,
    framing_mode: ZcWalFramingMode,
    data_path: ZcWalDataPath,
    ack_enabled: bool,
) -> io::Result<()> {
    zcwal_validate_framing_shape(framing_mode, bytes_per_connection, extent_bytes)?;
    let data_path = if framing_mode == ZcWalFramingMode::Extent {
        ZcWalDataPath::Blocking
    } else {
        data_path
    };
    let total_connections = tcp_bench_total_connections(lanes, connections_per_lane)?;
    let workers = tcp_bench_auto_workers(workers, total_connections);
    zcwal_extent_perf_warnings("zcwal-extent-send", lanes, connections_per_lane, workers)?;
    let source_ports = TcpSourcePortPlan::from_env()?;
    let send_bytes =
        if framing_mode == ZcWalFramingMode::Stream && data_path == ZcWalDataPath::Uring {
            zcwal_uring_send_bytes(extent_bytes, bytes_per_connection)?
        } else {
            extent_bytes
        };
    println!(
        "zcwal-extent-send: addr={addr} base_port={base_port} lanes={lanes} \
         connections_per_lane={connections_per_lane} total_connections={total_connections} \
         bytes_per_connection={bytes_per_connection} extent_bytes={extent_bytes} \
         record_size={ZC_WAL_RECORD_SIZE} records_per_extent={} workers={workers} \
         framing={} data_path={} ack_enabled={} sync_acks={} tcp_nodelay={} socket_buffer_bytes={} \
         uring_send_bytes={} uring_pipeline={} uring_entries={} source_ports={}",
        extent_bytes / ZC_WAL_RECORD_SIZE,
        framing_mode.label(),
        data_path.label(),
        yes(ack_enabled),
        yes(zcwal_sync_acks()),
        yes(tcp_nodelay_enabled()),
        socket_bench_buffer_bytes(),
        send_bytes,
        zcwal_uring_pipeline(),
        zcwal_uring_entries(),
        source_ports.label()
    );
    let specs = tcp_bench_mux_connect_specs(base_port, lanes, connections_per_lane, source_ports)?;
    let shards = tcp_bench_partition_connect_specs(specs, workers);
    let active_workers = shards.iter().filter(|shard| !shard.is_empty()).count();
    let ready_barrier = Arc::new(Barrier::new(active_workers + 1));
    let start_barrier = Arc::new(Barrier::new(active_workers + 1));
    let addr = Arc::new(addr.to_string());
    let mut handles = Vec::with_capacity(active_workers);
    for (worker, shard) in shards.into_iter().enumerate() {
        if shard.is_empty() {
            continue;
        }
        let addr = Arc::clone(&addr);
        let ready_barrier = Arc::clone(&ready_barrier);
        let start_barrier = Arc::clone(&start_barrier);
        handles.push(thread::spawn(move || {
            zcwal_extent_sender_worker(
                worker,
                addr,
                shard,
                lanes,
                bytes_per_connection,
                extent_bytes,
                send_bytes,
                framing_mode,
                data_path,
                ack_enabled,
                ready_barrier,
                start_barrier,
            )
        }));
    }
    ready_barrier.wait();
    let started = Instant::now();
    start_barrier.wait();
    let mut results = Vec::with_capacity(handles.len());
    for handle in handles {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other("zcwal extent send worker panicked"))??;
        zcwal_extent_print_worker("zcwal-extent-send", &stats);
        results.push(stats);
    }
    let mut total = zcwal_extent_sum(&results);
    total.wall = total.wall.max(started.elapsed());
    let secs = total.wall.as_secs_f64().max(f64::MIN_POSITIVE);
    println!(
        "zcwal-extent-send-summary: payload_bytes={} wire_bytes={} extents={} \
         logical_records={} acks={} seconds={secs:.6} payload_Gbitps={:.3} \
         logical_iops={:.0}",
        total.payload_bytes,
        total.wire_bytes,
        total.extents,
        total.records,
        total.acks,
        total.payload_bytes as f64 * 8.0 / 1_000_000_000.0 / secs,
        total.records as f64 / secs
    );
    if total.ack_latency.count != 0 {
        println!(
            "zcwal-extent-send-latency-summary: {}",
            zcwal_extent_latency_fields("ack", &total.ack_latency)
        );
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn zcwal_extent_recv(
    bind: &str,
    base_port: u16,
    lanes: usize,
    connections_per_lane: usize,
    bytes_per_connection: usize,
    extent_bytes: usize,
    workers: usize,
    framing_mode: ZcWalFramingMode,
    data_path: ZcWalDataPath,
    ack_enabled: bool,
) -> io::Result<()> {
    zcwal_validate_framing_shape(framing_mode, bytes_per_connection, extent_bytes)?;
    let data_path = if framing_mode == ZcWalFramingMode::Extent {
        ZcWalDataPath::Blocking
    } else {
        data_path
    };
    let total_connections = tcp_bench_total_connections(lanes, connections_per_lane)?;
    let workers = tcp_bench_auto_workers(workers, total_connections);
    zcwal_extent_perf_warnings("zcwal-extent-recv", lanes, connections_per_lane, workers)?;
    let recv_bytes =
        if framing_mode == ZcWalFramingMode::Stream && data_path == ZcWalDataPath::Uring {
            zcwal_uring_recv_bytes_for_stream(extent_bytes, bytes_per_connection)?
        } else {
            extent_bytes
        };
    println!(
        "zcwal-extent-recv: bind={bind} base_port={base_port} lanes={lanes} \
         connections_per_lane={connections_per_lane} total_connections={total_connections} \
         bytes_per_connection={bytes_per_connection} extent_bytes={extent_bytes} \
         record_size={ZC_WAL_RECORD_SIZE} records_per_extent={} workers={workers} \
         framing={} data_path={} ack_enabled={} socket_buffer_bytes={} \
         uring_recv_bytes={} uring_recv_pipeline={} uring_entries={} cqe_spin={} cqe_adaptive_spin={} \
         cqe_adaptive_spin_min={} cqe_adaptive_spin_max={} cqe_adaptive_wait_ns={} \
         cqe_hot_poll={} enter_no_iowait={}",
        extent_bytes / ZC_WAL_RECORD_SIZE,
        framing_mode.label(),
        data_path.label(),
        yes(ack_enabled),
        socket_bench_buffer_bytes(),
        recv_bytes,
        zcwal_uring_recv_pipeline(),
        zcwal_uring_entries(),
        env_usize_or("URING_PLAY_CQE_SPIN", 0),
        yes(env_enabled_or("URING_PLAY_CQE_ADAPTIVE_SPIN", false)),
        env_usize_or(
            "URING_PLAY_CQE_ADAPTIVE_SPIN_MIN",
            if env_usize_or("URING_PLAY_CQE_SPIN", 0) == 0 {
                64
            } else {
                env_usize_or("URING_PLAY_CQE_SPIN", 0)
            },
        ),
        env_usize_or(
            "URING_PLAY_CQE_ADAPTIVE_SPIN_MAX",
            if env_usize_or("URING_PLAY_CQE_SPIN", 0) == 0 {
                4096
            } else {
                env_usize_or("URING_PLAY_CQE_SPIN", 0).saturating_mul(8)
            },
        ),
        env_usize_or("URING_PLAY_CQE_ADAPTIVE_WAIT_NS", 50_000),
        yes(env_enabled_or("URING_PLAY_CQE_HOT_POLL", false)),
        yes(env_truthy("URING_PLAY_ENTER_NO_IOWAIT")),
    );
    let listeners = tcp_bench_mux_bind_listeners(bind, base_port, lanes)?;
    let streams = tcp_bench_mux_accept_tagged_listeners(listeners, lanes, connections_per_lane)?;
    let shard_policy = TcpMuxShardPolicy::from_env_or(
        "URING_PLAY_ZCWAL_EXTENT_SHARD",
        TcpMuxShardPolicy::PortLane,
    )?;
    let shards = zcwal_extent_partition_accepted_streams(
        streams,
        workers,
        shard_policy,
        "zcwal-extent-recv",
    );
    let started = Instant::now();
    let mut handles = Vec::new();
    for (worker, shard) in shards.into_iter().enumerate() {
        if shard.is_empty() {
            continue;
        }
        handles.push(thread::spawn(move || {
            zcwal_extent_recv_worker(
                worker,
                shard,
                lanes,
                bytes_per_connection,
                extent_bytes,
                recv_bytes,
                framing_mode,
                data_path,
                ack_enabled,
            )
        }));
    }
    let mut results = Vec::with_capacity(handles.len());
    for handle in handles {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other("zcwal extent recv worker panicked"))??;
        zcwal_extent_print_worker("zcwal-extent-recv", &stats);
        results.push(stats);
    }
    let mut total = zcwal_extent_sum(&results);
    total.wall = total.wall.max(started.elapsed());
    let secs = total.wall.as_secs_f64().max(f64::MIN_POSITIVE);
    println!(
        "zcwal-extent-recv-summary: payload_bytes={} wire_bytes={} extents={} \
         logical_records={} acks={} seconds={secs:.6} payload_Gbitps={:.3} \
         logical_iops={:.0} voluntary_ctxt_switches={} involuntary_ctxt_switches={} migrations={} \
         recv_data_cqes={} recv_avg_cqe_len={} recv_min_cqe_len={} recv_max_cqe_len={} \
         recv_full_chunk_cqes={} recv_partial_cqes={} ring_sqes_queued={} ring_sqes_submitted={} \
         ring_submit_syscalls={} ring_wait_cqe_calls={} ring_wait_syscalls={} ring_cqes_popped={} \
         ring_try_pop_empty={} ring_cqe_spin_loops={} ring_cqe_hot_poll_waits={} \
         ring_cqe_adaptive_grows={} ring_cqe_adaptive_shrinks={} \
         ring_cqe_adaptive_spin_max_seen={} ring_submit_short={}",
        total.payload_bytes,
        total.wire_bytes,
        total.extents,
        total.records,
        total.acks,
        total.payload_bytes as f64 * 8.0 / 1_000_000_000.0 / secs,
        total.records as f64 / secs,
        total.voluntary_switches,
        total.involuntary_switches,
        total.migrations,
        total.uring_recv.data_cqes,
        total.uring_recv.avg_cqe_len(),
        total.uring_recv.min_cqe_len,
        total.uring_recv.max_cqe_len,
        total.uring_recv.full_chunk_cqes,
        total.uring_recv.partial_cqes,
        total.uring_recv.ring.sqes_queued,
        total.uring_recv.ring.sqes_submitted,
        total.uring_recv.ring.submit_syscalls,
        total.uring_recv.ring.wait_cqe_calls,
        total.uring_recv.ring.wait_syscalls,
        total.uring_recv.ring.cqes_popped,
        total.uring_recv.ring.try_pop_empty,
        total.uring_recv.ring.cqe_spin_loops,
        total.uring_recv.ring.cqe_hot_poll_waits,
        total.uring_recv.ring.cqe_adaptive_grows,
        total.uring_recv.ring.cqe_adaptive_shrinks,
        total.uring_recv.ring.cqe_adaptive_spin_max_seen,
        total.uring_recv.ring.submit_short,
    );
    Ok(())
}

