const ZCRAID_RMA_DOORBELL_MAGIC: &[u8; 8] = b"ZCRMRMA1";

#[derive(Clone, Copy)]
struct ZcRaidMirrorRmaDoorbell {
    lane: u32,
    branch: u32,
    seq_base: u64,
    batch: u64,
    extent_bytes: u64,
}

impl ZcRaidMirrorRmaDoorbell {
    fn encode(self) -> [u8; ZCOFI_RMA_CONTROL_LEN] {
        let mut out = [0u8; ZCOFI_RMA_CONTROL_LEN];
        out[..8].copy_from_slice(ZCRAID_RMA_DOORBELL_MAGIC);
        out[8..12].copy_from_slice(&self.lane.to_le_bytes());
        out[12..16].copy_from_slice(&self.branch.to_le_bytes());
        out[16..24].copy_from_slice(&self.seq_base.to_le_bytes());
        out[24..32].copy_from_slice(&self.batch.to_le_bytes());
        out[32..40].copy_from_slice(&self.extent_bytes.to_le_bytes());
        out
    }

    fn decode(buf: &[u8]) -> io::Result<Self> {
        if buf.len() != ZCOFI_RMA_CONTROL_LEN || &buf[..8] != ZCRAID_RMA_DOORBELL_MAGIC {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "zcraid mirror RMA doorbell shape or magic mismatch",
            ));
        }
        Ok(Self {
            lane: u32::from_le_bytes(buf[8..12].try_into().unwrap()),
            branch: u32::from_le_bytes(buf[12..16].try_into().unwrap()),
            seq_base: u64::from_le_bytes(buf[16..24].try_into().unwrap()),
            batch: u64::from_le_bytes(buf[24..32].try_into().unwrap()),
            extent_bytes: u64::from_le_bytes(buf[32..40].try_into().unwrap()),
        })
    }
}

#[cfg(test)]
mod zcraid_mirror_rma_protocol_tests {
    use super::*;

    #[test]
    fn doorbell_round_trips_window_identity() {
        let expected = ZcRaidMirrorRmaDoorbell {
            lane: 7,
            branch: 3,
            seq_base: 4096,
            batch: 64,
            extent_bytes: 65536,
        };
        let actual = ZcRaidMirrorRmaDoorbell::decode(&expected.encode()).unwrap();
        assert_eq!(actual.lane, expected.lane);
        assert_eq!(actual.branch, expected.branch);
        assert_eq!(actual.seq_base, expected.seq_base);
        assert_eq!(actual.batch, expected.batch);
        assert_eq!(actual.extent_bytes, expected.extent_bytes);
    }

    #[test]
    fn transport_parser_does_not_alias_rdma_to_fi_msg() {
        assert_eq!(
            ZcRaidMirrorTransport::parse("ofi").unwrap(),
            ZcRaidMirrorTransport::OfiMsg
        );
        assert_eq!(
            ZcRaidMirrorTransport::parse("rdma").unwrap(),
            ZcRaidMirrorTransport::Rma
        );
    }
}

struct ZcRaidMirrorRmaRecvLane {
    lane: usize,
    endpoint: ZcOfiEndpoint,
    arena: Vec<u8>,
    doorbell: Box<[u8; ZCOFI_RMA_CONTROL_LEN]>,
    ack_slots: Vec<u8>,
}

#[allow(clippy::too_many_arguments)]
fn zcraid_mirror_rma_recv_worker(
    worker: usize,
    provider: Arc<String>,
    endpoint: Arc<String>,
    bind: Arc<String>,
    branch: ZcRaidMirrorBranchPlan,
    base_port: u16,
    lanes: Vec<usize>,
    lane_count: usize,
    extents_per_lane: usize,
    extent_bytes: usize,
    ack_window: usize,
    coord_mode: ZcRaidZlaneCoordMode,
    terminal: ZcRaidMirrorTerminal,
) -> io::Result<ZcWalExtentStats> {
    let affinity = maybe_pin_current_thread("zcraid-mirror-rma-recv-worker", worker);
    let tid = current_tid();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let start_cpu = current_cpu();
    let start_switches = read_thread_context_switches(tid).unwrap_or_default();
    let window = ack_window.max(1).min(extents_per_lane.max(1));
    let arena_bytes = window.checked_mul(extent_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "RMA receive arena size overflow",
        )
    })?;
    let contract = zcraid_mirror_rma_peer_contract(
        branch.branch,
        lane_count,
        extent_bytes,
        window,
        coord_mode,
    );
    let mut endpoints = Vec::with_capacity(lanes.len());
    for lane in lanes {
        let service = tcp_bench_port(base_port, lane)?.to_string();
        let mut ep = zcraid_mirror_rma_open_endpoint(
            provider.as_str(),
            endpoint.as_str(),
            bind.as_str(),
            &service,
            true,
            branch.fabric_domain.as_deref(),
        )?;
        let mut doorbell = Box::new([0u8; ZCOFI_RMA_CONTROL_LEN]);
        let ack_bytes = window.checked_mul(ZC_WAL_ACK_HEADER_LEN).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "RMA ACK arena size overflow")
        })?;
        let ack_slots = vec![0u8; ack_bytes];
        // The warmup itself posts from stack storage.  Register every stable
        // control arena first so later doorbells/ACKs never register hot.
        ep.register_recv_buffer(doorbell.as_mut_slice())?;
        ep.register_send_buffer(&ack_slots)?;
        let control_port = zcofi_control_port(&service)?;
        zcofi_server_exchange_peer(bind.as_str(), control_port, &mut ep, &contract)?;
        zcofi_rma_server_connection_warmup(&mut ep, lane, provider.as_str())?;
        let mut arena = vec![0u8; arena_bytes];
        let (remote_addr, remote_key) = ep.rma_register_target(&mut arena)?;
        let meta = ZcOfiRmaMeta {
            lane_id: u32::try_from(lane)
                .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "lane overflow"))?,
            lane_count: u32::try_from(lane_count)
                .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "lane count overflow"))?,
            bytes_per_lane: u64::try_from(arena_bytes)
                .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "arena overflow"))?,
            extent_bytes: u64::try_from(extent_bytes)
                .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "extent overflow"))?,
            remote_addr,
            remote_key,
        };
        ep.send(&meta.encode())?;
        eprintln!(
            "zcraid-mirror-rma-recv-lane: worker={worker} branch={} lane={lane} provider={} domain={} registered_staging_bytes={arena_bytes} remote_addr=0x{remote_addr:016x} remote_key=0x{remote_key:016x} terminal={} completion=terminal-write-plus-sync-before-ack",
            branch.branch,
            provider.as_str(),
            branch.fabric_domain.as_deref().unwrap_or("auto"),
            terminal.backend.label(),
        );
        endpoints.push(ZcRaidMirrorRmaRecvLane {
            lane,
            endpoint: ep,
            arena,
            doorbell,
            ack_slots,
        });
    }

    let mut payload_bytes = 0usize;
    let mut wire_bytes = 0usize;
    let mut extents = 0usize;
    let mut records = 0usize;
    let mut acks = 0usize;
    let mut terminal_writes = 0usize;
    let mut terminal_syncs = 0usize;
    let records_per_extent = extent_bytes / ZC_WAL_RECORD_SIZE;
    let started = Instant::now();
    for lane_ep in &mut endpoints {
        let mut expected_seq = 0usize;
        let mut ring = terminal.ring()?;
        while expected_seq < extents_per_lane {
            let got = lane_ep.endpoint.recv(lane_ep.doorbell.as_mut_slice())?;
            if got != ZCOFI_RMA_CONTROL_LEN {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "short RMA doorbell",
                ));
            }
            let doorbell = ZcRaidMirrorRmaDoorbell::decode(lane_ep.doorbell.as_slice())?;
            let batch = window.min(extents_per_lane - expected_seq);
            if doorbell.lane as usize != lane_ep.lane
                || doorbell.branch as usize != branch.branch
                || doorbell.seq_base as usize != expected_seq
                || doorbell.batch as usize != batch
                || doorbell.extent_bytes as usize != extent_bytes
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "RMA doorbell mismatch branch={} lane={} expected_seq={expected_seq} expected_batch={batch}",
                        branch.branch, lane_ep.lane
                    ),
                ));
            }
            let mut headers = Vec::with_capacity(batch);
            for slot in 0..batch {
                let header = zcraid_mirror_extent_header(
                    lane_ep.lane,
                    lane_count,
                    branch.branch,
                    expected_seq + slot,
                    extent_bytes,
                    coord_mode,
                )?;
                let start = slot * extent_bytes;
                terminal.write(
                    &mut ring,
                    header,
                    &lane_ep.arena[start..start + extent_bytes],
                )?;
                headers.push(header);
                terminal_writes += 1;
            }
            terminal.sync()?;
            terminal_syncs += 1;
            for (slot, header) in headers.into_iter().enumerate() {
                let start = slot * ZC_WAL_ACK_HEADER_LEN;
                let end = start + ZC_WAL_ACK_HEADER_LEN;
                lane_ep.ack_slots[start..end]
                    .copy_from_slice(&zcraid_mirror_ack_for_header(header)?.encode());
                lane_ep.endpoint.send(&lane_ep.ack_slots[start..end])?;
                acks += 1;
            }
            expected_seq += batch;
            payload_bytes += batch * extent_bytes;
            wire_bytes +=
                batch * extent_bytes + ZCOFI_RMA_CONTROL_LEN + batch * ZC_WAL_ACK_HEADER_LEN;
            extents += batch;
            records += batch * records_per_extent;
        }
    }
    eprintln!(
        "zcraid-mirror-terminal-worker: transport=rdma-rma worker={worker} enabled=yes writes={terminal_writes} syncs={terminal_syncs} durable_ack=yes durability_window={window}"
    );
    let end_thread_cpu = thread_cpu_time().unwrap_or(start_thread_cpu);
    let end_cpu = current_cpu();
    let end_switches = read_thread_context_switches(tid).unwrap_or(start_switches);
    Ok(ZcWalExtentStats {
        worker,
        streams: endpoints.len(),
        payload_bytes,
        wire_bytes,
        extents,
        records,
        acks,
        wall: started.elapsed(),
        cpu: end_thread_cpu.saturating_sub(start_thread_cpu),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        voluntary_switches: end_switches
            .voluntary
            .saturating_sub(start_switches.voluntary),
        involuntary_switches: end_switches
            .involuntary
            .saturating_sub(start_switches.involuntary),
        migrations: end_switches
            .migrations
            .saturating_sub(start_switches.migrations),
        ack_latency: LatencyHistogram::new(),
        uring_recv: UringRecvStats::default(),
    })
}

struct ZcRaidMirrorRmaSendBranch {
    branch: usize,
    endpoint: ZcOfiEndpoint,
    meta: ZcOfiRmaMeta,
    completion_slots: Vec<usize>,
    completion_tokens: Vec<u64>,
    doorbell: Box<[u8; ZCOFI_RMA_CONTROL_LEN]>,
    ack_slots: Vec<u8>,
}

#[allow(clippy::too_many_arguments)]
fn zcraid_mirror_rma_send_worker(
    worker: usize,
    provider: Arc<String>,
    endpoint: Arc<String>,
    lanes: Vec<usize>,
    branches: Arc<Vec<ZcRaidMirrorBranchTarget>>,
    coordinator: Arc<ZcRaidZlaneCoordinator>,
    lane_count: usize,
    extents_per_lane: usize,
    extent_bytes: usize,
    ack_window: usize,
) -> io::Result<ZcWalExtentStats> {
    let affinity = maybe_pin_current_thread("zcraid-mirror-rma-send-worker", worker);
    let tid = current_tid();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let start_cpu = current_cpu();
    let start_switches = read_thread_context_switches(tid).unwrap_or_default();
    let window = ack_window.max(1).min(extents_per_lane.max(1));
    let arena_bytes = window.checked_mul(extent_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "RMA source arena size overflow",
        )
    })?;
    let pattern = SendPayloadPattern::from_env(extent_bytes)?;
    let records_per_extent = extent_bytes / ZC_WAL_RECORD_SIZE;
    let mut payload_bytes = 0usize;
    let mut wire_bytes = 0usize;
    let mut extents = 0usize;
    let mut records = 0usize;
    let mut acks = 0usize;
    let mut ack_latency = LatencyHistogram::new();
    let mut cq_polls = 0u64;
    let mut cq_completions = 0u64;
    let stream_count = lanes.len().saturating_mul(branches.len());
    let mut operation_wall = Duration::ZERO;

    for lane in lanes {
        // One payload allocation is registered against every branch endpoint.
        // Mirroring therefore adds NIC operations, not branch-sized memcpy work.
        let mut source = vec![0u8; arena_bytes];
        for slot in source.chunks_exact_mut(extent_bytes) {
            pattern.fill(slot);
        }
        let mut branch_eps = Vec::with_capacity(branches.len());
        for branch in branches.iter() {
            let service = tcp_bench_port(branch.base_port, lane)?.to_string();
            let mut ep = zcraid_mirror_rma_open_endpoint(
                provider.as_str(),
                endpoint.as_str(),
                branch.addr.as_str(),
                &service,
                false,
                branch.plan.fabric_domain.as_deref(),
            )?;
            let doorbell = Box::new([0u8; ZCOFI_RMA_CONTROL_LEN]);
            let ack_bytes = window.checked_mul(ZC_WAL_ACK_HEADER_LEN).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "RMA ACK arena size overflow")
            })?;
            let mut ack_slots = vec![0u8; ack_bytes];
            // Register stable control storage before the stack-backed warmup
            // performs the endpoint's first SEND/RECV posts.
            ep.register_send_buffer(doorbell.as_slice())?;
            ep.register_recv_buffer(&mut ack_slots)?;
            let contract = zcraid_mirror_rma_peer_contract(
                branch.plan.branch,
                lane_count,
                extent_bytes,
                window,
                coordinator.mode(),
            );
            let control_port = zcofi_control_port(&service)?;
            zcofi_client_exchange_peer(branch.addr.as_str(), control_port, &mut ep, &contract)?;
            zcofi_rma_client_connection_warmup(&mut ep, lane, provider.as_str())?;
            let mut meta_buf = [0u8; ZCOFI_RMA_CONTROL_LEN];
            let got = ep.recv(&mut meta_buf)?;
            if got != ZCOFI_RMA_CONTROL_LEN {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "short RMA metadata",
                ));
            }
            let meta = ZcOfiRmaMeta::decode(&meta_buf)?;
            zcofi_rma_validate_meta(meta, lane, lane_count, arena_bytes, extent_bytes)?;
            // RMA source registration and queue initialization seal strict-mode
            // registration state.  All control arenas must be registered first.
            ep.rma_register_write_buffer(&source)?;
            ep.rma_write_queue_init(window)?;
            eprintln!(
                "zcraid-mirror-rma-send-lane: worker={worker} branch={} lane={lane} provider={} domain={} shared_registered_source_bytes={arena_bytes} remote_addr=0x{:016x} remote_key=0x{:016x} queue_depth={window} delivery_complete={} durable_completion=remote-terminal-sync-ack",
                branch.plan.branch,
                provider.as_str(),
                branch.plan.fabric_domain.as_deref().unwrap_or("auto"),
                meta.remote_addr,
                meta.remote_key,
                yes(env_enabled_or(
                    "URING_PLAY_OFI_RMA_WRITE_DELIVERY_COMPLETE",
                    true
                )),
            );
            branch_eps.push(ZcRaidMirrorRmaSendBranch {
                branch: branch.plan.branch,
                endpoint: ep,
                meta,
                completion_slots: vec![0; window],
                completion_tokens: vec![0; window],
                doorbell,
                ack_slots,
            });
        }

        let lane_started = Instant::now();
        let mut seq_base = 0usize;
        while seq_base < extents_per_lane {
            let batch = window.min(extents_per_lane - seq_base);
            let mut ranges = Vec::with_capacity(batch);
            for slot in 0..batch {
                let (_, first, last, _) = zcraid_mirror_extent_layout(
                    lane,
                    lane_count,
                    seq_base + slot,
                    extent_bytes,
                    coordinator.mode(),
                )?;
                ranges.push((first, last));
            }
            let _range_guards = coordinator.acquire_many(&ranges)?;
            let issued = Instant::now();
            for branch in &mut branch_eps {
                for slot in 0..batch {
                    let offset = slot.checked_mul(extent_bytes).ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidInput, "RMA slot overflow")
                    })?;
                    let remote_addr = branch
                        .meta
                        .remote_addr
                        .checked_add(u64::try_from(offset).unwrap())
                        .ok_or_else(|| {
                            io::Error::new(io::ErrorKind::InvalidInput, "RMA address overflow")
                        })?;
                    let posted = unsafe {
                        branch.endpoint.rma_write_post_more_raw(
                            source.as_ptr().add(offset),
                            extent_bytes,
                            remote_addr,
                            branch.meta.remote_key,
                            slot,
                            u64::try_from(slot).unwrap(),
                            slot + 1 < batch,
                        )?
                    };
                    if !posted {
                        return Err(io::Error::new(
                            io::ErrorKind::WouldBlock,
                            format!(
                                "RMA queue rejected branch={} lane={lane} slot={slot} batch={batch}",
                                branch.branch
                            ),
                        ));
                    }
                }
            }
            for branch in &mut branch_eps {
                let mut remaining = batch;
                while remaining != 0 {
                    cq_polls += 1;
                    let completed = branch.endpoint.rma_write_poll(
                        &mut branch.completion_slots[..batch],
                        &mut branch.completion_tokens[..batch],
                        true,
                    )?;
                    for index in 0..completed {
                        let slot = branch.completion_slots[index];
                        if slot >= batch || branch.completion_tokens[index] != slot as u64 {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                "RMA completion slot/token mismatch",
                            ));
                        }
                    }
                    remaining = remaining.checked_sub(completed).ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "excess RMA completions")
                    })?;
                    cq_completions += completed as u64;
                }
            }
            for branch in &mut branch_eps {
                let bell = ZcRaidMirrorRmaDoorbell {
                    lane: u32::try_from(lane).unwrap(),
                    branch: u32::try_from(branch.branch).unwrap(),
                    seq_base: u64::try_from(seq_base).unwrap(),
                    batch: u64::try_from(batch).unwrap(),
                    extent_bytes: u64::try_from(extent_bytes).unwrap(),
                };
                *branch.doorbell = bell.encode();
                branch.endpoint.send(branch.doorbell.as_slice())?;
            }
            for branch in &mut branch_eps {
                for slot in 0..batch {
                    let start = slot * ZC_WAL_ACK_HEADER_LEN;
                    let end = start + ZC_WAL_ACK_HEADER_LEN;
                    let got = branch.endpoint.recv(&mut branch.ack_slots[start..end])?;
                    if got != ZC_WAL_ACK_HEADER_LEN {
                        return Err(io::Error::new(io::ErrorKind::InvalidData, "short RMA ACK"));
                    }
                    let ack_buf: &[u8; ZC_WAL_ACK_HEADER_LEN] =
                        branch.ack_slots[start..end].try_into().map_err(|_| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "RMA ACK slot shape mismatch",
                            )
                        })?;
                    let ack = ZcWalAckHeader::decode(ack_buf)?;
                    if ack.lane_id as usize != lane
                        || ack.shard_id as usize != branch.branch
                        || ack.extent_sequence as usize != seq_base + slot
                    {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            "RMA durable ACK identity mismatch",
                        ));
                    }
                }
            }
            acks += batch;
            ack_latency.record_duration(issued.elapsed());
            payload_bytes += batch * extent_bytes;
            wire_bytes += batch * extent_bytes * branch_eps.len()
                + branch_eps.len() * (ZCOFI_RMA_CONTROL_LEN + batch * ZC_WAL_ACK_HEADER_LEN);
            extents += batch;
            records += batch * records_per_extent;
            seq_base += batch;
        }
        operation_wall = operation_wall.saturating_add(lane_started.elapsed());
    }
    eprintln!(
        "zcraid-mirror-rma-send-queue-worker: worker={worker} streams={stream_count} shared_payload_copy_per_branch=no cq_polls={cq_polls} cq_completions={cq_completions} durable_acks={acks}"
    );
    let end_thread_cpu = thread_cpu_time().unwrap_or(start_thread_cpu);
    let end_cpu = current_cpu();
    let end_switches = read_thread_context_switches(tid).unwrap_or(start_switches);
    Ok(ZcWalExtentStats {
        worker,
        streams: stream_count,
        payload_bytes,
        wire_bytes,
        extents,
        records,
        acks,
        wall: operation_wall,
        cpu: end_thread_cpu.saturating_sub(start_thread_cpu),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        voluntary_switches: end_switches
            .voluntary
            .saturating_sub(start_switches.voluntary),
        involuntary_switches: end_switches
            .involuntary
            .saturating_sub(start_switches.involuntary),
        migrations: end_switches
            .migrations
            .saturating_sub(start_switches.migrations),
        ack_latency,
        uring_recv: UringRecvStats::default(),
    })
}

struct ZcRaidMirrorOfiRecvLane {
    lane: usize,
    endpoint: ZcOfiEndpoint,
    messages: Vec<u8>,
    ack_buf: Box<[u8; ZC_WAL_ACK_HEADER_LEN]>,
    completion_slots: Vec<usize>,
    completion_tokens: Vec<u64>,
    completion_lengths: Vec<usize>,
    completion_sources: Vec<u64>,
}

fn zcraid_mirror_ofi_recv_worker(
    worker: usize,
    provider: Arc<String>,
    endpoint: Arc<String>,
    bind: Arc<String>,
    branch: ZcRaidMirrorBranchPlan,
    base_port: u16,
    lanes: Vec<usize>,
    lane_count: usize,
    extents_per_lane: usize,
    extent_bytes: usize,
    ack_enabled: bool,
    recv_window: usize,
    ack_window: usize,
    coord_mode: ZcRaidZlaneCoordMode,
    terminal: Option<ZcRaidMirrorTerminal>,
) -> io::Result<ZcWalExtentStats> {
    let affinity = maybe_pin_current_thread("zcraid-mirror-ofi-recv-worker", worker);
    let tid = current_tid();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let start_cpu = current_cpu();
    let start_switches = read_thread_context_switches(tid).unwrap_or_default();
    let compact_4k = zcofi_compact_4k_enabled(provider.as_str(), extent_bytes, ack_enabled);
    let message_bytes = zcofi_wal_message_bytes(provider.as_str(), extent_bytes, ack_enabled);
    let ack_inject = ack_enabled && env_enabled_or("URING_PLAY_OFI_ACK_INJECT", false);
    let recv_window = recv_window.max(1).min(extents_per_lane.max(1));
    let contract = zcraid_mirror_ofi_peer_contract(
        provider.as_str(),
        branch.branch,
        lane_count,
        extent_bytes,
        ack_enabled,
        recv_window,
        coord_mode,
    );
    let mut endpoints = Vec::with_capacity(lanes.len());
    let stream_count = lanes.len();
    for lane in lanes {
        let service = tcp_bench_port(base_port, lane)?.to_string();
        let mut ep = zcraid_mirror_ofi_open_endpoint(
            provider.as_str(),
            endpoint.as_str(),
            bind.as_str(),
            &service,
            true,
            branch.fabric_domain.as_deref(),
        )?;
        zcofi_wal_check_endpoint_shape(&ep, message_bytes, provider.as_str(), lane)?;
        let control_port = zcofi_control_port(&service)?;
        zcofi_server_exchange_peer(bind.as_str(), control_port, &mut ep, &contract)?;
        let arena_bytes = recv_window.checked_mul(message_bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcraid mirror RX arena overflow",
            )
        })?;
        let mut messages = vec![0u8; arena_bytes];
        let ack_buf = Box::new([0u8; ZC_WAL_ACK_HEADER_LEN]);
        ep.recv_queue_init(recv_window)?;
        ep.register_recv_buffer(&mut messages)?;
        if ack_enabled {
            ep.register_send_buffer(ack_buf.as_slice())?;
        }
        for slot in 0..recv_window {
            let posted = unsafe {
                ep.recv_post_raw(
                    messages.as_mut_ptr().add(slot * message_bytes),
                    message_bytes,
                    slot,
                    slot as u64,
                )?
            };
            if !posted {
                return Err(io::Error::new(
                    io::ErrorKind::WouldBlock,
                    format!(
                        "zcraid mirror could not prepost payload branch={} lane={lane} slot={slot}",
                        branch.branch
                    ),
                ));
            }
        }
        println!(
            "zcraid-mirror-ofi-recv-lane: worker={worker} branch={} lane={lane} provider={} endpoint={} bind={} service={} control_port={} domain={} max_msg_size={} inject_size={} rx_queue_depth={recv_window} rx_registered_arena_bytes={arena_bytes}",
            branch.branch,
            provider.as_str(),
            endpoint.as_str(),
            bind.as_str(),
            service,
            control_port,
            branch.fabric_domain.as_deref().unwrap_or("auto"),
            ep.max_msg_size(),
            ep.inject_size(),
        );
        endpoints.push(ZcRaidMirrorOfiRecvLane {
            lane,
            endpoint: ep,
            messages,
            ack_buf,
            completion_slots: vec![0; recv_window],
            completion_tokens: vec![0; recv_window],
            completion_lengths: vec![0; recv_window],
            completion_sources: vec![0; recv_window],
        });
    }

    let mut payload_bytes = 0usize;
    let mut wire_bytes = 0usize;
    let mut extents = 0usize;
    let mut records = 0usize;
    let mut acks = 0usize;
    let mut cq_poll_calls = 0u64;
    let mut cq_batches = 0u64;
    let mut cq_completions = 0u64;
    let mut terminal_writes = 0usize;
    let mut terminal_syncs = 0usize;
    let mut terminal_ring = terminal
        .as_ref()
        .map(ZcRaidMirrorTerminal::ring)
        .transpose()?
        .flatten();
    let started = Instant::now();
    for mut lane_state in endpoints {
        let lane = lane_state.lane;
        let mut next_post_seq = recv_window;
        let mut completed_extents = 0usize;
        let mut seen = vec![false; extents_per_lane];
        let durability_window = ack_window.max(1);
        let mut durability_batches = BTreeMap::<usize, Vec<Option<ZcWalExtentHeader>>>::new();
        while completed_extents < extents_per_lane {
            cq_poll_calls = cq_poll_calls.saturating_add(1);
            let completed = lane_state.endpoint.recv_poll(
                &mut lane_state.completion_slots,
                &mut lane_state.completion_tokens,
                &mut lane_state.completion_lengths,
                &mut lane_state.completion_sources,
                true,
            )?;
            if completed != 0 {
                cq_batches = cq_batches.saturating_add(1);
                cq_completions = cq_completions.saturating_add(completed as u64);
            }
            for completion_idx in 0..completed {
                let slot = lane_state.completion_slots[completion_idx];
                let token = lane_state.completion_tokens[completion_idx];
                if slot >= recv_window
                    || lane_state.completion_lengths[completion_idx] != message_bytes
                    || (!compact_4k && token != slot as u64)
                {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        format!(
                            "zcraid mirror OFI RX completion mismatch branch={} lane={lane} slot={slot} token={token} len={} depth={recv_window} extents={extents_per_lane}",
                            branch.branch, lane_state.completion_lengths[completion_idx],
                        ),
                    ));
                }
                let start = slot * message_bytes;
                let message = &lane_state.messages[start..start + message_bytes];
                let (header, seq) = if compact_4k {
                    let seq = usize::try_from(token).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidData, "mirror RX sequence overflow")
                    })?;
                    (
                        zcraid_mirror_extent_header(
                            lane,
                            lane_count,
                            branch.branch,
                            seq,
                            extent_bytes,
                            coord_mode,
                        )?,
                        seq,
                    )
                } else {
                    let mut header_buf = [0u8; ZC_WAL_EXTENT_HEADER_LEN];
                    header_buf.copy_from_slice(&message[..ZC_WAL_EXTENT_HEADER_LEN]);
                    let header = ZcWalExtentHeader::decode(&header_buf)?;
                    let seq = usize::try_from(header.extent_sequence).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidData, "mirror RX sequence overflow")
                    })?;
                    zcraid_mirror_verify_extent_header(
                        header,
                        lane,
                        lane_count,
                        branch.branch,
                        seq,
                        extent_bytes,
                        coord_mode,
                    )?;
                    (header, seq)
                };
                if seq >= extents_per_lane || seen[seq] {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        format!(
                            "zcraid mirror OFI RX sequence mismatch branch={} lane={lane} slot={slot} seq={seq} extents={extents_per_lane} duplicate={}",
                            branch.branch,
                            yes(seq < seen.len() && seen[seq]),
                        ),
                    ));
                }
                seen[seq] = true;
                completed_extents += 1;
                if let Some(terminal) = terminal.as_ref() {
                    let payload = if compact_4k {
                        message
                    } else {
                        &message[ZC_WAL_EXTENT_HEADER_LEN..]
                    };
                    terminal.write(&mut terminal_ring, header, payload)?;
                    terminal_writes = terminal_writes.saturating_add(1);
                    let batch_base = seq / durability_window * durability_window;
                    let expected = durability_window.min(extents_per_lane - batch_base);
                    let batch = durability_batches
                        .entry(batch_base)
                        .or_insert_with(|| vec![None; expected]);
                    let batch_slot = seq - batch_base;
                    if batch_slot >= batch.len() || batch[batch_slot].replace(header).is_some() {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!(
                                "zcraid mirror terminal durability batch mismatch lane={lane} seq={seq} base={batch_base} slot={batch_slot} expected={expected}"
                            ),
                        ));
                    }
                    if batch.iter().all(Option::is_some) {
                        let durable = durability_batches.remove(&batch_base).ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "zcraid mirror terminal durability batch disappeared",
                            )
                        })?;
                        terminal.sync()?;
                        terminal_syncs = terminal_syncs.saturating_add(1);
                        if ack_enabled {
                            for durable_header in durable.into_iter().flatten() {
                                lane_state.ack_buf.copy_from_slice(
                                    &zcraid_mirror_ack_for_header(durable_header)?.encode(),
                                );
                                if ack_inject
                                    && lane_state.ack_buf.len() <= lane_state.endpoint.inject_size()
                                {
                                    lane_state
                                        .endpoint
                                        .inject_to_last(lane_state.ack_buf.as_slice())?;
                                } else {
                                    lane_state
                                        .endpoint
                                        .send_to_last(lane_state.ack_buf.as_slice())?;
                                }
                                acks += 1;
                            }
                        }
                    }
                }
                payload_bytes += extent_bytes;
                wire_bytes += message_bytes;
                extents += 1;
                records += header.record_count as usize;
                if ack_enabled && terminal.is_none() {
                    lane_state
                        .ack_buf
                        .copy_from_slice(&zcraid_mirror_ack_for_header(header)?.encode());
                    if ack_inject && lane_state.ack_buf.len() <= lane_state.endpoint.inject_size() {
                        lane_state
                            .endpoint
                            .inject_to_last(lane_state.ack_buf.as_slice())?;
                    } else {
                        lane_state
                            .endpoint
                            .send_to_last(lane_state.ack_buf.as_slice())?;
                    }
                    acks += 1;
                }
                if next_post_seq < extents_per_lane {
                    let next_token = if compact_4k {
                        next_post_seq as u64
                    } else {
                        slot as u64
                    };
                    let posted = unsafe {
                        lane_state.endpoint.recv_post_raw(
                            lane_state.messages.as_mut_ptr().add(start),
                            message_bytes,
                            slot,
                            next_token,
                        )?
                    };
                    if !posted {
                        return Err(io::Error::new(
                            io::ErrorKind::WouldBlock,
                            format!(
                                "zcraid mirror could not recycle payload slot branch={} lane={lane} slot={slot} next_seq={next_post_seq}",
                                branch.branch
                            ),
                        ));
                    }
                    next_post_seq += 1;
                }
            }
        }
        if !durability_batches.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "zcraid mirror terminal lane={lane} ended with {} incomplete durability batches",
                    durability_batches.len()
                ),
            ));
        }
    }

    println!(
        "zcraid-mirror-ofi-recv-queue-worker: worker={worker} lanes={stream_count} configured_rx_depth={recv_window} cq_poll_calls={cq_poll_calls} cq_batches={cq_batches} cq_completions={cq_completions} avg_cqes_per_batch={:.2}",
        cq_completions as f64 / cq_batches.max(1) as f64,
    );
    eprintln!(
        "zcraid-mirror-terminal-worker: transport=ofi worker={worker} enabled={} writes={terminal_writes} syncs={terminal_syncs} durable_ack={} durability_window={}",
        yes(terminal.is_some()),
        yes(terminal.is_some() && ack_enabled),
        ack_window.max(1),
    );

    let end_thread_cpu = thread_cpu_time().unwrap_or(start_thread_cpu);
    let end_cpu = current_cpu();
    let end_switches = read_thread_context_switches(tid).unwrap_or(start_switches);
    Ok(ZcWalExtentStats {
        worker,
        streams: stream_count,
        payload_bytes,
        wire_bytes,
        extents,
        records,
        acks,
        wall: started.elapsed(),
        cpu: end_thread_cpu.saturating_sub(start_thread_cpu),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        voluntary_switches: end_switches
            .voluntary
            .saturating_sub(start_switches.voluntary),
        involuntary_switches: end_switches
            .involuntary
            .saturating_sub(start_switches.involuntary),
        migrations: end_switches
            .migrations
            .saturating_sub(start_switches.migrations),
        ack_latency: LatencyHistogram::new(),
        uring_recv: UringRecvStats::default(),
    })
}

struct ZcRaidMirrorOfiBranchLane {
    branch: usize,
    endpoint: ZcOfiEndpoint,
    tx_slots: Vec<u8>,
    ack_slots: Vec<u8>,
    completion_slots: Vec<usize>,
    completion_tokens: Vec<u64>,
    completion_lengths: Vec<usize>,
    completion_sources: Vec<u64>,
}

fn zcraid_mirror_ofi_drain_branches(
    lane: usize,
    branches: &mut [ZcRaidMirrorOfiBranchLane],
) -> io::Result<(u64, u64, u64)> {
    let timeout = Duration::from_millis(u64::try_from(zcofi_timeout_ms()).unwrap_or(30_000));
    let mut last_progress = Instant::now();
    let mut polls = 0u64;
    let mut empty_polls = 0u64;
    let mut completions = 0u64;
    loop {
        let mut pending = 0usize;
        let mut progress = 0usize;
        for branch in branches.iter_mut() {
            if branch.endpoint.send_pending() == 0 {
                continue;
            }
            pending += 1;
            polls = polls.saturating_add(1);
            let completed = branch.endpoint.send_poll(false)?;
            if completed == 0 {
                empty_polls = empty_polls.saturating_add(1);
            }
            progress = progress.saturating_add(completed);
            completions = completions.saturating_add(completed as u64);
        }
        if pending == 0 {
            return Ok((polls, empty_polls, completions));
        }
        if progress != 0 {
            last_progress = Instant::now();
        } else if last_progress.elapsed() >= timeout {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                format!(
                    "zcraid mirror fair TX CQ drain timed out lane={lane} pending_branches={pending}"
                ),
            ));
        } else {
            thread::yield_now();
        }
    }
}

fn zcraid_mirror_ofi_send_worker(
    worker: usize,
    provider: Arc<String>,
    endpoint: Arc<String>,
    lanes: Vec<usize>,
    branches: Arc<Vec<ZcRaidMirrorBranchTarget>>,
    coordinator: Arc<ZcRaidZlaneCoordinator>,
    lane_count: usize,
    extents_per_lane: usize,
    extent_bytes: usize,
    ack_enabled: bool,
    ack_window: usize,
) -> io::Result<ZcWalExtentStats> {
    let affinity = maybe_pin_current_thread("zcraid-mirror-ofi-send-worker", worker);
    let tid = current_tid();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let start_cpu = current_cpu();
    let start_switches = read_thread_context_switches(tid).unwrap_or_default();
    let compact_4k = zcofi_compact_4k_enabled(provider.as_str(), extent_bytes, ack_enabled);
    let message_bytes = zcofi_wal_message_bytes(provider.as_str(), extent_bytes, ack_enabled);
    let records_per_extent = extent_bytes / ZC_WAL_RECORD_SIZE;
    let payload_inject = env_enabled_or("URING_PLAY_OFI_PAYLOAD_INJECT", false);
    let branch_post_nowait = env_enabled_or("URING_PLAY_OFI_BRANCH_POST_NOWAIT", true);
    let prepost_ack = ack_enabled && env_enabled_or("URING_PLAY_OFI_PREPOST_ACK", true);
    let configured_window = if ack_enabled {
        ack_window.max(1)
    } else {
        env_usize_or("URING_PLAY_OFI_TX_QUEUE_DEPTH", 64).max(1)
    };
    let tx_arena_bytes = configured_window
        .checked_mul(message_bytes)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcraid mirror OFI TX arena size overflow",
            )
        })?;
    let ack_arena_bytes = configured_window
        .checked_mul(ZC_WAL_ACK_HEADER_LEN)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcraid mirror OFI ACK arena size overflow",
            )
        })?;
    let payload_pattern = SendPayloadPattern::from_env(extent_bytes)?;
    let mut payload_bytes = 0usize;
    let mut wire_bytes = 0usize;
    let mut extents = 0usize;
    let mut records = 0usize;
    let mut acks = 0usize;
    let mut ack_latency = LatencyHistogram::new();
    let mut branch_post_skew = LatencyHistogram::new();
    let mut ack_mask_wait = LatencyHistogram::new();
    let mut ack_hol_wait = LatencyHistogram::new();
    let mut ack_out_of_order = 0u64;
    let mut ack_hol_waits = 0u64;
    let mut ack_poll_calls = 0u64;
    let mut ack_poll_empty = 0u64;
    let mut tx_poll_calls = 0u64;
    let mut tx_poll_empty = 0u64;
    let mut tx_poll_completions = 0u64;
    let worker_lane_count = lanes.len();
    let stream_count = worker_lane_count * branches.len();
    let configured_ack_outstanding = if prepost_ack {
        worker_lane_count
            .saturating_mul(branches.len())
            .saturating_mul(configured_window)
    } else {
        0
    };
    let mut peak_ack_outstanding = 0usize;
    let mut lane_eps = Vec::with_capacity(lanes.len());

    for lane in lanes {
        let mut branch_eps = Vec::with_capacity(branches.len());
        for branch in branches.iter() {
            let service = tcp_bench_port(branch.base_port, lane)?.to_string();
            let mut ep = zcraid_mirror_ofi_open_endpoint(
                provider.as_str(),
                endpoint.as_str(),
                branch.addr.as_str(),
                &service,
                false,
                branch.plan.fabric_domain.as_deref(),
            )?;
            zcofi_wal_check_endpoint_shape(&ep, message_bytes, provider.as_str(), lane)?;
            let control_port = zcofi_control_port(&service)?;
            let contract = zcraid_mirror_ofi_peer_contract(
                provider.as_str(),
                branch.plan.branch,
                lane_count,
                extent_bytes,
                ack_enabled,
                if ack_enabled {
                    configured_window.min(extents_per_lane.max(1))
                } else {
                    0
                },
                coordinator.mode,
            );
            zcofi_client_exchange_peer(branch.addr.as_str(), control_port, &mut ep, &contract)?;
            let mut tx_slots = vec![0u8; tx_arena_bytes];
            for slot in tx_slots.chunks_exact_mut(message_bytes) {
                if compact_4k {
                    payload_pattern.fill(slot);
                } else {
                    payload_pattern.fill(&mut slot[ZC_WAL_EXTENT_HEADER_LEN..]);
                }
            }
            ep.register_send_buffer(&tx_slots)?;
            let mut ack_slots = if prepost_ack {
                vec![0u8; ack_arena_bytes]
            } else {
                Vec::new()
            };
            if prepost_ack {
                ep.recv_queue_init(configured_window)?;
                ep.register_recv_buffer(&mut ack_slots)?;
            }
            println!(
                "zcraid-mirror-ofi-send-lane: worker={worker} branch={} lane={lane} provider={} endpoint={} addr={} service={} control_port={} domain={} max_msg_size={} inject_size={} tx_queue_depth={} tx_registered_arena_bytes={} ack_queue_depth={} ack_registered_arena_bytes={} branch_post_nowait={} prepost_ack={}",
                branch.plan.branch,
                provider.as_str(),
                endpoint.as_str(),
                branch.addr.as_str(),
                service,
                control_port,
                branch.plan.fabric_domain.as_deref().unwrap_or("auto"),
                ep.max_msg_size(),
                ep.inject_size(),
                configured_window,
                tx_slots.len(),
                if prepost_ack { configured_window } else { 0 },
                ack_slots.len(),
                yes(branch_post_nowait),
                yes(prepost_ack),
            );
            branch_eps.push(ZcRaidMirrorOfiBranchLane {
                branch: branch.plan.branch,
                endpoint: ep,
                tx_slots,
                ack_slots,
                completion_slots: vec![0; configured_window],
                completion_tokens: vec![0; configured_window],
                completion_lengths: vec![0; configured_window],
                completion_sources: vec![0; configured_window],
            });
        }
        lane_eps.push((lane, branch_eps));
    }

    let started = Instant::now();
    for (lane, mut branch_eps) in lane_eps {
        let all_can_inject = compact_4k
            && payload_inject
            && branch_eps
                .iter()
                .all(|branch| message_bytes <= branch.endpoint.inject_size());
        let effective_window = configured_window.min(extents_per_lane.max(1));
        let mut issued_slots = vec![Instant::now(); effective_window];
        let mut seq_base = 0usize;
        while seq_base < extents_per_lane {
            let batch = effective_window.min(extents_per_lane - seq_base).max(1);
            let mut ranges = Vec::with_capacity(batch);
            for slot in 0..batch {
                let seq = seq_base + slot;
                let (_, first_logical_index, last_logical_index, _) = zcraid_mirror_extent_layout(
                    lane,
                    lane_count,
                    seq,
                    extent_bytes,
                    coordinator.mode(),
                )?;
                ranges.push((first_logical_index, last_logical_index));
            }
            // acquire_many() returns one guard per distinct lock shard, not one
            // guard per sequence.  Keep the whole batch protected until its ACK
            // high-water mark has retired; indexing these guards by slot is both
            // incorrect for deduplicated shards and empty in lane-owner mode.
            let mut range_guards = Some(coordinator.acquire_many(&ranges)?);

            if prepost_ack {
                for branch in &mut branch_eps {
                    for slot in 0..batch {
                        let offset = slot * ZC_WAL_ACK_HEADER_LEN;
                        let token = u64::try_from(slot).map_err(|_| {
                            io::Error::new(
                                io::ErrorKind::InvalidInput,
                                "zcraid mirror ACK token overflow",
                            )
                        })?;
                        let posted = unsafe {
                            branch.endpoint.recv_post_raw(
                                branch.ack_slots.as_mut_ptr().add(offset),
                                ZC_WAL_ACK_HEADER_LEN,
                                slot,
                                token,
                            )?
                        };
                        if !posted {
                            return Err(io::Error::new(
                                io::ErrorKind::WouldBlock,
                                format!(
                                    "zcraid mirror OFI could not prepost ACK branch={} lane={lane} slot={slot} window={effective_window}",
                                    branch.branch
                                ),
                            ));
                        }
                    }
                }
                peak_ack_outstanding =
                    peak_ack_outstanding.max(batch.saturating_mul(branch_eps.len()));
            }

            for (slot, issued) in issued_slots.iter_mut().take(batch).enumerate() {
                let seq = seq_base + slot;
                *issued = Instant::now();
                let first_post = Instant::now();
                for branch in &mut branch_eps {
                    let start = slot * message_bytes;
                    let end = start + message_bytes;
                    let message = &mut branch.tx_slots[start..end];
                    if !compact_4k {
                        let header = zcraid_mirror_extent_header(
                            lane,
                            lane_count,
                            branch.branch,
                            seq,
                            extent_bytes,
                            coordinator.mode(),
                        )?
                        .encode();
                        message[..ZC_WAL_EXTENT_HEADER_LEN].copy_from_slice(&header);
                    }
                    if all_can_inject {
                        branch.endpoint.inject(message)?;
                    } else if branch_post_nowait {
                        branch.endpoint.send_nowait(message)?;
                    } else {
                        branch.endpoint.send(message)?;
                    }
                }
                branch_post_skew.record_duration(first_post.elapsed());
                payload_bytes += extent_bytes;
                wire_bytes += message_bytes * branch_eps.len();
                extents += 1;
                records += records_per_extent;
            }

            if branch_post_nowait && !all_can_inject {
                let (polls, empty, completions) =
                    zcraid_mirror_ofi_drain_branches(lane, &mut branch_eps)?;
                tx_poll_calls = tx_poll_calls.saturating_add(polls);
                tx_poll_empty = tx_poll_empty.saturating_add(empty);
                tx_poll_completions = tx_poll_completions.saturating_add(completions);
            }

            if ack_enabled {
                if prepost_ack {
                    let mut ack_masks = vec![vec![false; branch_eps.len()]; batch];
                    let mut mask_complete = vec![false; batch];
                    let mut first_ack = vec![None; batch];
                    let mut mask_completed_at = vec![None; batch];
                    let mut hol_blocked = vec![false; batch];
                    let mut remaining = batch.saturating_mul(branch_eps.len());
                    let mut next_retire = 0usize;
                    let mut last_progress = Instant::now();
                    while remaining != 0 {
                        let mut progress = 0usize;
                        for (branch_idx, branch) in branch_eps.iter_mut().enumerate() {
                            ack_poll_calls = ack_poll_calls.saturating_add(1);
                            let completed = branch.endpoint.recv_poll(
                                &mut branch.completion_slots[..batch],
                                &mut branch.completion_tokens[..batch],
                                &mut branch.completion_lengths[..batch],
                                &mut branch.completion_sources[..batch],
                                false,
                            )?;
                            if completed == 0 {
                                ack_poll_empty = ack_poll_empty.saturating_add(1);
                                continue;
                            }
                            progress += completed;
                            for index in 0..completed {
                                let recv_slot = branch.completion_slots[index];
                                if recv_slot >= batch
                                    || branch.completion_tokens[index] != recv_slot as u64
                                    || branch.completion_lengths[index] != ZC_WAL_ACK_HEADER_LEN
                                {
                                    return Err(io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        format!(
                                            "zcraid mirror OFI ACK completion mismatch branch={} lane={lane} recv_slot={recv_slot} token={} len={} batch={batch}",
                                            branch.branch,
                                            branch.completion_tokens[index],
                                            branch.completion_lengths[index],
                                        ),
                                    ));
                                }
                                let start = recv_slot * ZC_WAL_ACK_HEADER_LEN;
                                let end = start + ZC_WAL_ACK_HEADER_LEN;
                                let ack_buf: &[u8; ZC_WAL_ACK_HEADER_LEN] =
                                    branch.ack_slots[start..end].try_into().map_err(|_| {
                                        io::Error::new(
                                            io::ErrorKind::InvalidData,
                                            "zcraid mirror OFI ACK slot shape mismatch",
                                        )
                                    })?;
                                let ack = ZcWalAckHeader::decode(ack_buf)?;
                                let seq = usize::try_from(ack.extent_sequence).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "zcraid mirror OFI ACK sequence overflow",
                                    )
                                })?;
                                if seq < seq_base || seq >= seq_base + batch {
                                    return Err(io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        format!(
                                            "zcraid mirror OFI ACK sequence outside window branch={} lane={lane} seq={seq} seq_base={seq_base} batch={batch} recv_slot={recv_slot}",
                                            branch.branch,
                                        ),
                                    ));
                                }
                                let seq_slot = seq - seq_base;
                                if ack_masks[seq_slot][branch_idx] {
                                    return Err(io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        format!(
                                            "zcraid mirror OFI duplicate ACK branch={} lane={lane} seq={seq} recv_slot={recv_slot}",
                                            branch.branch,
                                        ),
                                    ));
                                }
                                zcraid_mirror_verify_ack(
                                    ack,
                                    branch.branch,
                                    lane,
                                    lane_count,
                                    seq,
                                    extent_bytes,
                                    coordinator.mode(),
                                )?;
                                first_ack[seq_slot].get_or_insert_with(Instant::now);
                                ack_masks[seq_slot][branch_idx] = true;
                                remaining = remaining.checked_sub(1).ok_or_else(|| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "zcraid mirror OFI ACK remaining underflow",
                                    )
                                })?;
                                if ack_masks[seq_slot].iter().all(|seen| *seen) {
                                    let completed_at = Instant::now();
                                    mask_complete[seq_slot] = true;
                                    mask_completed_at[seq_slot] = Some(completed_at);
                                    if let Some(first) = first_ack[seq_slot] {
                                        ack_mask_wait.record_duration(first.elapsed());
                                    }
                                    if seq_slot != next_retire {
                                        hol_blocked[seq_slot] = true;
                                        ack_out_of_order = ack_out_of_order.saturating_add(1);
                                        ack_hol_waits = ack_hol_waits.saturating_add(1);
                                    }
                                    while next_retire < batch && mask_complete[next_retire] {
                                        if hol_blocked[next_retire]
                                            && let Some(completed_at) =
                                                mask_completed_at[next_retire]
                                        {
                                            ack_hol_wait.record_duration(completed_at.elapsed());
                                        }
                                        acks += 1;
                                        ack_latency
                                            .record_duration(issued_slots[next_retire].elapsed());
                                        next_retire += 1;
                                    }
                                }
                            }
                        }
                        if progress != 0 {
                            last_progress = Instant::now();
                        } else if last_progress.elapsed()
                            >= Duration::from_millis(
                                u64::try_from(zcofi_timeout_ms()).unwrap_or(30_000),
                            )
                        {
                            return Err(io::Error::new(
                                io::ErrorKind::TimedOut,
                                format!(
                                    "zcraid mirror OFI ACK matrix timed out lane={lane} seq_base={seq_base} remaining={remaining} batch={batch} branches={}",
                                    branch_eps.len()
                                ),
                            ));
                        } else {
                            thread::yield_now();
                        }
                    }
                    drop(range_guards.take());
                    if next_retire != batch {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!(
                                "zcraid mirror OFI ACK HWM stopped at {next_retire}/{batch} lane={lane} seq_base={seq_base}"
                            ),
                        ));
                    }
                } else {
                    let mut ack_buf = [0u8; ZC_WAL_ACK_HEADER_LEN];
                    for (slot, issued) in issued_slots.iter().take(batch).enumerate() {
                        let seq = seq_base + slot;
                        for branch in &mut branch_eps {
                            let got = branch.endpoint.recv(&mut ack_buf)?;
                            if got != ZC_WAL_ACK_HEADER_LEN {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    format!(
                                        "zcraid mirror OFI ack length mismatch branch={} lane={lane} seq={seq} got={got} expected={ZC_WAL_ACK_HEADER_LEN}",
                                        branch.branch
                                    ),
                                ));
                            }
                            let ack = ZcWalAckHeader::decode(&ack_buf)?;
                            zcraid_mirror_verify_ack(
                                ack,
                                branch.branch,
                                lane,
                                lane_count,
                                seq,
                                extent_bytes,
                                coordinator.mode(),
                            )?;
                        }
                        acks += 1;
                        ack_latency.record_duration(issued.elapsed());
                    }
                    drop(range_guards.take());
                }
            } else {
                drop(range_guards.take());
            }
            seq_base += batch;
        }
    }

    println!(
        "zcraid-mirror-ofi-queue-worker: worker={worker} branches={} lanes={} configured_window={configured_window} branch_post_nowait={} tx_cq_progress=fair-round-robin tx_poll_calls={tx_poll_calls} tx_poll_empty={tx_poll_empty} tx_poll_completions={tx_poll_completions} prepost_ack={} configured_ack_outstanding={configured_ack_outstanding} peak_ack_outstanding={peak_ack_outstanding} ack_poll_calls={ack_poll_calls} ack_poll_empty={ack_poll_empty} ack_out_of_order={ack_out_of_order} ack_hol_waits={ack_hol_waits} {} {} {}",
        branches.len(),
        stream_count / branches.len().max(1),
        yes(branch_post_nowait),
        yes(prepost_ack),
        zcwal_extent_latency_fields("branch_post_skew", &branch_post_skew),
        zcwal_extent_latency_fields("ack_mask_wait", &ack_mask_wait),
        zcwal_extent_latency_fields("ack_hol_wait", &ack_hol_wait),
    );

    let end_thread_cpu = thread_cpu_time().unwrap_or(start_thread_cpu);
    let end_cpu = current_cpu();
    let end_switches = read_thread_context_switches(tid).unwrap_or(start_switches);
    Ok(ZcWalExtentStats {
        worker,
        streams: stream_count,
        payload_bytes,
        wire_bytes,
        extents,
        records,
        acks,
        wall: started.elapsed(),
        cpu: end_thread_cpu.saturating_sub(start_thread_cpu),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        voluntary_switches: end_switches
            .voluntary
            .saturating_sub(start_switches.voluntary),
        involuntary_switches: end_switches
            .involuntary
            .saturating_sub(start_switches.involuntary),
        migrations: end_switches
            .migrations
            .saturating_sub(start_switches.migrations),
        ack_latency,
        uring_recv: UringRecvStats::default(),
    })
}

#[allow(clippy::too_many_arguments)]
fn zcraid_mirror_recv(
    transport: ZcRaidMirrorTransport,
    bind: &str,
    base_port: u16,
    branch_id: usize,
    bytes_per_lane: usize,
    record_bytes: usize,
    workers: usize,
    plan_path: Option<&str>,
    provider: &str,
    endpoint: &str,
    ack_enabled: bool,
    terminal_target: Option<&str>,
) -> io::Result<()> {
    let fallback_branches = branch_id + 1;
    let plan = zcraid_mirror_load_plan(plan_path, 1, fallback_branches.max(2))?;
    let branch = zcraid_mirror_branch(&plan, branch_id)?.clone();
    let lanes = zcraid_mirror_plan_lanes(&plan)?;
    let extents_per_lane =
        zcraid_mirror_validate_shape(bytes_per_lane, record_bytes, plan.branches.len())?;
    let workers = tcp_bench_auto_workers(workers, lanes.len());
    let lane_count = plan.lane_count;
    let branch_count = plan.branches.len();
    let ack_window = zcraid_mirror_ack_window(transport);
    let ack_policy = ZcRaidMirrorAckPolicy::from_env(ack_enabled)?;
    let wire_ack_enabled = ack_policy.waits_for_acks();
    let coord_mode = ZcRaidZlaneCoordMode::from_env()?;
    let coordinator = ZcRaidZlaneCoordinator::new(coord_mode);
    let terminal = terminal_target
        .filter(|target| !target.trim().is_empty() && *target != "-")
        .map(|target| {
            ZcRaidMirrorTerminal::open(
                target,
                record_bytes,
                zcraid_mirror_required_terminal_bytes(lane_count, bytes_per_lane, coord_mode)?,
            )
        })
        .transpose()?;
    if wire_ack_enabled && terminal.is_none() {
        zc_topology_issue(
            "zcraid-mirror-recv",
            "ACKs cover remote userspace receipt only because no terminal target was supplied; pass a persistent zcpwal or allowlisted PARTUUID terminal before reporting durable mirror completion",
        )?;
    }
    if terminal.is_some() && !wire_ack_enabled {
        zc_topology_issue(
            "zcraid-mirror-recv",
            "a terminal target is configured but ACKs are disabled; terminal writes will be drained, but the sender cannot observe a durable HWM",
        )?;
    }
    let tcp_recv_spin_budget = zcraid_mirror_tcp_recv_spin_budget();
    if matches!(
        transport,
        ZcRaidMirrorTransport::OfiMsg | ZcRaidMirrorTransport::Rma
    ) {
        zcofi_report_wire_profile(
            "zcraid-mirror-recv",
            provider,
            record_bytes,
            wire_ack_enabled,
        );
        zcofi_queue_depth_preflight(
            "zcraid-mirror-recv",
            1,
            if wire_ack_enabled {
                ack_window.max(1)
            } else {
                env_usize_or("URING_PLAY_OFI_RX_QUEUE_DEPTH", 64).max(1)
            },
        )?;
    }
    zcraid_mirror_topology_warnings(
        "zcraid-mirror-recv",
        transport,
        provider,
        &plan,
        &lanes,
        workers,
        record_bytes,
        coord_mode,
    )?;
    let ofi_recv_window = if wire_ack_enabled {
        ack_window.max(1)
    } else {
        env_usize_or("URING_PLAY_OFI_RX_QUEUE_DEPTH", 64).max(1)
    };
    let aggregate_rx_outstanding = if matches!(
        transport,
        ZcRaidMirrorTransport::OfiMsg | ZcRaidMirrorTransport::Rma
    ) {
        lanes.len().saturating_mul(ofi_recv_window)
    } else {
        0
    };
    println!(
        "zcraid-mirror-recv: transport={} bind={bind} base_port={base_port} branch={branch_id} lanes={} lane_count={lane_count} bytes_per_lane={bytes_per_lane} extent_bytes={record_bytes} logical_record_bytes={ZC_WAL_RECORD_SIZE} extents_per_lane={extents_per_lane} workers={workers} ack_enabled={} ack_policy={} completion_semantic={} ack_window={ack_window} per_lane_rx_qd={ofi_recv_window} aggregate_rx_outstanding={aggregate_rx_outstanding} zlane_coord={} zlane_lock_shards={} tcp_recv_spin={} tcp_recv_spin_budget={} provider={provider} endpoint={endpoint} branch_domain={} plan_json={} compact_4k={} wire_sequence_header={} terminal={} terminal_ack_semantic={}",
        transport.label(),
        format_cpu_list(&lanes),
        yes(wire_ack_enabled),
        ack_policy.label(),
        ack_policy.label(),
        coord_mode.label(),
        coordinator.lock_count(),
        yes(tcp_recv_spin_budget.is_some()),
        tcp_recv_spin_budget
            .map(|budget| budget.to_string())
            .unwrap_or_else(|| "off".to_string()),
        branch.fabric_domain.as_deref().unwrap_or("auto"),
        yes(plan.from_plan_json),
        yes(zcofi_compact_4k_enabled(
            provider,
            record_bytes,
            wire_ack_enabled
        )),
        yes(!zcofi_compact_4k_enabled(
            provider,
            record_bytes,
            wire_ack_enabled
        )),
        terminal
            .as_ref()
            .map(|terminal| terminal.backend.label())
            .unwrap_or("none"),
        if terminal.is_some() && wire_ack_enabled {
            "terminal-write-plus-sync-hwm"
        } else {
            "remote-userspace-receipt-only"
        },
    );
    let mut results = Vec::new();
    match transport {
        ZcRaidMirrorTransport::Tcp => {
            let accepted = zcraid_mirror_tcp_accept_lanes(bind, base_port, &lanes)?;
            let shards = zcraid_mirror_partition_tcp_lanes(accepted, workers);
            let mut handles = Vec::new();
            for (worker, shard) in shards.into_iter().enumerate() {
                if shard.is_empty() {
                    continue;
                }
                let terminal = terminal.clone();
                handles.push(thread::spawn(move || {
                    zcraid_mirror_tcp_recv_worker(
                        worker,
                        branch_id,
                        shard,
                        lane_count,
                        extents_per_lane,
                        record_bytes,
                        wire_ack_enabled,
                        ack_window,
                        coord_mode,
                        tcp_recv_spin_budget,
                        terminal,
                    )
                }));
            }
            for handle in handles {
                let stats = handle
                    .join()
                    .map_err(|_| io::Error::other("zcraid mirror TCP recv worker panicked"))??;
                zcraid_mirror_print_worker("zcraid-mirror-recv", &stats);
                results.push(stats);
            }
        }
        ZcRaidMirrorTransport::OfiMsg => {
            let lane_shards = zcraid_mirror_partition_lanes(&lanes, workers);
            let provider = Arc::new(provider.to_string());
            let endpoint = Arc::new(libfabric_endpoint_pingpong(endpoint)?.to_string());
            let bind = Arc::new(bind.to_string());
            let mut handles = Vec::new();
            for (worker, shard) in lane_shards.into_iter().enumerate() {
                if shard.is_empty() {
                    continue;
                }
                let provider = Arc::clone(&provider);
                let endpoint = Arc::clone(&endpoint);
                let bind = Arc::clone(&bind);
                let branch = branch.clone();
                let terminal = terminal.clone();
                handles.push(thread::spawn(move || {
                    zcraid_mirror_ofi_recv_worker(
                        worker,
                        provider,
                        endpoint,
                        bind,
                        branch,
                        base_port,
                        shard,
                        lane_count,
                        extents_per_lane,
                        record_bytes,
                        wire_ack_enabled,
                        if wire_ack_enabled {
                            ack_window
                        } else {
                            env_usize_or("URING_PLAY_OFI_RX_QUEUE_DEPTH", 64).max(1)
                        },
                        ack_window,
                        coord_mode,
                        terminal,
                    )
                }));
            }
            for handle in handles {
                let stats = handle
                    .join()
                    .map_err(|_| io::Error::other("zcraid mirror OFI recv worker panicked"))??;
                zcraid_mirror_print_worker("zcraid-mirror-recv", &stats);
                results.push(stats);
            }
        }
        ZcRaidMirrorTransport::Rma => {
            if !wire_ack_enabled {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "the RDMA mirror requires durable acknowledgements",
                ));
            }
            let terminal = terminal.ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "the RDMA mirror requires a persistent terminal target",
                )
            })?;
            let lane_shards = zcraid_mirror_partition_lanes(&lanes, workers);
            let provider = Arc::new(provider.to_string());
            let endpoint = Arc::new(libfabric_endpoint_pingpong(endpoint)?.to_string());
            let bind = Arc::new(bind.to_string());
            let mut handles = Vec::new();
            for (worker, shard) in lane_shards.into_iter().enumerate() {
                if shard.is_empty() {
                    continue;
                }
                let provider = Arc::clone(&provider);
                let endpoint = Arc::clone(&endpoint);
                let bind = Arc::clone(&bind);
                let branch = branch.clone();
                let terminal = terminal.clone();
                handles.push(thread::spawn(move || {
                    zcraid_mirror_rma_recv_worker(
                        worker,
                        provider,
                        endpoint,
                        bind,
                        branch,
                        base_port,
                        shard,
                        lane_count,
                        extents_per_lane,
                        record_bytes,
                        ack_window,
                        coord_mode,
                        terminal,
                    )
                }));
            }
            for handle in handles {
                let stats = handle
                    .join()
                    .map_err(|_| io::Error::other("zcraid mirror RMA recv worker panicked"))??;
                zcraid_mirror_print_worker("zcraid-mirror-recv", &stats);
                results.push(stats);
            }
        }
    }
    let total = zcwal_extent_sum(&results);
    zcraid_mirror_print_summary(
        "zcraid-mirror-recv",
        transport,
        branch_count,
        lanes.len(),
        workers,
        record_bytes,
        ack_window,
        ack_policy,
        coord_mode,
        coordinator.lock_count(),
        &total,
    );
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn zcraid_mirror_send(
    transport: ZcRaidMirrorTransport,
    addr: &str,
    base_ports: Vec<u16>,
    bytes_per_lane: usize,
    record_bytes: usize,
    workers: usize,
    plan_path: Option<&str>,
    provider: &str,
    endpoint: &str,
    ack_enabled: bool,
) -> io::Result<()> {
    let plan = zcraid_mirror_load_plan(plan_path, 1, base_ports.len())?;
    let lanes = zcraid_mirror_plan_lanes(&plan)?;
    let extents_per_lane =
        zcraid_mirror_validate_shape(bytes_per_lane, record_bytes, plan.branches.len())?;
    if base_ports.len() != plan.branches.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "zcraid mirror sender got {} base ports for {} plan branches",
                base_ports.len(),
                plan.branches.len()
            ),
        ));
    }
    let addrs = zcraid_mirror_parse_addrs(addr, plan.branches.len())?;
    let tcp_source_ips = if matches!(transport, ZcRaidMirrorTransport::Tcp) {
        zcraid_mirror_tcp_source_ips_from_env(plan.branches.len())?
    } else {
        vec![None; plan.branches.len()]
    };
    let branches = Arc::new(
        plan.branches
            .iter()
            .cloned()
            .zip(addrs)
            .zip(base_ports)
            .zip(tcp_source_ips)
            .map(
                |(((plan, addr), base_port), source_ip)| ZcRaidMirrorBranchTarget {
                    plan,
                    addr,
                    base_port,
                    source_ip,
                },
            )
            .collect::<Vec<_>>(),
    );
    let workers = tcp_bench_auto_workers(workers, lanes.len());
    let lane_count = plan.lane_count;
    let branch_count = plan.branches.len();
    let ack_window = zcraid_mirror_ack_window(transport);
    let requested_ack_policy = ZcRaidMirrorAckPolicy::from_env(ack_enabled)?;
    let ack_policy = requested_ack_policy;
    if transport == ZcRaidMirrorTransport::Rma && !ack_policy.waits_for_acks() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "the RDMA mirror requires durable terminal acknowledgements",
        ));
    }
    if transport == ZcRaidMirrorTransport::Rma
        && !env_enabled_or("URING_PLAY_OFI_RMA_WRITE_DELIVERY_COMPLETE", true)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "RDMA mirror delivery-complete cannot be disabled because the data/doorbell visibility order would be unsafe",
        ));
    }
    let wire_ack_enabled = ack_policy.waits_for_acks();
    let coord_mode = ZcRaidZlaneCoordMode::from_env()?;
    let coordinator = Arc::new(ZcRaidZlaneCoordinator::new(coord_mode));
    let wait_window = ack_policy.wait_window(ack_window, extents_per_lane);
    if coord_mode.serializes_overlaps()
        && matches!(ack_policy, ZcRaidMirrorAckPolicy::Remote)
        && ack_window > 1
    {
        eprintln!(
            "PERF NOTE: zcraid-mirror-send range-lock mode holds sorted batch range locks until all branch ACKs arrive; requested_ack_window={ack_window} zlane_lock_shards={}",
            coordinator.lock_count()
        );
    }
    if matches!(
        transport,
        ZcRaidMirrorTransport::OfiMsg | ZcRaidMirrorTransport::Rma
    ) {
        zcofi_report_wire_profile(
            "zcraid-mirror-send",
            provider,
            record_bytes,
            wire_ack_enabled,
        );
        if transport == ZcRaidMirrorTransport::OfiMsg
            && branch_count > 1
            && !env_enabled_or("URING_PLAY_OFI_BRANCH_POST_NOWAIT", true)
        {
            zc_topology_issue(
                "zcraid-mirror-send",
                "multi-branch OFI posting is configured to wait branch-by-branch",
            )?;
        }
        if transport == ZcRaidMirrorTransport::OfiMsg
            && wire_ack_enabled
            && ack_window > 1
            && !env_enabled_or("URING_PLAY_OFI_PREPOST_ACK", true)
        {
            zc_topology_issue(
                "zcraid-mirror-send",
                "windowed OFI ACK preposting is disabled; the branch-by-window ACK matrix cannot run",
            )?;
        }
        if transport == ZcRaidMirrorTransport::Rma
            && ack_window > 1
            && !env_enabled_or("URING_PLAY_OFI_RMA_WRITE_MORE", false)
        {
            zc_topology_issue(
                "zcraid-mirror-send",
                "windowed RDMA posting is not using FI_MORE doorbell coalescing; set URING_PLAY_OFI_RMA_WRITE_MORE=1",
            )?;
        }
        let required_window = if wire_ack_enabled {
            ack_window.max(1)
        } else {
            env_usize_or("URING_PLAY_OFI_TX_QUEUE_DEPTH", 64).max(1)
        };
        zcofi_queue_depth_preflight(
            "zcraid-mirror-send",
            required_window,
            if wire_ack_enabled {
                ack_window.max(1)
            } else {
                1
            },
        )?;
    }
    zcraid_mirror_topology_warnings(
        "zcraid-mirror-send",
        transport,
        provider,
        &plan,
        &lanes,
        workers,
        record_bytes,
        coord_mode,
    )?;
    for branch in branches.iter() {
        println!(
            "zcraid-mirror-send-branch-port: branch={} addr={} base_port={} source_ip={} domain={}",
            branch.plan.branch,
            branch.addr,
            branch.base_port,
            branch
                .source_ip
                .map(|ip| ip.to_string())
                .unwrap_or_else(|| "kernel-route".to_string()),
            branch.plan.fabric_domain.as_deref().unwrap_or("auto")
        );
    }
    let ofi_branch_post_nowait = transport == ZcRaidMirrorTransport::OfiMsg
        && env_enabled_or("URING_PLAY_OFI_BRANCH_POST_NOWAIT", true);
    let ofi_prepost_ack = transport == ZcRaidMirrorTransport::OfiMsg
        && wire_ack_enabled
        && env_enabled_or("URING_PLAY_OFI_PREPOST_ACK", true);
    let ofi_window = if wire_ack_enabled {
        ack_window.max(1)
    } else {
        env_usize_or("URING_PLAY_OFI_TX_QUEUE_DEPTH", 64).max(1)
    };
    let aggregate_tx_outstanding = lanes
        .len()
        .saturating_mul(branch_count)
        .saturating_mul(ofi_window);
    let aggregate_ack_outstanding = if ofi_prepost_ack {
        aggregate_tx_outstanding
    } else {
        0
    };
    println!(
        "zcraid-mirror-send: transport={} addr={addr} branches={} lanes={} lane_count={lane_count} bytes_per_lane={bytes_per_lane} extent_bytes={record_bytes} logical_record_bytes={ZC_WAL_RECORD_SIZE} extents_per_lane={extents_per_lane} workers={workers} ack_enabled={} ack_policy={} completion_semantic={} ack_window={ack_window} ack_wait_window={wait_window} per_lane_branch_qd={ofi_window} aggregate_tx_outstanding={aggregate_tx_outstanding} aggregate_ack_outstanding={aggregate_ack_outstanding} zlane_coord={} zlane_lock_shards={} provider={provider} endpoint={endpoint} plan_json={} compact_4k={} wire_sequence_header={} payload_inject={} ack_inject={} branch_post_nowait={} prepost_ack={}",
        transport.label(),
        branch_count,
        format_cpu_list(&lanes),
        yes(wire_ack_enabled),
        ack_policy.label(),
        ack_policy.label(),
        coord_mode.label(),
        coordinator.lock_count(),
        yes(plan.from_plan_json),
        yes(zcofi_compact_4k_enabled(
            provider,
            record_bytes,
            wire_ack_enabled
        )),
        yes(!zcofi_compact_4k_enabled(
            provider,
            record_bytes,
            wire_ack_enabled
        )),
        yes(env_enabled_or("URING_PLAY_OFI_PAYLOAD_INJECT", false)),
        yes(env_enabled_or("URING_PLAY_OFI_ACK_INJECT", false)),
        yes(ofi_branch_post_nowait),
        yes(ofi_prepost_ack),
    );
    let lane_shards = zcraid_mirror_partition_lanes(&lanes, workers);
    let mut handles = Vec::new();
    match transport {
        ZcRaidMirrorTransport::Tcp => {
            for (worker, shard) in lane_shards.into_iter().enumerate() {
                if shard.is_empty() {
                    continue;
                }
                let branches = Arc::clone(&branches);
                let coordinator = Arc::clone(&coordinator);
                handles.push(thread::spawn(move || {
                    zcraid_mirror_tcp_send_worker(
                        worker,
                        shard,
                        branches,
                        coordinator,
                        lane_count,
                        extents_per_lane,
                        record_bytes,
                        ack_policy,
                        ack_window,
                    )
                }));
            }
        }
        ZcRaidMirrorTransport::OfiMsg => {
            let provider = Arc::new(provider.to_string());
            let endpoint = Arc::new(libfabric_endpoint_pingpong(endpoint)?.to_string());
            for (worker, shard) in lane_shards.into_iter().enumerate() {
                if shard.is_empty() {
                    continue;
                }
                let provider = Arc::clone(&provider);
                let endpoint = Arc::clone(&endpoint);
                let branches = Arc::clone(&branches);
                let coordinator = Arc::clone(&coordinator);
                handles.push(thread::spawn(move || {
                    zcraid_mirror_ofi_send_worker(
                        worker,
                        provider,
                        endpoint,
                        shard,
                        branches,
                        coordinator,
                        lane_count,
                        extents_per_lane,
                        record_bytes,
                        wire_ack_enabled,
                        ack_window,
                    )
                }));
            }
        }
        ZcRaidMirrorTransport::Rma => {
            let provider = Arc::new(provider.to_string());
            let endpoint = Arc::new(libfabric_endpoint_pingpong(endpoint)?.to_string());
            for (worker, shard) in lane_shards.into_iter().enumerate() {
                if shard.is_empty() {
                    continue;
                }
                let provider = Arc::clone(&provider);
                let endpoint = Arc::clone(&endpoint);
                let branches = Arc::clone(&branches);
                let coordinator = Arc::clone(&coordinator);
                handles.push(thread::spawn(move || {
                    zcraid_mirror_rma_send_worker(
                        worker,
                        provider,
                        endpoint,
                        shard,
                        branches,
                        coordinator,
                        lane_count,
                        extents_per_lane,
                        record_bytes,
                        ack_window,
                    )
                }));
            }
        }
    }
    let mut results = Vec::new();
    for handle in handles {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other("zcraid mirror send worker panicked"))??;
        zcraid_mirror_print_worker("zcraid-mirror-send", &stats);
        results.push(stats);
    }
    let total = zcwal_extent_sum(&results);
    zcraid_mirror_print_summary(
        "zcraid-mirror-send",
        transport,
        branch_count,
        lanes.len(),
        workers,
        record_bytes,
        wait_window,
        ack_policy,
        coord_mode,
        coordinator.lock_count(),
        &total,
    );
    Ok(())
}

const TCP_WAL_RECV_USER_DATA: u64 = 1u64 << 63;
const TCP_WAL_WRITE_USER_DATA: u64 = 1u64 << 62;
const TCP_WAL_SLOT_MASK: u64 = TCP_WAL_WRITE_USER_DATA - 1;

#[derive(Clone, Copy, PartialEq, Eq)]
enum TcpWalCqeKind {
    Recv,
    Write,
}

fn tcp_wal_recv_user_data(slot: usize) -> u64 {
    TCP_WAL_RECV_USER_DATA | slot as u64
}

fn tcp_wal_write_user_data(slot: usize) -> u64 {
    TCP_WAL_WRITE_USER_DATA | slot as u64
}

fn tcp_wal_decode_user_data(user_data: u64) -> io::Result<(TcpWalCqeKind, usize)> {
    let slot = (user_data & TCP_WAL_SLOT_MASK) as usize;
    if (user_data & TCP_WAL_RECV_USER_DATA) != 0 {
        Ok((TcpWalCqeKind::Recv, slot))
    } else if (user_data & TCP_WAL_WRITE_USER_DATA) != 0 {
        Ok((TcpWalCqeKind::Write, slot))
    } else {
        Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("unexpected TCP WAL CQE user_data={user_data}"),
        ))
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum TcpWalSlotStage {
    Free,
    Recv,
    Write,
}

struct TcpWalSlot {
    stage: TcpWalSlotStage,
    conn: usize,
    filled: usize,
    file_offset: u64,
}

impl Default for TcpWalSlot {
    fn default() -> Self {
        Self {
            stage: TcpWalSlotStage::Free,
            conn: 0,
            filled: 0,
            file_offset: 0,
        }
    }
}

struct TcpWalConn {
    fd: i32,
    fixed_file: bool,
    received: usize,
    recv_in_flight: bool,
}

#[derive(Clone, Copy)]
struct TcpWalWorkerResult {
    worker: usize,
    streams: usize,
    received_bytes: usize,
    written_bytes: usize,
    chunks: usize,
    elapsed: Duration,
    target_cpu: i32,
    affinity_applied: bool,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum TcpWalPipelineMode {
    SameCore,
    Split,
    Zcrx,
}

impl TcpWalPipelineMode {
    fn from_env() -> io::Result<Self> {
        match env::var("URING_PLAY_TCP_WAL_MODE")
            .unwrap_or_else(|_| "same-core".to_string())
            .as_str()
        {
            "" | "same-core" | "same" | "coupled" => Ok(Self::SameCore),
            "split" | "split-rx-wal" | "decoupled" => Ok(Self::Split),
            "zcrx" | "recv-zc" | "zero-copy-rx" => Ok(Self::Zcrx),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown URING_PLAY_TCP_WAL_MODE={other:?}; use same-core, split, or zcrx"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::SameCore => "same-core",
            Self::Split => "split",
            Self::Zcrx => "zcrx",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TcpWalWriteMode {
    Null,
    Slot,
    Write,
    WriteFixed,
    WriteFixedFile,
}

impl TcpWalWriteMode {
    fn from_env() -> io::Result<Self> {
        match env::var("URING_PLAY_TCP_WAL_WRITE_MODE")
            .unwrap_or_else(|_| "auto".to_string())
            .as_str()
        {
            "" | "auto" | "autodetect" | "sniff" => Self::auto_detect(),
            "fixed-file" | "fixedfile" | "fixedbufs-registerfiles" | "fast" => {
                Ok(Self::WriteFixedFile)
            }
            "null" | "sink" | "discard" | "none" => Ok(Self::Null),
            "fixed" | "write-fixed" | "fixedbuf" | "fixedbufs" => Ok(Self::WriteFixed),
            "write" | "plain" | "normal" => Ok(Self::Write),
            "slot" | "slots" | "io-slot" | "io-slots" => Ok(Self::Slot),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "unknown URING_PLAY_TCP_WAL_WRITE_MODE={other:?}; use auto, fixed-file, fixed, write, slot, or null"
                ),
            )),
        }
    }

    fn auto_detect() -> io::Result<Self> {
        match kernel_supports_io_slots() {
            Ok(true) => {
                eprintln!("tcp-wal-write-auto: io-slot kernel support detected; using slot");
                Ok(Self::Slot)
            }
            Ok(false) => {
                eprintln!(
                    "tcp-wal-write-auto: io-slot kernel support unavailable; using fixed-file"
                );
                Ok(Self::WriteFixedFile)
            }
            Err(err) => {
                eprintln!(
                    "tcp-wal-write-auto: io_uring opcode query failed ({err}); using fixed-file"
                );
                Ok(Self::WriteFixedFile)
            }
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Null => "null",
            Self::Slot => "slot",
            Self::Write => "write",
            Self::WriteFixed => "fixed",
            Self::WriteFixedFile => "fixed-file",
        }
    }

    fn needs_registered_buffers(self) -> bool {
        matches!(self, Self::Slot | Self::WriteFixed | Self::WriteFixedFile)
    }

    fn needs_registered_files(self) -> bool {
        matches!(self, Self::Slot | Self::WriteFixedFile)
    }

    fn needs_io_slots(self) -> bool {
        matches!(self, Self::Slot)
    }

    fn is_null(self) -> bool {
        matches!(self, Self::Null)
    }
}

fn tcp_wal_fixed_recv_enabled() -> bool {
    env_enabled_or("URING_PLAY_TCP_WAL_FIXED_RECV", true)
}

fn fixed_file_index_i32(index: usize, label: &str) -> io::Result<i32> {
    i32::try_from(index).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{label} fixed-file index {index} does not fit in i32"),
        )
    })
}

