struct ZcnblkPendingIo {
    op: u16,
    request_id: u64,
    len: usize,
    offset: u64,
    issued_at: Instant,
}

fn zcnblk_track_pending_io(
    pending: &mut BTreeMap<(u16, u64), ZcnblkPendingIo>,
    op: u16,
    request_id: u64,
    len: usize,
    offset: u64,
    issued_at: Instant,
) -> io::Result<()> {
    let key = (op, request_id);
    if pending.contains_key(&key) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("duplicate pending zcnblk request op={op} request_id={request_id}"),
        ));
    }
    pending.insert(
        key,
        ZcnblkPendingIo {
            op,
            request_id,
            len,
            offset,
            issued_at,
        },
    );
    Ok(())
}

fn zcnblk_complete_pending_io(
    pending: &mut BTreeMap<(u16, u64), ZcnblkPendingIo>,
    expected_op: u16,
    request_id: u64,
    len: usize,
    offset: u64,
    latency: &mut LatencyHistogram,
    context: &str,
) -> io::Result<()> {
    let pending = pending.remove(&(expected_op, request_id)).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{context} had no pending zcnblk request op={expected_op} request_id={request_id} offset={offset}"
            ),
        )
    })?;
    if pending.op != expected_op
        || pending.request_id != request_id
        || pending.len != len
        || pending.offset != offset
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{context} pending request mismatch op={} request_id={} len={} offset={} expected_op={} request_id={} len={} offset={offset}",
                pending.op,
                pending.request_id,
                pending.len,
                pending.offset,
                expected_op,
                request_id,
                len
            ),
        ));
    }
    latency.record_duration(pending.issued_at.elapsed());
    Ok(())
}

fn zcnblk_complete_pending_io_by_offset(
    pending: &mut BTreeMap<(u16, u64), ZcnblkPendingIo>,
    expected_op: u16,
    len: usize,
    offset: u64,
    latency: &mut LatencyHistogram,
    context: &str,
) -> io::Result<()> {
    let key = pending
        .iter()
        .find_map(|(key, item)| {
            (item.op == expected_op && item.len == len && item.offset == offset).then_some(*key)
        })
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "{context} had no pending zcnblk request op={expected_op} len={len} offset={offset}"
                ),
            )
        })?;
    let pending = pending.remove(&key).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{context} pending zcnblk request disappeared for offset={offset}"),
        )
    })?;
    latency.record_duration(pending.issued_at.elapsed());
    Ok(())
}

