#[derive(Clone, Copy, Default)]
struct ZcnblkFanWalReadCacheStats {
    leased_response_frames: usize,
    leased_response_bytes: usize,
    materialized_response_frames: usize,
    materialized_response_bytes: usize,
    fallback_materialized_response_frames: usize,
    fallback_materialized_response_bytes: usize,
    response_source_parts: usize,
    response_payload_iovecs: usize,
    response_coalesced_parts: usize,
    response_total_iovecs: usize,
    response_writev_calls: usize,
    range_response_batches: usize,
    range_response_runs: usize,
    range_response_saved_headers: usize,
}

impl ZcnblkFanWalReadCacheStats {
    fn add(&mut self, other: Self) {
        self.leased_response_frames = self
            .leased_response_frames
            .saturating_add(other.leased_response_frames);
        self.leased_response_bytes = self
            .leased_response_bytes
            .saturating_add(other.leased_response_bytes);
        self.materialized_response_frames = self
            .materialized_response_frames
            .saturating_add(other.materialized_response_frames);
        self.materialized_response_bytes = self
            .materialized_response_bytes
            .saturating_add(other.materialized_response_bytes);
        self.fallback_materialized_response_frames = self
            .fallback_materialized_response_frames
            .saturating_add(other.fallback_materialized_response_frames);
        self.fallback_materialized_response_bytes = self
            .fallback_materialized_response_bytes
            .saturating_add(other.fallback_materialized_response_bytes);
        self.response_source_parts = self
            .response_source_parts
            .saturating_add(other.response_source_parts);
        self.response_payload_iovecs = self
            .response_payload_iovecs
            .saturating_add(other.response_payload_iovecs);
        self.response_coalesced_parts = self
            .response_coalesced_parts
            .saturating_add(other.response_coalesced_parts);
        self.response_total_iovecs = self
            .response_total_iovecs
            .saturating_add(other.response_total_iovecs);
        self.response_writev_calls = self
            .response_writev_calls
            .saturating_add(other.response_writev_calls);
        self.range_response_batches = self
            .range_response_batches
            .saturating_add(other.range_response_batches);
        self.range_response_runs = self
            .range_response_runs
            .saturating_add(other.range_response_runs);
        self.range_response_saved_headers = self
            .range_response_saved_headers
            .saturating_add(other.range_response_saved_headers);
    }

    fn note_read_response(&mut self, read: &ZcnblkFanWalLocalRead, payload_iovecs: usize) {
        self.note_read_responses(std::iter::once(read), payload_iovecs);
    }

    fn note_read_responses<'a>(
        &mut self,
        reads: impl IntoIterator<Item = &'a ZcnblkFanWalLocalRead>,
        payload_iovecs: usize,
    ) {
        let mut source_parts = 0usize;
        let mut leased_frames = 0usize;
        let mut leased_bytes = 0usize;
        let mut materialized_frames = 0usize;
        let mut materialized_bytes = 0usize;
        for read in reads {
            source_parts = source_parts.saturating_add(read.source_part_count());
            match read {
                ZcnblkFanWalLocalRead::Leased { .. } => {
                    leased_frames = leased_frames.saturating_add(1);
                    leased_bytes = leased_bytes.saturating_add(read.len());
                }
                ZcnblkFanWalLocalRead::Materialized(data) => {
                    materialized_frames = materialized_frames.saturating_add(1);
                    materialized_bytes = materialized_bytes.saturating_add(data.len());
                }
            }
        }
        self.leased_response_frames = self.leased_response_frames.saturating_add(leased_frames);
        self.leased_response_bytes = self.leased_response_bytes.saturating_add(leased_bytes);
        self.materialized_response_frames = self
            .materialized_response_frames
            .saturating_add(materialized_frames);
        self.materialized_response_bytes = self
            .materialized_response_bytes
            .saturating_add(materialized_bytes);
        self.response_source_parts = self.response_source_parts.saturating_add(source_parts);
        self.response_payload_iovecs = self.response_payload_iovecs.saturating_add(payload_iovecs);
        self.response_coalesced_parts = self
            .response_coalesced_parts
            .saturating_add(source_parts.saturating_sub(payload_iovecs));
    }

    fn note_response_writev(&mut self, total_iovecs: usize) {
        self.response_writev_calls = self.response_writev_calls.saturating_add(1);
        self.response_total_iovecs = self.response_total_iovecs.saturating_add(total_iovecs);
    }

    fn note_range_response(&mut self, frames: usize, runs: usize) {
        self.range_response_batches = self.range_response_batches.saturating_add(1);
        self.range_response_runs = self.range_response_runs.saturating_add(runs);
        self.range_response_saved_headers = self
            .range_response_saved_headers
            .saturating_add(frames.saturating_sub(runs));
    }

    fn note_fallback_materialized_read(&mut self, len: usize) {
        self.materialized_response_frames = self.materialized_response_frames.saturating_add(1);
        self.materialized_response_bytes = self.materialized_response_bytes.saturating_add(len);
        self.fallback_materialized_response_frames =
            self.fallback_materialized_response_frames.saturating_add(1);
        self.fallback_materialized_response_bytes = self
            .fallback_materialized_response_bytes
            .saturating_add(len);
    }
}

