#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ZcnblkFanWalDirtyPressure {
    None,
    Soft,
    Hard,
}

impl ZcnblkFanWalDirtyPressure {
    fn should_drain(self) -> bool {
        matches!(self, Self::Soft | Self::Hard)
    }
}

#[derive(Clone, Copy, Debug)]
struct ZcnblkFanWalDirtySnapshot {
    current_bytes: usize,
    max_observed_bytes: usize,
    total_admit_bytes: usize,
    total_release_bytes: usize,
    total_admit_events: usize,
    total_release_events: usize,
    total_soft_pressure_events: usize,
    total_hard_pressure_events: usize,
    total_wait_events: usize,
    total_wait: Duration,
}

impl ZcnblkFanWalDirtyBudgetConfig {
    fn from_env() -> io::Result<Self> {
        let enabled = env_enabled_or("URING_PLAY_ZCNBLK_WAL_WRITEBACK", true)
            && env_enabled_or("URING_PLAY_ZCNBLK_WAL_DIRTY_BUDGET", true);
        let hard_bytes = zcnblk_fan_wal_dirty_size_env(&[
            "URING_PLAY_ZCNBLK_FAN_WAL_HARD_DIRTY_BYTES",
            "URING_PLAY_ZCNBLK_FAN_WAL_MAX_DIRTY_BYTES",
            "URING_PLAY_ZCNBLK_WAL_HARD_DIRTY_BYTES",
            "URING_PLAY_ZCNBLK_WAL_MAX_DIRTY_BYTES",
            "URING_PLAY_ZCNBLK_WAL_DIRTY_BYTES",
        ])?
        .unwrap_or(DEFAULT_ZCNBLK_FAN_WAL_MAX_DIRTY_BYTES);
        let soft_bytes = zcnblk_fan_wal_dirty_size_env(&[
            "URING_PLAY_ZCNBLK_FAN_WAL_SOFT_DIRTY_BYTES",
            "URING_PLAY_ZCNBLK_WAL_SOFT_DIRTY_BYTES",
        ])?
        .unwrap_or_else(|| hard_bytes.saturating_mul(70) / 100);
        if enabled && hard_bytes == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "fan WAL hard/max dirty bytes must be non-zero when WAL writeback is enabled",
            ));
        }
        if enabled && soft_bytes > hard_bytes {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "URING_PLAY_ZCNBLK_WAL_SOFT_DIRTY_BYTES ({soft_bytes}) exceeds hard dirty bytes ({hard_bytes})"
                ),
            ));
        }
        Ok(Self {
            enabled,
            soft_bytes,
            hard_bytes,
        })
    }

    fn label(self) -> String {
        if self.enabled {
            format!(
                "writeback_dirty_budget=enabled soft_dirty_bytes={} hard_dirty_bytes={}",
                self.soft_bytes, self.hard_bytes
            )
        } else {
            "writeback_dirty_budget=disabled".to_string()
        }
    }
}

fn zcnblk_fan_wal_dirty_size_env(names: &[&str]) -> io::Result<Option<usize>> {
    for name in names {
        match env::var(name) {
            Ok(value) if !value.trim().is_empty() => {
                return parse_size_arg(&value, name).map(Some);
            }
            _ => {}
        }
    }
    Ok(None)
}

impl ZcnblkFanWalDirtyBudget {
    fn new(config: ZcnblkFanWalDirtyBudgetConfig) -> Self {
        Self {
            config,
            inner: Arc::new((
                Mutex::new(ZcnblkFanWalDirtyBudgetInner::default()),
                Condvar::new(),
            )),
        }
    }

    fn pressure(&self, bytes: usize) -> io::Result<ZcnblkFanWalDirtyPressure> {
        if !self.config.enabled || bytes == 0 {
            return Ok(ZcnblkFanWalDirtyPressure::None);
        }
        if bytes > self.config.hard_bytes {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "single fan WAL write batch dirty payload bytes={} exceeds hard dirty budget={}",
                    bytes, self.config.hard_bytes
                ),
            ));
        }
        let (lock, _) = &*self.inner;
        let inner = lock.lock().map_err(|_| {
            io::Error::new(io::ErrorKind::Other, "fan WAL dirty budget lock poisoned")
        })?;
        let projected = inner.current_bytes.checked_add(bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL dirty budget projection overflow",
            )
        })?;
        if projected > self.config.hard_bytes {
            Ok(ZcnblkFanWalDirtyPressure::Hard)
        } else if projected > self.config.soft_bytes {
            Ok(ZcnblkFanWalDirtyPressure::Soft)
        } else {
            Ok(ZcnblkFanWalDirtyPressure::None)
        }
    }

    fn reserve(
        &self,
        bytes: usize,
        stats: &mut ZcnblkFanWalDirtyStats,
    ) -> io::Result<Option<ZcnblkFanWalDirtyLease>> {
        if !self.config.enabled || bytes == 0 {
            return Ok(None);
        }
        if bytes > self.config.hard_bytes {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "single fan WAL write batch dirty payload bytes={} exceeds hard dirty budget={}",
                    bytes, self.config.hard_bytes
                ),
            ));
        }

        let (lock, cvar) = &*self.inner;
        let mut inner = lock.lock().map_err(|_| {
            io::Error::new(io::ErrorKind::Other, "fan WAL dirty budget lock poisoned")
        })?;
        let mut noted_hard_pressure = false;
        let mut local_wait_events = 0usize;
        let wait_started = Instant::now();
        while inner.current_bytes.checked_add(bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL dirty budget reservation overflow",
            )
        })? > self.config.hard_bytes
        {
            if !noted_hard_pressure {
                stats.hard_pressure_events =
                    stats.hard_pressure_events.checked_add(1).ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "fan WAL dirty hard pressure count overflow",
                        )
                    })?;
                inner.total_hard_pressure_events = inner
                    .total_hard_pressure_events
                    .checked_add(1)
                    .ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "fan WAL dirty hard pressure total overflow",
                        )
                    })?;
                noted_hard_pressure = true;
            }
            stats.wait_events = stats.wait_events.checked_add(1).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL dirty wait count overflow",
                )
            })?;
            local_wait_events = local_wait_events.checked_add(1).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL dirty local wait count overflow",
                )
            })?;
            inner.total_wait_events = inner.total_wait_events.checked_add(1).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL dirty wait total overflow",
                )
            })?;
            inner = cvar.wait(inner).map_err(|_| {
                io::Error::new(io::ErrorKind::Other, "fan WAL dirty budget wait poisoned")
            })?;
        }
        if inner.current_bytes.checked_add(bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL dirty budget soft projection overflow",
            )
        })? > self.config.soft_bytes
        {
            stats.soft_pressure_events =
                stats.soft_pressure_events.checked_add(1).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "fan WAL dirty soft pressure count overflow",
                    )
                })?;
            inner.total_soft_pressure_events = inner
                .total_soft_pressure_events
                .checked_add(1)
                .ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "fan WAL dirty soft pressure total overflow",
                    )
                })?;
        }
        let waited = wait_started.elapsed();
        if local_wait_events > 0 {
            stats.wait = stats.wait.saturating_add(waited);
            inner.total_wait = inner.total_wait.saturating_add(waited);
        }
        inner.current_bytes = inner.current_bytes.checked_add(bytes).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "fan WAL dirty byte overflow")
        })?;
        inner.max_observed_bytes = inner.max_observed_bytes.max(inner.current_bytes);
        inner.total_admit_bytes = inner.total_admit_bytes.checked_add(bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL dirty admit byte overflow",
            )
        })?;
        inner.total_admit_events = inner.total_admit_events.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL dirty admit event overflow",
            )
        })?;
        stats.admit_bytes = stats.admit_bytes.checked_add(bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL handler dirty admit byte overflow",
            )
        })?;
        stats.admit_events = stats.admit_events.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL handler dirty admit event overflow",
            )
        })?;

        Ok(Some(ZcnblkFanWalDirtyLease {
            budget: self.clone(),
            bytes,
            released: false,
        }))
    }

    fn release(&self, bytes: usize) {
        if !self.config.enabled || bytes == 0 {
            return;
        }
        let (lock, cvar) = &*self.inner;
        let Ok(mut inner) = lock.lock() else {
            return;
        };
        inner.current_bytes = inner.current_bytes.saturating_sub(bytes);
        inner.total_release_bytes = inner.total_release_bytes.saturating_add(bytes);
        inner.total_release_events = inner.total_release_events.saturating_add(1);
        cvar.notify_all();
    }

    fn wait_empty(&self, stats: &mut ZcnblkFanWalDirtyStats) -> io::Result<()> {
        if !self.config.enabled {
            return Ok(());
        }
        let (lock, cvar) = &*self.inner;
        let mut inner = lock.lock().map_err(|_| {
            io::Error::new(io::ErrorKind::Other, "fan WAL dirty budget lock poisoned")
        })?;
        if inner.current_bytes == 0 {
            return Ok(());
        }
        let started = Instant::now();
        stats.wait_events = stats.wait_events.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL handler dirty wait event overflow",
            )
        })?;
        inner.total_wait_events = inner.total_wait_events.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL dirty wait event overflow",
            )
        })?;
        while inner.current_bytes != 0 {
            inner = cvar.wait(inner).map_err(|_| {
                io::Error::new(io::ErrorKind::Other, "fan WAL dirty budget lock poisoned")
            })?;
        }
        let waited = started.elapsed();
        stats.wait = stats.wait.saturating_add(waited);
        inner.total_wait = inner.total_wait.saturating_add(waited);
        Ok(())
    }

    fn snapshot(&self) -> ZcnblkFanWalDirtySnapshot {
        let (lock, _) = &*self.inner;
        let inner = lock.lock().expect("fan WAL dirty budget lock poisoned");
        ZcnblkFanWalDirtySnapshot {
            current_bytes: inner.current_bytes,
            max_observed_bytes: inner.max_observed_bytes,
            total_admit_bytes: inner.total_admit_bytes,
            total_release_bytes: inner.total_release_bytes,
            total_admit_events: inner.total_admit_events,
            total_release_events: inner.total_release_events,
            total_soft_pressure_events: inner.total_soft_pressure_events,
            total_hard_pressure_events: inner.total_hard_pressure_events,
            total_wait_events: inner.total_wait_events,
            total_wait: inner.total_wait,
        }
    }
}

impl ZcnblkFanWalDirtyLease {
    fn bytes(&self) -> usize {
        self.bytes
    }

    fn release(&mut self) {
        if !self.released {
            self.budget.release(self.bytes);
            self.released = true;
        }
    }

    fn release_accounted(&mut self, stats: &mut ZcnblkFanWalDirtyStats) -> io::Result<()> {
        if self.released {
            return Ok(());
        }
        let bytes = self.bytes();
        self.release();
        stats.release_bytes = stats.release_bytes.checked_add(bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL handler dirty release byte overflow",
            )
        })?;
        stats.release_events = stats.release_events.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL handler dirty release event overflow",
            )
        })?;
        Ok(())
    }
}

impl Drop for ZcnblkFanWalDirtyLease {
    fn drop(&mut self) {
        self.release();
    }
}

