struct ZcnblkFanWalMemfdLog {
    file: fs::File,
    next_offset: AtomicU64,
}

unsafe impl Send for ZcnblkFanWalMemfdLog {}
unsafe impl Sync for ZcnblkFanWalMemfdLog {}

impl ZcnblkFanWalMemfdLog {
    fn create(handler: usize, lane: usize) -> io::Result<Self> {
        let name = CString::new(format!("zcnblk-fan-dirty-lane-{lane}-handler-{handler}"))
            .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;
        let fd = unsafe {
            libc::syscall(
                libc::SYS_memfd_create,
                name.as_ptr(),
                libc::MFD_CLOEXEC | libc::MFD_ALLOW_SEALING,
            )
        };
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Self {
            file: unsafe { fs::File::from_raw_fd(fd as i32) },
            next_offset: AtomicU64::new(0),
        })
    }

    fn append(&self, payload: &[u8]) -> io::Result<u64> {
        let len = u64::try_from(payload.len()).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "fan WAL memfd payload exceeds u64",
            )
        })?;
        let start = self.next_offset.fetch_add(len, Ordering::Relaxed);
        let end = start.checked_add(len).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "fan WAL memfd log overflow")
        })?;
        self.file.set_len(end)?;
        zc_write_all_at(&self.file, payload, start)?;
        Ok(start)
    }

    fn splice_from_fd(&self, in_fd: RawFd, len: usize) -> io::Result<u64> {
        let len_u64 = u64::try_from(len).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "fan WAL memfd splice payload exceeds u64",
            )
        })?;
        let start = self.next_offset.fetch_add(len_u64, Ordering::Relaxed);
        let end = start.checked_add(len_u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "fan WAL memfd log overflow")
        })?;
        self.file.set_len(end)?;
        splice_fd_to_fd_exact_at(in_fd, self.file.as_raw_fd(), Some(start), len)?;
        Ok(start)
    }

    fn read_exact_at(&self, out: &mut [u8], offset: u64) -> io::Result<()> {
        zc_read_exact_at(&self.file, out, offset)
    }

    fn sendfile_to(&self, out_fd: RawFd, mut offset: u64, mut len: usize) -> io::Result<()> {
        while len != 0 {
            let chunk = len.min(usize::try_from(i32::MAX).unwrap_or(usize::MAX));
            let mut off = libc::off_t::try_from(offset).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "fan WAL memfd offset exceeds off_t",
                )
            })?;
            let sent = unsafe { libc::sendfile(out_fd, self.file.as_raw_fd(), &mut off, chunk) };
            if sent < 0 {
                let err = io::Error::last_os_error();
                if matches!(
                    err.kind(),
                    io::ErrorKind::Interrupted | io::ErrorKind::WouldBlock
                ) {
                    continue;
                }
                return Err(err);
            }
            if sent == 0 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    "fan WAL memfd sendfile wrote zero bytes",
                ));
            }
            let sent = sent as usize;
            offset = offset.checked_add(sent as u64).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "fan WAL memfd send offset overflow",
                )
            })?;
            len -= sent;
        }
        Ok(())
    }
}

fn zcnblk_fan_wal_memfd_dirty_cache_enabled() -> bool {
    env_enabled_or("URING_PLAY_ZCNBLK_FAN_MEMFD_DIRTY_CACHE", false)
        || env_enabled_or("URING_PLAY_ZCNBLK_FAN_MEMFD_CACHE", false)
}

fn zc_loglease_arena_payload_slice<'a>(
    arena: &'a ZcLogLeaseArenaMap,
    start: usize,
    len: usize,
) -> io::Result<&'a [u8]> {
    let end = start.checked_add(len).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "shared WAL arena payload range overflow",
        )
    })?;
    let payload_total = arena
        .payload_bytes
        .checked_mul(arena.slot_count)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "shared WAL arena payload size overflow",
            )
        })?;
    if end > payload_total {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "shared WAL arena payload range outside arena",
        ));
    }
    let absolute = arena.payload_offset.checked_add(start).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "shared WAL arena payload absolute offset overflow",
        )
    })?;
    if absolute.checked_add(len).is_none_or(|end| end > arena.len) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "shared WAL arena payload range outside mmap",
        ));
    }
    let ptr = unsafe { arena.ptr.add(absolute) };
    Ok(unsafe { std::slice::from_raw_parts(ptr.cast_const(), len) })
}

impl ZcnblkFanWalSharedLeaseSource for ZcLogLeaseArenaMap {
    fn payload_slice(&self, start: usize, len: usize) -> io::Result<&[u8]> {
        zc_loglease_arena_payload_slice(self, start, len)
    }
}

impl ZcnblkFanWalDirtyPayload {
    fn read_part(&self, record_offset: usize, len: usize) -> io::Result<ZcnblkFanWalReadPart> {
        match self {
            Self::Copy(data) => {
                if record_offset != 0 || len > data.len() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "fan WAL copy payload can only expose its original 4K record",
                    ));
                }
                Ok(ZcnblkFanWalReadPart::Copy {
                    source: Arc::clone(data),
                    start: 0,
                    len,
                })
            }
            Self::Lease { source, start } => {
                let offset_bytes =
                    record_offset
                        .checked_mul(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty lease read part offset overflow",
                            )
                        })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty lease read part overflow")
                })?;
                let end = start.checked_add(len).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "dirty lease read part end overflow",
                    )
                })?;
                if end > source.len() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "dirty lease read part outside source range",
                    ));
                }
                Ok(ZcnblkFanWalReadPart::Lease {
                    source: Arc::clone(source),
                    start,
                    len,
                })
            }
            Self::Arena { arena, start } => {
                let offset_bytes =
                    record_offset
                        .checked_mul(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty arena read part offset overflow",
                            )
                        })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty arena read part overflow")
                })?;
                let _ = zc_loglease_arena_payload_slice(arena.as_ref(), start, len)?;
                Ok(ZcnblkFanWalReadPart::Arena {
                    arena: Arc::clone(arena),
                    start,
                    len,
                })
            }
            Self::Shared { source, start } => {
                let offset_bytes =
                    record_offset
                        .checked_mul(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty shared lease read part offset overflow",
                            )
                        })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "dirty shared lease read part overflow",
                    )
                })?;
                let _ = source.payload_slice(start, len)?;
                Ok(ZcnblkFanWalReadPart::Shared {
                    source: Arc::clone(source),
                    start,
                    len,
                })
            }
            Self::Memfd { log, start } => {
                let offset_bytes =
                    u64::try_from(record_offset.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(
                        || {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty memfd read part offset overflow",
                            )
                        },
                    )?)
                    .map_err(|_| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "dirty memfd read part offset exceeds u64",
                        )
                    })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "dirty memfd read part start overflow",
                    )
                })?;
                Ok(ZcnblkFanWalReadPart::Memfd {
                    log: Arc::clone(log),
                    start,
                    len,
                })
            }
        }
    }

    fn slice_from_record(&self, record_offset: usize) -> io::Result<Self> {
        match self {
            Self::Copy(data) if record_offset == 0 => Ok(Self::Copy(Arc::clone(data))),
            Self::Copy(_) => Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL copy payload cannot be split at a shifted record",
            )),
            Self::Lease { source, start } => {
                let offset_bytes =
                    record_offset
                        .checked_mul(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty lease offset overflow",
                            )
                        })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty lease start overflow")
                })?;
                Ok(Self::Lease {
                    source: Arc::clone(source),
                    start,
                })
            }
            Self::Arena { arena, start } => {
                let offset_bytes =
                    record_offset
                        .checked_mul(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty arena offset overflow",
                            )
                        })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty arena start overflow")
                })?;
                Ok(Self::Arena {
                    arena: Arc::clone(arena),
                    start,
                })
            }
            Self::Shared { source, start } => {
                let offset_bytes =
                    record_offset
                        .checked_mul(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty shared lease offset overflow",
                            )
                        })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "dirty shared lease start overflow",
                    )
                })?;
                Ok(Self::Shared {
                    source: Arc::clone(source),
                    start,
                })
            }
            Self::Memfd { log, start } => {
                let offset_bytes =
                    u64::try_from(record_offset.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(
                        || {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty memfd slice offset overflow",
                            )
                        },
                    )?)
                    .map_err(|_| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "dirty memfd slice offset exceeds u64",
                        )
                    })?;
                let start = start.checked_add(offset_bytes).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "dirty memfd slice start overflow",
                    )
                })?;
                Ok(Self::Memfd {
                    log: Arc::clone(log),
                    start,
                })
            }
        }
    }
}

impl ZcnblkFanWalReadPart {
    fn copy_into(&self, out: &mut [u8]) -> io::Result<()> {
        match self {
            Self::Copy { source, start, len } => {
                if out.len() != *len {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "read part copy output length mismatch",
                    ));
                }
                let end = start.checked_add(*len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part copy overflow")
                })?;
                let payload = source.get(*start..end).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part copy out of range")
                })?;
                out.copy_from_slice(payload);
                Ok(())
            }
            Self::Lease { source, start, len } => {
                if out.len() != *len {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "read part lease output length mismatch",
                    ));
                }
                let end = start.checked_add(*len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part lease overflow")
                })?;
                let payload = source.get(*start..end).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part lease out of range")
                })?;
                out.copy_from_slice(payload);
                Ok(())
            }
            Self::Arena { arena, start, len } => {
                if out.len() != *len {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "read part arena output length mismatch",
                    ));
                }
                let payload = zc_loglease_arena_payload_slice(arena.as_ref(), *start, *len)?;
                out.copy_from_slice(payload);
                Ok(())
            }
            Self::Shared { source, start, len } => {
                if out.len() != *len {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "read part shared lease output length mismatch",
                    ));
                }
                out.copy_from_slice(source.payload_slice(*start, *len)?);
                Ok(())
            }
            Self::Memfd { log, start, len } => {
                if out.len() != *len {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "read part memfd output length mismatch",
                    ));
                }
                log.read_exact_at(out, *start)
            }
        }
    }

    fn push_payload_iovec(iovecs: &mut Vec<libc::iovec>, payload: &[u8]) -> io::Result<()> {
        if payload.is_empty() {
            return Ok(());
        }
        if let Some(last) = iovecs.last_mut() {
            let last_end = unsafe { (last.iov_base as *mut u8).add(last.iov_len) };
            if last_end.cast_const() == payload.as_ptr() {
                last.iov_len = last.iov_len.checked_add(payload.len()).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "fan WAL read response iovec merge overflow",
                    )
                })?;
                return Ok(());
            }
        }
        iovecs.push(libc::iovec {
            iov_base: payload.as_ptr() as *mut libc::c_void,
            iov_len: payload.len(),
        });
        Ok(())
    }

    fn push_iovec(&self, iovecs: &mut Vec<libc::iovec>) -> io::Result<()> {
        match self {
            Self::Copy { source, start, len } => {
                let end = start.checked_add(*len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part copy iovec overflow")
                })?;
                let payload = source.get(*start..end).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "read part copy iovec out of range",
                    )
                })?;
                Self::push_payload_iovec(iovecs, payload)?;
            }
            Self::Lease { source, start, len } => {
                let end = start.checked_add(*len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part lease iovec overflow")
                })?;
                let payload = source.get(*start..end).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "read part lease iovec out of range",
                    )
                })?;
                Self::push_payload_iovec(iovecs, payload)?;
            }
            Self::Arena { arena, start, len } => {
                let payload = zc_loglease_arena_payload_slice(arena.as_ref(), *start, *len)?;
                Self::push_payload_iovec(iovecs, payload)?;
            }
            Self::Shared { source, start, len } => {
                Self::push_payload_iovec(iovecs, source.payload_slice(*start, *len)?)?;
            }
            Self::Memfd { .. } => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "fan WAL memfd dirty read part requires sendfile response path",
                ));
            }
        }
        Ok(())
    }

    fn write_plaintext_payload_to_tcp(&self, stream: &mut TcpStream) -> io::Result<()> {
        match self {
            Self::Copy { source, start, len } => {
                let end = start.checked_add(*len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part copy write overflow")
                })?;
                let payload = source.get(*start..end).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "read part copy write out of range",
                    )
                })?;
                stream.write_all(payload)
            }
            Self::Lease { source, start, len } => {
                let end = start.checked_add(*len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "read part lease write overflow")
                })?;
                let payload = source.get(*start..end).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "read part lease write out of range",
                    )
                })?;
                stream.write_all(payload)
            }
            Self::Arena { arena, start, len } => {
                let payload = zc_loglease_arena_payload_slice(arena.as_ref(), *start, *len)?;
                stream.write_all(payload)
            }
            Self::Shared { source, start, len } => {
                stream.write_all(source.payload_slice(*start, *len)?)
            }
            Self::Memfd { log, start, len } => log.sendfile_to(stream.as_raw_fd(), *start, *len),
        }
    }
}

fn zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(
    out_fd: RawFd,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
) -> io::Result<usize> {
    let Some(pending) = pending.take() else {
        return Ok(0);
    };
    pending
        .log
        .sendfile_to(out_fd, pending.start, pending.len)?;
    Ok(1)
}

fn zcnblk_fan_wal_write_memfd_payload_to_fd_coalesced_counted(
    out_fd: RawFd,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
    log: Arc<ZcnblkFanWalMemfdLog>,
    start: u64,
    len: usize,
) -> io::Result<usize> {
    if len == 0 {
        return Ok(0);
    }
    let max_coalesce_bytes = zcnblk_fan_wal_memfd_send_coalesce_bytes();
    if max_coalesce_bytes == 0 || len > max_coalesce_bytes {
        let flushed = zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(out_fd, pending)?;
        log.sendfile_to(out_fd, start, len)?;
        return Ok(flushed.saturating_add(1));
    }
    if let Some(existing) = pending.as_mut() {
        let existing_end = existing
            .start
            .checked_add(existing.len as u64)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL pending read memfd payload range overflow",
                )
            })?;
        let merged_len = existing.len.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL pending read memfd payload length overflow",
            )
        })?;
        if Arc::ptr_eq(&existing.log, &log)
            && existing_end == start
            && merged_len <= max_coalesce_bytes
        {
            existing.len = merged_len;
            return Ok(0);
        }
    }
    let flushed = zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(out_fd, pending)?;
    *pending = Some(ZcnblkFanWalPendingMemfdPayloadWrite { log, start, len });
    Ok(flushed)
}

fn zcnblk_fan_wal_write_read_part_plaintext_coalesced(
    upstream: &mut ZcnblkTransport,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
    part: &ZcnblkFanWalReadPart,
) -> io::Result<usize> {
    match part {
        ZcnblkFanWalReadPart::Copy { source, start, len } => {
            let flushed = zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(
                upstream.as_raw_fd(),
                pending,
            )?;
            let end = start.checked_add(*len).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "read part plaintext write overflow",
                )
            })?;
            let payload = source.get(*start..end).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "read part plaintext write out of range",
                )
            })?;
            upstream.write_all(payload)?;
            Ok(flushed.saturating_add((!payload.is_empty()) as usize))
        }
        ZcnblkFanWalReadPart::Lease { source, start, len } => {
            let flushed = zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(
                upstream.as_raw_fd(),
                pending,
            )?;
            let end = start.checked_add(*len).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "read part plaintext write overflow",
                )
            })?;
            let payload = source.get(*start..end).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "read part plaintext write out of range",
                )
            })?;
            upstream.write_all(payload)?;
            Ok(flushed.saturating_add((!payload.is_empty()) as usize))
        }
        ZcnblkFanWalReadPart::Arena { arena, start, len } => {
            let flushed = zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(
                upstream.as_raw_fd(),
                pending,
            )?;
            let payload = zc_loglease_arena_payload_slice(arena.as_ref(), *start, *len)?;
            upstream.write_all(payload)?;
            Ok(flushed.saturating_add((!payload.is_empty()) as usize))
        }
        ZcnblkFanWalReadPart::Shared { source, start, len } => {
            let flushed = zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(
                upstream.as_raw_fd(),
                pending,
            )?;
            let payload = source.payload_slice(*start, *len)?;
            upstream.write_all(payload)?;
            Ok(flushed.saturating_add((!payload.is_empty()) as usize))
        }
        ZcnblkFanWalReadPart::Memfd { log, start, len } => {
            zcnblk_fan_wal_write_memfd_payload_to_fd_coalesced_counted(
                upstream.as_raw_fd(),
                pending,
                Arc::clone(log),
                *start,
                *len,
            )
        }
    }
}

fn zcnblk_fan_wal_write_local_read_plaintext_coalesced(
    upstream: &mut ZcnblkTransport,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
    read: &ZcnblkFanWalLocalRead,
) -> io::Result<usize> {
    match read {
        ZcnblkFanWalLocalRead::Materialized(data) => {
            let flushed = zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(
                upstream.as_raw_fd(),
                pending,
            )?;
            upstream.write_all(data)?;
            Ok(flushed.saturating_add((!data.is_empty()) as usize))
        }
        ZcnblkFanWalLocalRead::Leased { parts, .. } => {
            let mut written_parts = 0usize;
            for part in parts {
                written_parts = written_parts.saturating_add(
                    zcnblk_fan_wal_write_read_part_plaintext_coalesced(upstream, pending, part)?,
                );
            }
            Ok(written_parts)
        }
    }
}

fn zcnblk_fan_wal_write_local_reads_plaintext_coalesced<'a>(
    upstream: &mut ZcnblkTransport,
    reads: impl IntoIterator<Item = &'a ZcnblkFanWalLocalRead>,
) -> io::Result<usize> {
    if upstream.is_encrypted() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "fan WAL memfd cached read response cannot use sendfile with encrypted zcnblk transport",
        ));
    }
    let mut pending = None::<ZcnblkFanWalPendingMemfdPayloadWrite>;
    let mut written_parts = 0usize;
    for read in reads {
        written_parts = written_parts.saturating_add(
            zcnblk_fan_wal_write_local_read_plaintext_coalesced(upstream, &mut pending, read)?,
        );
    }
    written_parts =
        written_parts.saturating_add(zcnblk_fan_wal_flush_pending_memfd_payload_to_fd_counted(
            upstream.as_raw_fd(),
            &mut pending,
        )?);
    Ok(written_parts)
}

impl ZcnblkFanWalLocalRead {
    fn materialized(data: Vec<u8>) -> Self {
        Self::Materialized(data)
    }

    fn leased(len: usize, parts: Vec<ZcnblkFanWalReadPart>) -> Self {
        Self::Leased { len, parts }
    }

    fn len(&self) -> usize {
        match self {
            Self::Materialized(data) => data.len(),
            Self::Leased { len, .. } => *len,
        }
    }

    fn source_part_count(&self) -> usize {
        match self {
            Self::Materialized(data) if data.is_empty() => 0,
            Self::Materialized(_) => 1,
            Self::Leased { parts, .. } => parts.len(),
        }
    }

    fn materialized_mut(&mut self) -> io::Result<&mut [u8]> {
        match self {
            Self::Materialized(data) => Ok(data.as_mut_slice()),
            Self::Leased { .. } => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "fan WAL tried to merge leaf payload into a fully leased dirty-cache read",
            )),
        }
    }

    fn push_iovecs(&self, iovecs: &mut Vec<libc::iovec>) -> io::Result<()> {
        match self {
            Self::Materialized(data) => {
                if !data.is_empty() {
                    iovecs.push(libc::iovec {
                        iov_base: data.as_ptr() as *mut libc::c_void,
                        iov_len: data.len(),
                    });
                }
            }
            Self::Leased { parts, .. } => {
                for part in parts {
                    part.push_iovec(iovecs)?;
                }
            }
        }
        Ok(())
    }

    fn has_memfd_parts(&self) -> bool {
        match self {
            Self::Materialized(_) => false,
            Self::Leased { parts, .. } => parts
                .iter()
                .any(|part| matches!(part, ZcnblkFanWalReadPart::Memfd { .. })),
        }
    }

    fn write_plaintext_payload_to_tcp(&self, stream: &mut TcpStream) -> io::Result<()> {
        match self {
            Self::Materialized(data) => stream.write_all(data),
            Self::Leased { parts, .. } => {
                for part in parts {
                    part.write_plaintext_payload_to_tcp(stream)?;
                }
                Ok(())
            }
        }
    }
}

impl ZcnblkFanWalDirtyExtent {
    fn end_record(&self) -> io::Result<u64> {
        self.first_record
            .checked_add(self.record_count as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "dirty extent overflow"))
    }

    fn contains(&self, record: u64) -> io::Result<bool> {
        Ok(record >= self.first_record && record < self.end_record()?)
    }

    fn slice(&self, record_offset: usize, record_count: usize) -> io::Result<Self> {
        let first_record = self
            .first_record
            .checked_add(record_offset as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "dirty extent overflow"))?;
        Ok(Self {
            first_record,
            record_count,
            sequence: self.sequence,
            payload: self.payload.slice_from_record(record_offset)?,
        })
    }
}

impl ZcnblkFanWalDirtyDirectTable {
    fn from_env(default_shards: usize) -> Self {
        let requested = env_usize_or(
            "URING_PLAY_ZCNBLK_FAN_DIRTY_DIRECT_RECORDS",
            env_usize_or("URING_PLAY_ZCNBLK_FAN_DIRTY_LATEST_RECORDS", 0),
        );
        let slot_count = requested.max(1);
        let shard_count = env_usize_or("URING_PLAY_ZCNBLK_FAN_DIRTY_DIRECT_SHARDS", default_shards)
            .max(1)
            .min(slot_count);
        let slots_per_shard = slot_count.div_ceil(shard_count);
        let shards = Arc::new(
            (0..shard_count)
                .map(|_| {
                    Mutex::new(
                        std::iter::repeat_with(|| None)
                            .take(slots_per_shard)
                            .collect::<Vec<_>>(),
                    )
                })
                .collect(),
        );
        eprintln!(
            "zcnblk-fan-wal-dirty-direct: records={} shards={} slots_per_shard={} mode=lookaside source_of_truth=dirty-cache",
            slot_count, shard_count, slots_per_shard
        );
        Self { shards, slot_count }
    }

    fn enabled_from_env() -> bool {
        env_usize_or(
            "URING_PLAY_ZCNBLK_FAN_DIRTY_DIRECT_RECORDS",
            env_usize_or("URING_PLAY_ZCNBLK_FAN_DIRTY_LATEST_RECORDS", 0),
        ) != 0
    }

    fn slot_index(&self, record: u64) -> (usize, usize) {
        let table_idx = record as usize % self.slot_count;
        let shard_idx = table_idx % self.shards.len();
        let local_idx = table_idx / self.shards.len();
        (shard_idx, local_idx)
    }

    fn admit(&self, record: u64, entry: ZcnblkFanWalDirtyCacheEntry) -> io::Result<()> {
        let (shard_idx, local_idx) = self.slot_index(record);
        let mut shard = self.shards[shard_idx]
            .lock()
            .map_err(|_| io::Error::other("fan WAL dirty direct cache lock poisoned"))?;
        let Some(slot) = shard.get_mut(local_idx) else {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL dirty direct cache slot out of range",
            ));
        };
        let replace = slot.as_ref().is_none_or(|existing| {
            existing.record != record || existing.entry.sequence <= entry.sequence
        });
        if replace {
            *slot = Some(ZcnblkFanWalDirtyDirectSlot { record, entry });
        }
        Ok(())
    }

    fn read_part(&self, record: u64) -> io::Result<Option<ZcnblkFanWalReadPart>> {
        let (shard_idx, local_idx) = self.slot_index(record);
        let shard = self.shards[shard_idx]
            .lock()
            .map_err(|_| io::Error::other("fan WAL dirty direct cache lock poisoned"))?;
        let Some(Some(slot)) = shard.get(local_idx) else {
            return Ok(None);
        };
        if slot.record != record {
            return Ok(None);
        }
        slot.entry
            .payload
            .read_part(0, ZC_WAL_RECORD_SIZE)
            .map(Some)
    }

    fn clear_if_current(&self, record: u64, sequence: u64) -> io::Result<()> {
        let (shard_idx, local_idx) = self.slot_index(record);
        let mut shard = self.shards[shard_idx]
            .lock()
            .map_err(|_| io::Error::other("fan WAL dirty direct cache lock poisoned"))?;
        let Some(slot) = shard.get_mut(local_idx) else {
            return Ok(());
        };
        if slot
            .as_ref()
            .is_some_and(|current| current.record == record && current.entry.sequence == sequence)
        {
            *slot = None;
        }
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ZcnblkFanWalReadHole {
    logical_offset: u64,
    payload_offset: usize,
    len: usize,
}

impl ZcnblkFanWalDirtyCache {
    fn new() -> Self {
        let shard_count = env_usize_or(
            "URING_PLAY_ZCNBLK_FAN_DIRTY_CACHE_SHARDS",
            online_cpu_count().saturating_mul(4),
        )
        .max(1);
        let extent_shard_count =
            env_usize_or("URING_PLAY_ZCNBLK_FAN_DIRTY_EXTENT_SHARDS", shard_count).max(1);
        let extent_shard_records = env_usize_or(
            "URING_PLAY_ZCNBLK_FAN_DIRTY_EXTENT_SHARD_RECORDS",
            16 * 1024,
        )
        .max(1) as u64;
        let direct_table = ZcnblkFanWalDirtyDirectTable::enabled_from_env()
            .then(|| ZcnblkFanWalDirtyDirectTable::from_env(shard_count));
        Self {
            shards: Arc::new(
                (0..shard_count)
                    .map(|_| Mutex::new(ZcnblkFanWalDirtyCacheShard::default()))
                    .collect(),
            ),
            extent_shards: Arc::new(
                (0..extent_shard_count)
                    .map(|_| Mutex::new(BTreeMap::new()))
                    .collect(),
            ),
            direct_table,
            extent_shard_records,
            record_entries: Arc::new(AtomicUsize::new(0)),
            extent_entries: Arc::new(AtomicUsize::new(0)),
            retain_committed: env_enabled_or("URING_PLAY_ZCNBLK_FAN_RETAIN_COMMITTED_CACHE", false)
                || env_enabled_or("URING_PLAY_ZCNBLK_FAN_KEEP_COMMITTED_CACHE", false),
        }
    }

    fn has_cached_payloads(&self) -> bool {
        self.record_entries.load(Ordering::Relaxed) != 0
            || self.extent_entries.load(Ordering::Relaxed) != 0
    }

    fn shard_index(&self, record: u64) -> usize {
        record as usize % self.shards.len()
    }

    fn extent_shard_index(&self, record: u64) -> usize {
        ((record / self.extent_shard_records) as usize) % self.extent_shards.len()
    }

    fn extent_shard_end(&self, record: u64) -> io::Result<u64> {
        let shard_base = record / self.extent_shard_records;
        shard_base
            .checked_add(1)
            .and_then(|next| next.checked_mul(self.extent_shard_records))
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "dirty extent shard boundary overflow",
                )
            })
    }

    fn validate_range(offset: u64, len: usize, label: &str) -> io::Result<()> {
        if len == 0 || len % ZC_WAL_RECORD_SIZE != 0 || offset % ZC_WAL_RECORD_SIZE as u64 != 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "fan WAL dirty cache {label} requires 4K-aligned non-empty ranges, got offset={offset} len={len}"
                ),
            ));
        }
        Ok(())
    }

    fn record_index(offset: u64) -> u64 {
        offset / ZC_WAL_RECORD_SIZE as u64
    }

    fn admit_record_payload(
        &self,
        record: u64,
        entry: ZcnblkFanWalDirtyCacheEntry,
    ) -> io::Result<()> {
        let shard = &self.shards[self.shard_index(record)];
        let mut shard = shard
            .lock()
            .map_err(|_| io::Error::other("fan WAL dirty cache lock poisoned"))?;
        let replace = shard
            .records
            .get(&record)
            .is_none_or(|existing| existing.sequence <= entry.sequence);
        if replace {
            let inserted_new = !shard.records.contains_key(&record);
            shard.records.insert(record, entry.clone());
            if inserted_new {
                self.record_entries.fetch_add(1, Ordering::Relaxed);
            }
            if let Some(direct) = &self.direct_table
                && self.direct_entry_visible_after_extent(record, entry.sequence)?
            {
                direct.admit(record, entry)?;
            }
        }
        Ok(())
    }

    fn admit_write(&self, offset: u64, payload: &[u8], sequence: u64) -> io::Result<()> {
        Self::validate_range(offset, payload.len(), "admit")?;
        for (idx, chunk) in payload.chunks_exact(ZC_WAL_RECORD_SIZE).enumerate() {
            let record = Self::record_index(offset)
                .checked_add(idx as u64)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
                })?;
            self.admit_record_payload(
                record,
                ZcnblkFanWalDirtyCacheEntry {
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Copy(Arc::<[u8]>::from(chunk)),
                },
            )?;
        }
        Ok(())
    }

    fn admit_write_lease(
        &self,
        offset: u64,
        source: Arc<Vec<u8>>,
        source_start: usize,
        len: usize,
        sequence: u64,
    ) -> io::Result<()> {
        Self::validate_range(offset, len, "admit lease")?;
        let source_end = source_start.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "dirty lease source range overflow",
            )
        })?;
        if source_end > source.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "dirty lease source range is outside upstream payload",
            ));
        }
        if len == ZC_WAL_RECORD_SIZE {
            return self.admit_record_payload(
                Self::record_index(offset),
                ZcnblkFanWalDirtyCacheEntry {
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Lease {
                        source,
                        start: source_start,
                    },
                },
            );
        }
        let mut first_record = Self::record_index(offset);
        let mut source_cursor = source_start;
        let mut remaining_records = len / ZC_WAL_RECORD_SIZE;
        while remaining_records != 0 {
            let shard_end = self.extent_shard_end(first_record)?;
            let shard_records = usize::try_from(shard_end.saturating_sub(first_record))
                .unwrap_or(usize::MAX)
                .min(remaining_records);
            let shard_idx = self.extent_shard_index(first_record);
            let mut extents = self.extent_shards[shard_idx]
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
            Self::admit_dirty_extent(
                &mut extents,
                ZcnblkFanWalDirtyExtent {
                    first_record,
                    record_count: shard_records,
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Lease {
                        source: Arc::clone(&source),
                        start: source_cursor,
                    },
                },
            )?;
            self.extent_entries.fetch_add(1, Ordering::Relaxed);
            if let Some(direct) = &self.direct_table {
                for record_offset in 0..shard_records {
                    let record =
                        first_record
                            .checked_add(record_offset as u64)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "dirty cache record overflow",
                                )
                            })?;
                    let start = source_cursor
                        .checked_add(record_offset.saturating_mul(ZC_WAL_RECORD_SIZE))
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty cache source overflow",
                            )
                        })?;
                    let Some(best) = Self::best_extent_for_record(&extents, record)? else {
                        continue;
                    };
                    if best.sequence != sequence {
                        continue;
                    }
                    direct.admit(
                        record,
                        ZcnblkFanWalDirtyCacheEntry {
                            sequence,
                            payload: ZcnblkFanWalDirtyPayload::Lease {
                                source: Arc::clone(&source),
                                start,
                            },
                        },
                    )?;
                }
            }
            remaining_records -= shard_records;
            first_record = first_record
                .checked_add(shard_records as u64)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
                })?;
            source_cursor = source_cursor
                .checked_add(shard_records * ZC_WAL_RECORD_SIZE)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty cache source overflow")
                })?;
        }
        Ok(())
    }

    fn admit_write_memfd_lease(
        &self,
        offset: u64,
        log: Arc<ZcnblkFanWalMemfdLog>,
        log_start: u64,
        len: usize,
        sequence: u64,
    ) -> io::Result<()> {
        Self::validate_range(offset, len, "admit memfd lease")?;
        let len_u64 = u64::try_from(len).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "dirty memfd lease length exceeds u64",
            )
        })?;
        let _log_end = log_start.checked_add(len_u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "dirty memfd lease range overflow",
            )
        })?;
        if len == ZC_WAL_RECORD_SIZE {
            return self.admit_record_payload(
                Self::record_index(offset),
                ZcnblkFanWalDirtyCacheEntry {
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Memfd {
                        log,
                        start: log_start,
                    },
                },
            );
        }
        let mut first_record = Self::record_index(offset);
        let mut log_cursor = log_start;
        let mut remaining_records = len / ZC_WAL_RECORD_SIZE;
        while remaining_records != 0 {
            let shard_end = self.extent_shard_end(first_record)?;
            let shard_records = usize::try_from(shard_end.saturating_sub(first_record))
                .unwrap_or(usize::MAX)
                .min(remaining_records);
            let shard_idx = self.extent_shard_index(first_record);
            let mut extents = self.extent_shards[shard_idx]
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
            Self::admit_dirty_extent(
                &mut extents,
                ZcnblkFanWalDirtyExtent {
                    first_record,
                    record_count: shard_records,
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Memfd {
                        log: Arc::clone(&log),
                        start: log_cursor,
                    },
                },
            )?;
            self.extent_entries.fetch_add(1, Ordering::Relaxed);
            if let Some(direct) = &self.direct_table {
                for record_offset in 0..shard_records {
                    let record =
                        first_record
                            .checked_add(record_offset as u64)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "dirty cache record overflow",
                                )
                            })?;
                    let byte_offset =
                        u64::try_from(record_offset.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(
                            || {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "dirty memfd direct byte offset overflow",
                                )
                            },
                        )?)
                        .map_err(|_| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty memfd direct byte offset exceeds u64",
                            )
                        })?;
                    let start = log_cursor.checked_add(byte_offset).ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "dirty memfd direct offset overflow",
                        )
                    })?;
                    let Some(best) = Self::best_extent_for_record(&extents, record)? else {
                        continue;
                    };
                    if best.sequence != sequence {
                        continue;
                    }
                    direct.admit(
                        record,
                        ZcnblkFanWalDirtyCacheEntry {
                            sequence,
                            payload: ZcnblkFanWalDirtyPayload::Memfd {
                                log: Arc::clone(&log),
                                start,
                            },
                        },
                    )?;
                }
            }
            remaining_records -= shard_records;
            first_record = first_record
                .checked_add(shard_records as u64)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
                })?;
            let shard_bytes = u64::try_from(
                shard_records
                    .checked_mul(ZC_WAL_RECORD_SIZE)
                    .ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "dirty memfd shard byte overflow",
                        )
                    })?,
            )
            .map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "dirty memfd shard byte count exceeds u64",
                )
            })?;
            log_cursor = log_cursor.checked_add(shard_bytes).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "dirty memfd cursor overflow")
            })?;
        }
        Ok(())
    }

    fn admit_write_arena_lease(
        &self,
        offset: u64,
        arena: Arc<ZcLogLeaseArenaMap>,
        arena_start: usize,
        len: usize,
        sequence: u64,
    ) -> io::Result<()> {
        Self::validate_range(offset, len, "admit shared-arena lease")?;
        let _ = zc_loglease_arena_payload_slice(arena.as_ref(), arena_start, len)?;
        if len == ZC_WAL_RECORD_SIZE {
            return self.admit_record_payload(
                Self::record_index(offset),
                ZcnblkFanWalDirtyCacheEntry {
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Arena {
                        arena,
                        start: arena_start,
                    },
                },
            );
        }
        let mut first_record = Self::record_index(offset);
        let mut arena_cursor = arena_start;
        let mut remaining_records = len / ZC_WAL_RECORD_SIZE;
        while remaining_records != 0 {
            let shard_end = self.extent_shard_end(first_record)?;
            let shard_records = usize::try_from(shard_end.saturating_sub(first_record))
                .unwrap_or(usize::MAX)
                .min(remaining_records);
            let shard_idx = self.extent_shard_index(first_record);
            let mut extents = self.extent_shards[shard_idx]
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
            Self::admit_dirty_extent(
                &mut extents,
                ZcnblkFanWalDirtyExtent {
                    first_record,
                    record_count: shard_records,
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Arena {
                        arena: Arc::clone(&arena),
                        start: arena_cursor,
                    },
                },
            )?;
            self.extent_entries.fetch_add(1, Ordering::Relaxed);
            if let Some(direct) = &self.direct_table {
                for record_offset in 0..shard_records {
                    let record =
                        first_record
                            .checked_add(record_offset as u64)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "dirty cache record overflow",
                                )
                            })?;
                    let start = arena_cursor
                        .checked_add(record_offset.saturating_mul(ZC_WAL_RECORD_SIZE))
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty cache arena source overflow",
                            )
                        })?;
                    let Some(best) = Self::best_extent_for_record(&extents, record)? else {
                        continue;
                    };
                    if best.sequence != sequence {
                        continue;
                    }
                    direct.admit(
                        record,
                        ZcnblkFanWalDirtyCacheEntry {
                            sequence,
                            payload: ZcnblkFanWalDirtyPayload::Arena {
                                arena: Arc::clone(&arena),
                                start,
                            },
                        },
                    )?;
                }
            }
            remaining_records -= shard_records;
            first_record = first_record
                .checked_add(shard_records as u64)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
                })?;
            arena_cursor = arena_cursor
                .checked_add(shard_records * ZC_WAL_RECORD_SIZE)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty cache arena overflow")
                })?;
        }
        Ok(())
    }

    pub(crate) fn admit_write_shared_lease(
        &self,
        offset: u64,
        source: Arc<dyn ZcnblkFanWalSharedLeaseSource>,
        source_start: usize,
        len: usize,
        sequence: u64,
    ) -> io::Result<()> {
        Self::validate_range(offset, len, "admit shared lease")?;
        let _ = source.payload_slice(source_start, len)?;
        if len == ZC_WAL_RECORD_SIZE {
            return self.admit_record_payload(
                Self::record_index(offset),
                ZcnblkFanWalDirtyCacheEntry {
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Shared {
                        source,
                        start: source_start,
                    },
                },
            );
        }
        let mut first_record = Self::record_index(offset);
        let mut source_cursor = source_start;
        let mut remaining_records = len / ZC_WAL_RECORD_SIZE;
        while remaining_records != 0 {
            let shard_end = self.extent_shard_end(first_record)?;
            let shard_records = usize::try_from(shard_end.saturating_sub(first_record))
                .unwrap_or(usize::MAX)
                .min(remaining_records);
            let shard_idx = self.extent_shard_index(first_record);
            let mut extents = self.extent_shards[shard_idx]
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
            Self::admit_dirty_extent(
                &mut extents,
                ZcnblkFanWalDirtyExtent {
                    first_record,
                    record_count: shard_records,
                    sequence,
                    payload: ZcnblkFanWalDirtyPayload::Shared {
                        source: Arc::clone(&source),
                        start: source_cursor,
                    },
                },
            )?;
            self.extent_entries.fetch_add(1, Ordering::Relaxed);
            if let Some(direct) = &self.direct_table {
                for record_offset in 0..shard_records {
                    let record =
                        first_record
                            .checked_add(record_offset as u64)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "dirty cache record overflow",
                                )
                            })?;
                    let start = source_cursor
                        .checked_add(record_offset.saturating_mul(ZC_WAL_RECORD_SIZE))
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty cache shared source overflow",
                            )
                        })?;
                    let Some(best) = Self::best_extent_for_record(&extents, record)? else {
                        continue;
                    };
                    if best.sequence != sequence {
                        continue;
                    }
                    direct.admit(
                        record,
                        ZcnblkFanWalDirtyCacheEntry {
                            sequence,
                            payload: ZcnblkFanWalDirtyPayload::Shared {
                                source: Arc::clone(&source),
                                start,
                            },
                        },
                    )?;
                }
            }
            remaining_records -= shard_records;
            first_record = first_record
                .checked_add(shard_records as u64)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
                })?;
            source_cursor = source_cursor
                .checked_add(shard_records * ZC_WAL_RECORD_SIZE)
                .ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "dirty cache shared source overflow",
                    )
                })?;
        }
        Ok(())
    }

    fn push_dirty_extent(
        extents: &mut BTreeMap<u64, Vec<ZcnblkFanWalDirtyExtent>>,
        extent: ZcnblkFanWalDirtyExtent,
    ) {
        extents.entry(extent.first_record).or_default().push(extent);
    }

    fn dirty_extent_vec_overlaps(
        candidates: &[ZcnblkFanWalDirtyExtent],
        first: u64,
        end: u64,
    ) -> io::Result<bool> {
        for extent in candidates {
            let extent_first = extent.first_record;
            let extent_end = extent.end_record()?;
            if extent_end > first && extent_first < end {
                return Ok(true);
            }
        }
        Ok(false)
    }

    fn dirty_extent_map_overlaps(
        extents: &BTreeMap<u64, Vec<ZcnblkFanWalDirtyExtent>>,
        first: u64,
        end: u64,
    ) -> io::Result<bool> {
        if let Some((_key, candidates)) = extents.range(..=first).next_back() {
            if Self::dirty_extent_vec_overlaps(candidates, first, end)? {
                return Ok(true);
            }
        }
        for (_key, candidates) in extents.range(first..end) {
            if Self::dirty_extent_vec_overlaps(candidates, first, end)? {
                return Ok(true);
            }
        }
        Ok(false)
    }

    fn push_dirty_extent_pieces_outside(
        out: &mut BTreeMap<u64, Vec<ZcnblkFanWalDirtyExtent>>,
        extent: ZcnblkFanWalDirtyExtent,
        cut_first: u64,
        cut_end: u64,
    ) -> io::Result<()> {
        let extent_first = extent.first_record;
        let extent_end = extent.end_record()?;
        let overlap_first = extent_first.max(cut_first);
        let overlap_end = extent_end.min(cut_end);
        if overlap_first >= overlap_end {
            Self::push_dirty_extent(out, extent);
            return Ok(());
        }
        if extent_first < overlap_first {
            let left_count = usize::try_from(overlap_first - extent_first).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "dirty extent left split overflow",
                )
            })?;
            Self::push_dirty_extent(out, extent.slice(0, left_count)?);
        }
        if overlap_end < extent_end {
            let right_offset = usize::try_from(overlap_end - extent_first).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "dirty extent right split overflow",
                )
            })?;
            let right_count = usize::try_from(extent_end - overlap_end).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "dirty extent right count overflow",
                )
            })?;
            Self::push_dirty_extent(out, extent.slice(right_offset, right_count)?);
        }
        Ok(())
    }

    fn split_dirty_extent_vec_outside(
        extents: Vec<ZcnblkFanWalDirtyExtent>,
        cut_first: u64,
        cut_end: u64,
    ) -> io::Result<Vec<ZcnblkFanWalDirtyExtent>> {
        let mut rebuilt = BTreeMap::new();
        for extent in extents {
            Self::push_dirty_extent_pieces_outside(&mut rebuilt, extent, cut_first, cut_end)?;
        }
        Ok(rebuilt.into_values().flatten().collect())
    }

    fn admit_dirty_extent(
        extents: &mut BTreeMap<u64, Vec<ZcnblkFanWalDirtyExtent>>,
        extent: ZcnblkFanWalDirtyExtent,
    ) -> io::Result<()> {
        let new_first = extent.first_record;
        let new_end = extent.end_record()?;
        if !Self::dirty_extent_map_overlaps(extents, new_first, new_end)? {
            Self::push_dirty_extent(extents, extent);
            return Ok(());
        }
        let new_sequence = extent.sequence;
        let mut pending_new = vec![extent];
        let mut rebuilt = BTreeMap::new();
        for (_key, candidates) in std::mem::take(extents) {
            for existing in candidates {
                let existing_first = existing.first_record;
                let existing_end = existing.end_record()?;
                if existing_end <= new_first || existing_first >= new_end {
                    Self::push_dirty_extent(&mut rebuilt, existing);
                    continue;
                }
                if existing.sequence <= new_sequence {
                    Self::push_dirty_extent_pieces_outside(
                        &mut rebuilt,
                        existing,
                        new_first,
                        new_end,
                    )?;
                } else {
                    pending_new = Self::split_dirty_extent_vec_outside(
                        pending_new,
                        existing_first,
                        existing_end,
                    )?;
                    Self::push_dirty_extent(&mut rebuilt, existing);
                }
            }
        }
        for new_extent in pending_new {
            Self::push_dirty_extent(&mut rebuilt, new_extent);
        }
        *extents = rebuilt;
        Ok(())
    }

    fn mark_committed_in_extent_map(
        extents: &mut BTreeMap<u64, Vec<ZcnblkFanWalDirtyExtent>>,
        first: u64,
        commit_end: u64,
        sequence: u64,
    ) -> io::Result<bool> {
        let mut changed = false;
        let mut rebuilt = BTreeMap::new();
        for (_key, candidates) in std::mem::take(extents) {
            for extent in candidates {
                if extent.sequence != sequence {
                    Self::push_dirty_extent(&mut rebuilt, extent);
                    continue;
                }
                let extent_first = extent.first_record;
                let extent_end = extent.end_record()?;
                let overlap_first = extent_first.max(first);
                let overlap_end = extent_end.min(commit_end);
                if overlap_first >= overlap_end {
                    Self::push_dirty_extent(&mut rebuilt, extent);
                    continue;
                }
                if extent_first < overlap_first {
                    let left_count =
                        usize::try_from(overlap_first - extent_first).map_err(|_| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty extent left split overflow",
                            )
                        })?;
                    Self::push_dirty_extent(&mut rebuilt, extent.slice(0, left_count)?);
                }
                if overlap_end < extent_end {
                    let right_offset =
                        usize::try_from(overlap_end - extent_first).map_err(|_| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty extent right split overflow",
                            )
                        })?;
                    let right_count = usize::try_from(extent_end - overlap_end).map_err(|_| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "dirty extent right count overflow",
                        )
                    })?;
                    Self::push_dirty_extent(&mut rebuilt, extent.slice(right_offset, right_count)?);
                }
                changed = true;
            }
        }
        *extents = rebuilt;
        Ok(changed)
    }

    fn mark_committed(&self, offset: u64, len: usize, sequence: u64) -> io::Result<()> {
        Self::validate_range(offset, len, "commit")?;
        if self.retain_committed {
            return Ok(());
        }
        let first = Self::record_index(offset);
        let count = len / ZC_WAL_RECORD_SIZE;
        let commit_end = first
            .checked_add(count as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "commit end overflow"))?;
        if self.extent_entries.load(Ordering::Relaxed) != 0 {
            let mut shard_first = first;
            while shard_first < commit_end {
                let shard_end = self.extent_shard_end(shard_first)?.min(commit_end);
                let shard_idx = self.extent_shard_index(shard_first);
                let mut extents = self.extent_shards[shard_idx]
                    .lock()
                    .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
                let _ = Self::mark_committed_in_extent_map(
                    &mut extents,
                    shard_first,
                    shard_end,
                    sequence,
                )?;
                shard_first = shard_end;
            }
        }
        if let Some(direct) = &self.direct_table {
            for idx in 0..count {
                let record = first.checked_add(idx as u64).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
                })?;
                direct.clear_if_current(record, sequence)?;
            }
        }
        if self.record_entries.load(Ordering::Relaxed) == 0 {
            return Ok(());
        }
        for idx in 0..count {
            let record = first.checked_add(idx as u64).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
            })?;
            let shard = &self.shards[self.shard_index(record)];
            let mut shard = shard
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache lock poisoned"))?;
            if shard
                .records
                .get(&record)
                .is_some_and(|entry| entry.sequence == sequence)
                && shard.records.remove(&record).is_some()
            {
                self.record_entries.fetch_sub(1, Ordering::Relaxed);
            }
        }
        Ok(())
    }

    fn best_extent_for_record(
        extents: &BTreeMap<u64, Vec<ZcnblkFanWalDirtyExtent>>,
        record: u64,
    ) -> io::Result<Option<ZcnblkFanWalDirtyExtent>> {
        let Some((_first, candidates)) = extents.range(..=record).next_back() else {
            return Ok(None);
        };
        let mut best = None::<ZcnblkFanWalDirtyExtent>;
        for extent in candidates.iter().rev() {
            if !extent.contains(record)? {
                continue;
            }
            if best
                .as_ref()
                .is_none_or(|existing| extent.sequence >= existing.sequence)
            {
                best = Some(extent.clone());
            }
        }
        Ok(best)
    }

    fn direct_entry_visible_after_extent(&self, record: u64, sequence: u64) -> io::Result<bool> {
        if self.extent_entries.load(Ordering::Relaxed) == 0 {
            return Ok(true);
        }
        let shard_idx = self.extent_shard_index(record);
        let extents = self.extent_shards[shard_idx]
            .lock()
            .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
        Ok(Self::best_extent_for_record(&extents, record)?
            .is_none_or(|extent| extent.sequence <= sequence))
    }

    fn read_direct_part(&self, record: u64) -> io::Result<Option<ZcnblkFanWalReadPart>> {
        if let Some(direct) = &self.direct_table {
            direct.read_part(record)
        } else {
            Ok(None)
        }
    }

    fn read_record_entry_part(
        &self,
        record: u64,
    ) -> io::Result<Option<(u64, ZcnblkFanWalReadPart)>> {
        if self.record_entries.load(Ordering::Relaxed) == 0 {
            return Ok(None);
        }
        let shard = &self.shards[self.shard_index(record)];
        let shard = shard
            .lock()
            .map_err(|_| io::Error::other("fan WAL dirty cache lock poisoned"))?;
        shard
            .records
            .get(&record)
            .map(|entry| {
                entry
                    .payload
                    .read_part(0, ZC_WAL_RECORD_SIZE)
                    .map(|part| (entry.sequence, part))
            })
            .transpose()
    }

    fn read_best_record_part(&self, record: u64) -> io::Result<Option<ZcnblkFanWalReadPart>> {
        let record_part = self.read_record_entry_part(record)?;
        let extent = if self.extent_entries.load(Ordering::Relaxed) != 0 {
            let shard_idx = self.extent_shard_index(record);
            let extents = self.extent_shards[shard_idx]
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
            Self::best_extent_for_record(&extents, record)?
        } else {
            None
        };
        match (record_part, extent) {
            (None, None) => Ok(None),
            (Some((_sequence, part)), None) => Ok(Some(part)),
            (None, Some(extent)) => {
                let record_offset =
                    usize::try_from(record - extent.first_record).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidData, "dirty extent offset overflow")
                    })?;
                extent
                    .payload
                    .read_part(record_offset, ZC_WAL_RECORD_SIZE)
                    .map(Some)
            }
            (Some((record_sequence, part)), Some(extent)) if record_sequence >= extent.sequence => {
                Ok(Some(part))
            }
            (Some((_record_sequence, _part)), Some(extent)) => {
                let record_offset =
                    usize::try_from(record - extent.first_record).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidData, "dirty extent offset overflow")
                    })?;
                extent
                    .payload
                    .read_part(record_offset, ZC_WAL_RECORD_SIZE)
                    .map(Some)
            }
        }
    }

    fn push_read_hole(
        holes: &mut Vec<ZcnblkFanWalReadHole>,
        logical_offset: u64,
        payload_offset: usize,
        len: usize,
    ) -> io::Result<()> {
        if let Some(last) = holes.last_mut() {
            let last_end = last
                .logical_offset
                .checked_add(last.len as u64)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "read hole end overflow")
                })?;
            if last_end == logical_offset
                && last.payload_offset.checked_add(last.len) == Some(payload_offset)
            {
                last.len = last.len.checked_add(len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "read hole len overflow")
                })?;
                return Ok(());
            }
        }
        holes.push(ZcnblkFanWalReadHole {
            logical_offset,
            payload_offset,
            len,
        });
        Ok(())
    }

    fn read_cached_refs_or_holes(
        &self,
        offset: u64,
        len: usize,
    ) -> io::Result<(Option<ZcnblkFanWalLocalRead>, Vec<ZcnblkFanWalReadHole>)> {
        Self::validate_range(offset, len, "cached-ref-or-holes read")?;
        if !self.has_cached_payloads() {
            return Ok((
                None,
                vec![ZcnblkFanWalReadHole {
                    logical_offset: offset,
                    payload_offset: 0,
                    len,
                }],
            ));
        }
        let first = Self::record_index(offset);
        let count = len / ZC_WAL_RECORD_SIZE;
        let end = first.checked_add(count as u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "cached read end overflow")
        })?;
        let mut record = first;
        let mut payload_offset = 0usize;
        let mut parts = Vec::new();
        let mut holes = Vec::new();
        while record < end {
            if let Some(part) = self.read_direct_part(record)? {
                parts.push(part);
                payload_offset =
                    payload_offset
                        .checked_add(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidInput,
                                "cached read payload overflow",
                            )
                        })?;
                record = record.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
                })?;
                continue;
            }
            if self.record_entries.load(Ordering::Relaxed) != 0 {
                if let Some(part) = self.read_best_record_part(record)? {
                    parts.push(part);
                } else {
                    let logical_offset =
                        offset.checked_add(payload_offset as u64).ok_or_else(|| {
                            io::Error::new(io::ErrorKind::InvalidInput, "read hole overflow")
                        })?;
                    Self::push_read_hole(
                        &mut holes,
                        logical_offset,
                        payload_offset,
                        ZC_WAL_RECORD_SIZE,
                    )?;
                }
                payload_offset =
                    payload_offset
                        .checked_add(ZC_WAL_RECORD_SIZE)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidInput,
                                "cached read payload overflow",
                            )
                        })?;
                record = record.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
                })?;
                continue;
            }
            let shard_end = self.extent_shard_end(record)?.min(end);
            let extent = if self.extent_entries.load(Ordering::Relaxed) != 0 {
                let shard_idx = self.extent_shard_index(record);
                let extents = self.extent_shards[shard_idx]
                    .lock()
                    .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
                Self::best_extent_for_record(&extents, record)?
            } else {
                None
            };
            if let Some(extent) = extent {
                let extent_end = extent.end_record()?;
                let run_end = extent_end.min(shard_end);
                let record_offset =
                    usize::try_from(record - extent.first_record).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidData, "dirty extent offset overflow")
                    })?;
                let run_records = usize::try_from(run_end - record).map_err(|_| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty extent run overflow")
                })?;
                let run_bytes = run_records.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty extent run byte overflow")
                })?;
                parts.push(extent.payload.read_part(record_offset, run_bytes)?);
                payload_offset = payload_offset.checked_add(run_bytes).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read payload overflow")
                })?;
                record = run_end;
                continue;
            }
            let copied = {
                let shard = &self.shards[self.shard_index(record)];
                let shard = shard
                    .lock()
                    .map_err(|_| io::Error::other("fan WAL dirty cache lock poisoned"))?;
                shard
                    .records
                    .get(&record)
                    .map(|entry| entry.payload.read_part(0, ZC_WAL_RECORD_SIZE))
                    .transpose()?
            };
            if let Some(copied) = copied {
                parts.push(copied);
            } else {
                let logical_offset =
                    offset.checked_add(payload_offset as u64).ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidInput, "read hole overflow")
                    })?;
                Self::push_read_hole(
                    &mut holes,
                    logical_offset,
                    payload_offset,
                    ZC_WAL_RECORD_SIZE,
                )?;
            }
            payload_offset = payload_offset
                .checked_add(ZC_WAL_RECORD_SIZE)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read payload overflow")
                })?;
            record = record.checked_add(1).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
            })?;
        }
        if holes.is_empty() {
            Ok((Some(ZcnblkFanWalLocalRead::leased(len, parts)), holes))
        } else {
            Ok((None, holes))
        }
    }

    fn read_cached_refs(
        &self,
        offset: u64,
        len: usize,
    ) -> io::Result<Option<ZcnblkFanWalLocalRead>> {
        Self::validate_range(offset, len, "cached-ref read")?;
        if !self.has_cached_payloads() {
            return Ok(None);
        }
        let first = Self::record_index(offset);
        let count = len / ZC_WAL_RECORD_SIZE;
        let end = first.checked_add(count as u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "cached read end overflow")
        })?;
        let mut record = first;
        let mut parts = Vec::new();
        while record < end {
            if let Some(part) = self.read_direct_part(record)? {
                parts.push(part);
                record = record.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
                })?;
                continue;
            }
            if self.record_entries.load(Ordering::Relaxed) != 0 {
                let Some(part) = self.read_best_record_part(record)? else {
                    return Ok(None);
                };
                parts.push(part);
                record = record.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
                })?;
                continue;
            }
            let shard_end = self.extent_shard_end(record)?.min(end);
            let extent = if self.extent_entries.load(Ordering::Relaxed) != 0 {
                let shard_idx = self.extent_shard_index(record);
                let extents = self.extent_shards[shard_idx]
                    .lock()
                    .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
                Self::best_extent_for_record(&extents, record)?
            } else {
                None
            };
            if let Some(extent) = extent {
                let extent_end = extent.end_record()?;
                let run_end = extent_end.min(shard_end);
                let record_offset =
                    usize::try_from(record - extent.first_record).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidData, "dirty extent offset overflow")
                    })?;
                let run_records = usize::try_from(run_end - record).map_err(|_| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty extent run overflow")
                })?;
                let run_bytes = run_records.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty extent run byte overflow")
                })?;
                parts.push(extent.payload.read_part(record_offset, run_bytes)?);
                record = run_end;
                continue;
            }
            let copied = {
                let shard = &self.shards[self.shard_index(record)];
                let shard = shard
                    .lock()
                    .map_err(|_| io::Error::other("fan WAL dirty cache lock poisoned"))?;
                shard
                    .records
                    .get(&record)
                    .map(|entry| entry.payload.read_part(0, ZC_WAL_RECORD_SIZE))
                    .transpose()?
            };
            let Some(copied) = copied else {
                return Ok(None);
            };
            parts.push(copied);
            record = record.checked_add(1).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
            })?;
        }
        Ok(Some(ZcnblkFanWalLocalRead::leased(len, parts)))
    }

    fn read_refs_or_zero(&self, offset: u64, len: usize) -> io::Result<ZcnblkFanWalLocalRead> {
        Self::validate_range(offset, len, "cached-ref-or-zero read")?;
        if !self.has_cached_payloads() {
            return zcnblk_fan_wal_zero_local_read(len);
        }
        let first = Self::record_index(offset);
        let count = len / ZC_WAL_RECORD_SIZE;
        let end = first.checked_add(count as u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "cached read end overflow")
        })?;
        let mut record = first;
        let mut parts = Vec::new();
        let mut zero_run_records = 0usize;
        while record < end {
            if let Some(part) = self.read_direct_part(record)? {
                if zero_run_records != 0 {
                    zcnblk_fan_wal_push_zero_read_parts(
                        &mut parts,
                        zero_run_records
                            .checked_mul(ZC_WAL_RECORD_SIZE)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zero read run byte overflow",
                                )
                            })?,
                    )?;
                    zero_run_records = 0;
                }
                parts.push(part);
                record = record.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
                })?;
                continue;
            }
            if self.record_entries.load(Ordering::Relaxed) != 0 {
                if let Some(part) = self.read_best_record_part(record)? {
                    if zero_run_records != 0 {
                        zcnblk_fan_wal_push_zero_read_parts(
                            &mut parts,
                            zero_run_records
                                .checked_mul(ZC_WAL_RECORD_SIZE)
                                .ok_or_else(|| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "zero read run byte overflow",
                                    )
                                })?,
                        )?;
                        zero_run_records = 0;
                    }
                    parts.push(part);
                } else {
                    zero_run_records = zero_run_records.checked_add(1).ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zero read run record overflow")
                    })?;
                }
                record = record.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
                })?;
                continue;
            }
            let shard_end = self.extent_shard_end(record)?.min(end);
            let extent = if self.extent_entries.load(Ordering::Relaxed) != 0 {
                let shard_idx = self.extent_shard_index(record);
                let extents = self.extent_shards[shard_idx]
                    .lock()
                    .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
                Self::best_extent_for_record(&extents, record)?
            } else {
                None
            };
            if let Some(extent) = extent {
                if zero_run_records != 0 {
                    zcnblk_fan_wal_push_zero_read_parts(
                        &mut parts,
                        zero_run_records
                            .checked_mul(ZC_WAL_RECORD_SIZE)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zero read run byte overflow",
                                )
                            })?,
                    )?;
                    zero_run_records = 0;
                }
                let extent_end = extent.end_record()?;
                let run_end = extent_end.min(shard_end);
                let record_offset =
                    usize::try_from(record - extent.first_record).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidData, "dirty extent offset overflow")
                    })?;
                let run_records = usize::try_from(run_end - record).map_err(|_| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty extent run overflow")
                })?;
                let run_bytes = run_records.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "dirty extent run byte overflow")
                })?;
                parts.push(extent.payload.read_part(record_offset, run_bytes)?);
                record = run_end;
                continue;
            }
            let copied = {
                let shard = &self.shards[self.shard_index(record)];
                let shard = shard
                    .lock()
                    .map_err(|_| io::Error::other("fan WAL dirty cache lock poisoned"))?;
                shard
                    .records
                    .get(&record)
                    .map(|entry| entry.payload.read_part(0, ZC_WAL_RECORD_SIZE))
                    .transpose()?
            };
            if let Some(copied) = copied {
                if zero_run_records != 0 {
                    zcnblk_fan_wal_push_zero_read_parts(
                        &mut parts,
                        zero_run_records
                            .checked_mul(ZC_WAL_RECORD_SIZE)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zero read run byte overflow",
                                )
                            })?,
                    )?;
                    zero_run_records = 0;
                }
                parts.push(copied);
            } else {
                zero_run_records = zero_run_records.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zero read run record overflow")
                })?;
            }
            record = record.checked_add(1).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "cached read record overflow")
            })?;
        }
        if zero_run_records != 0 {
            zcnblk_fan_wal_push_zero_read_parts(
                &mut parts,
                zero_run_records
                    .checked_mul(ZC_WAL_RECORD_SIZE)
                    .ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zero read run byte overflow")
                    })?,
            )?;
        }
        Ok(ZcnblkFanWalLocalRead::leased(len, parts))
    }

    fn overlay_read(
        &self,
        offset: u64,
        len: usize,
        out: &mut [u8],
    ) -> io::Result<Vec<ZcnblkFanWalReadHole>> {
        Self::validate_range(offset, len, "read")?;
        if out.len() != len {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "fan WAL dirty cache read buffer length mismatch got={} expected={len}",
                    out.len()
                ),
            ));
        }
        if !self.has_cached_payloads() {
            return Ok(vec![ZcnblkFanWalReadHole {
                logical_offset: offset,
                payload_offset: 0,
                len,
            }]);
        }
        let first = Self::record_index(offset);
        let count = len / ZC_WAL_RECORD_SIZE;
        let mut holes: Vec<ZcnblkFanWalReadHole> = Vec::new();
        for idx in 0..count {
            let record = first.checked_add(idx as u64).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "dirty cache record overflow")
            })?;
            let payload_offset = idx.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "dirty cache payload overflow")
            })?;
            if let Some(part) = self.read_best_record_part(record)? {
                part.copy_into(&mut out[payload_offset..payload_offset + ZC_WAL_RECORD_SIZE])?;
                continue;
            }
            let logical_offset = offset
                .checked_add(payload_offset as u64)
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "read hole overflow"))?;
            Self::push_read_hole(
                &mut holes,
                logical_offset,
                payload_offset,
                ZC_WAL_RECORD_SIZE,
            )?;
        }
        Ok(holes)
    }

    fn covers_range(&self, offset: u64, len: usize) -> io::Result<bool> {
        Ok(self.read_cached_refs(offset, len)?.is_some())
    }

    fn snapshot_records(&self) -> io::Result<usize> {
        let mut extent_records = 0usize;
        for shard in self.extent_shards.iter() {
            let extents = shard
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache extent lock poisoned"))?;
            extent_records = extents
                .values()
                .try_fold(extent_records, |total, candidates| {
                    candidates.iter().try_fold(total, |total, extent| {
                        total.checked_add(extent.record_count).ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "dirty cache extent record count overflow",
                            )
                        })
                    })
                })?;
        }
        self.shards.iter().try_fold(extent_records, |total, shard| {
            let shard = shard
                .lock()
                .map_err(|_| io::Error::other("fan WAL dirty cache lock poisoned"))?;
            total.checked_add(shard.records.len()).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "dirty cache record count overflow",
                )
            })
        })
    }
}

struct ZcnblkFanWalPendingWrite {
    prepared: ZcnblkFanPreparedFrame,
    segments: Vec<ZcnblkFanSegment>,
    payload_start: usize,
    payload_len: usize,
}

struct ZcnblkFanWalSubmittedWrite {
    prepared: ZcnblkFanPreparedFrame,
    segments: Vec<ZcnblkFanSegment>,
}

struct ZcnblkFanWalSubmittedWriteBatch {
    writes: Vec<ZcnblkFanWalSubmittedWrite>,
    leaf_result_batches: Vec<ZcnblkFanWalLeafResultBatch>,
    records: Vec<u64>,
    dirty_lease: Option<ZcnblkFanWalDirtyLease>,
}

struct ZcnblkFanWalLeafResultBatch {
    leaf_idx: usize,
    items: Vec<ZcnblkFanWalLeafBatchItem>,
}

struct ZcnblkFanWalPendingRequest {
    prepared: ZcnblkFanPreparedFrame,
    segments: Vec<ZcnblkFanSegment>,
    payload_start: usize,
}

struct ZcnblkFanWalSubmittedRequest {
    prepared: ZcnblkFanPreparedFrame,
    segments: Vec<ZcnblkFanSegment>,
    local_read: Option<ZcnblkFanWalLocalRead>,
    response_sent: bool,
    accounted: bool,
    order_released: bool,
}

struct ZcnblkFanWalSubmittedRequestBatch {
    requests: Vec<ZcnblkFanWalSubmittedRequest>,
    leaf_batches: Vec<ZcnblkFanWalLeafResultBatch>,
    records: Vec<u64>,
    dirty_lease: Option<ZcnblkFanWalDirtyLease>,
    owned_leaf_batches: Vec<ZcnblkFanWalOwnedLeafBatch>,
}

impl ZcnblkFanWalSubmittedRequestBatch {
    fn has_leaf_work(&self) -> bool {
        self.leaf_batches
            .iter()
            .any(|batch| !batch.items.is_empty())
    }
}

#[derive(Clone, Copy)]
struct ZcnblkFanWalLeafBatchItem {
    request_idx: usize,
    segment_idx: usize,
    segment: ZcnblkFanSegment,
}

struct ZcnblkFanWalOwnedLeafBatch {
    leaf_idx: usize,
    frame: ZcnblkFanWalFrame,
    descriptor_bytes: Vec<u8>,
    payload_bytes: Vec<u8>,
    payload_ranges: Vec<ZcnblkFanWalOwnedPayloadRange>,
}

enum ZcnblkFanWalOwnedPayloadRange {
    Heap {
        source: Arc<Vec<u8>>,
        start: usize,
        len: usize,
    },
    Memfd {
        log: Arc<ZcnblkFanWalMemfdLog>,
        start: u64,
        len: usize,
    },
}

struct ZcnblkFanWalPendingMemfdPayloadWrite {
    log: Arc<ZcnblkFanWalMemfdLog>,
    start: u64,
    len: usize,
}

static ZCNBLK_FAN_WAL_MEMFD_SEND_COALESCE_BYTES: OnceLock<usize> = OnceLock::new();
static ZCNBLK_FAN_WAL_INGRESS_MEMFD_PAYLOAD: OnceLock<bool> = OnceLock::new();
static ZCNBLK_FAN_WAL_HWM_ONLY_RESULTS: OnceLock<bool> = OnceLock::new();
static ZCNBLK_WAL_ZERO_COPY_STRICT: OnceLock<bool> = OnceLock::new();
static ZCNBLK_FAN_WAL_ZERO_READ_SOURCE: OnceLock<Arc<Vec<u8>>> = OnceLock::new();

fn zcnblk_fan_wal_memfd_send_coalesce_bytes() -> usize {
    *ZCNBLK_FAN_WAL_MEMFD_SEND_COALESCE_BYTES
        .get_or_init(|| env_usize_or("URING_PLAY_ZCNBLK_FAN_MEMFD_SEND_COALESCE_BYTES", 0))
}

fn zcnblk_fan_wal_ingress_memfd_payload_enabled() -> bool {
    *ZCNBLK_FAN_WAL_INGRESS_MEMFD_PAYLOAD.get_or_init(|| {
        env_enabled_or("URING_PLAY_ZCNBLK_FAN_INGRESS_MEMFD_PAYLOAD", false)
            || env_enabled_or("URING_PLAY_ZCNBLK_FAN_DIRECT_MEMFD_PAYLOAD", false)
    })
}

fn zcnblk_wal_zero_copy_strict_enabled() -> bool {
    *ZCNBLK_WAL_ZERO_COPY_STRICT.get_or_init(|| {
        env_enabled_or("URING_PLAY_ZCNBLK_WAL_ZERO_COPY_STRICT", false)
            || env_enabled_or("URING_PLAY_ZCNBLK_ZERO_COPY_STRICT", false)
    })
}

fn zcnblk_fan_wal_zero_read_source() -> Arc<Vec<u8>> {
    Arc::clone(ZCNBLK_FAN_WAL_ZERO_READ_SOURCE.get_or_init(|| {
        let bytes =
            env_usize_or("URING_PLAY_ZCNBLK_ZERO_LEASE_BYTES", 1024 * 1024).max(ZC_WAL_RECORD_SIZE);
        Arc::new(vec![0u8; align_up(bytes, ZC_WAL_RECORD_SIZE)])
    }))
}

fn zcnblk_fan_wal_push_zero_read_parts(
    parts: &mut Vec<ZcnblkFanWalReadPart>,
    mut len: usize,
) -> io::Result<()> {
    if len == 0 {
        return Ok(());
    }
    let source = zcnblk_fan_wal_zero_read_source();
    if source.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "fan WAL zero read source is empty",
        ));
    }
    while len != 0 {
        let chunk = len.min(source.len());
        parts.push(ZcnblkFanWalReadPart::Lease {
            source: Arc::clone(&source),
            start: 0,
            len: chunk,
        });
        len -= chunk;
    }
    Ok(())
}

fn zcnblk_fan_wal_zero_local_read(len: usize) -> io::Result<ZcnblkFanWalLocalRead> {
    let mut parts = Vec::new();
    zcnblk_fan_wal_push_zero_read_parts(&mut parts, len)?;
    Ok(ZcnblkFanWalLocalRead::leased(len, parts))
}

impl ZcnblkFanWalOwnedPayloadRange {
    fn len(&self) -> usize {
        match self {
            Self::Heap { len, .. } | Self::Memfd { len, .. } => *len,
        }
    }

    fn is_memfd(&self) -> bool {
        matches!(self, Self::Memfd { .. })
    }

    fn write_to_stream(&self, stream: &mut TcpStream) -> io::Result<()> {
        match self {
            Self::Heap { source, start, len } => {
                let end = start.checked_add(*len).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "fan WAL owned heap range overflow",
                    )
                })?;
                let payload = source.get(*start..end).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "fan WAL owned heap range out of source bounds",
                    )
                })?;
                stream.write_all(payload)
            }
            Self::Memfd { log, start, len } => log.sendfile_to(stream.as_raw_fd(), *start, *len),
        }
    }
}

fn zcnblk_fan_wal_flush_pending_memfd_payload_write(
    stream: &mut TcpStream,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
) -> io::Result<()> {
    let Some(pending) = pending.take() else {
        return Ok(());
    };
    pending
        .log
        .sendfile_to(stream.as_raw_fd(), pending.start, pending.len)
}

fn zcnblk_fan_wal_write_memfd_payload_range_coalesced(
    stream: &mut TcpStream,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
    log: Arc<ZcnblkFanWalMemfdLog>,
    start: u64,
    len: usize,
) -> io::Result<()> {
    if len == 0 {
        return Ok(());
    }
    let max_coalesce_bytes = zcnblk_fan_wal_memfd_send_coalesce_bytes();
    if max_coalesce_bytes == 0 || len > max_coalesce_bytes {
        zcnblk_fan_wal_flush_pending_memfd_payload_write(stream, pending)?;
        return log.sendfile_to(stream.as_raw_fd(), start, len);
    }
    if let Some(existing) = pending.as_mut() {
        let existing_end = existing
            .start
            .checked_add(existing.len as u64)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL pending memfd payload range overflow",
                )
            })?;
        let merged_len = existing.len.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL pending memfd payload length overflow",
            )
        })?;
        if Arc::ptr_eq(&existing.log, &log)
            && existing_end == start
            && merged_len <= max_coalesce_bytes
        {
            existing.len = merged_len;
            return Ok(());
        }
    }
    zcnblk_fan_wal_flush_pending_memfd_payload_write(stream, pending)?;
    *pending = Some(ZcnblkFanWalPendingMemfdPayloadWrite { log, start, len });
    Ok(())
}

fn zcnblk_fan_wal_write_owned_payload_range_coalesced(
    stream: &mut TcpStream,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
    range: &ZcnblkFanWalOwnedPayloadRange,
) -> io::Result<()> {
    match range {
        ZcnblkFanWalOwnedPayloadRange::Heap { source, start, len } => {
            zcnblk_fan_wal_flush_pending_memfd_payload_write(stream, pending)?;
            let end = start.checked_add(*len).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL owned heap range overflow",
                )
            })?;
            let payload = source.get(*start..end).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL owned heap range out of source bounds",
                )
            })?;
            stream.write_all(payload)
        }
        ZcnblkFanWalOwnedPayloadRange::Memfd { log, start, len } => {
            zcnblk_fan_wal_write_memfd_payload_range_coalesced(
                stream,
                pending,
                Arc::clone(log),
                *start,
                *len,
            )
        }
    }
}

fn zcnblk_fan_wal_write_owned_payload_bytes_coalesced(
    stream: &mut TcpStream,
    pending: &mut Option<ZcnblkFanWalPendingMemfdPayloadWrite>,
    payload: &[u8],
) -> io::Result<()> {
    if payload.is_empty() {
        return Ok(());
    }
    zcnblk_fan_wal_flush_pending_memfd_payload_write(stream, pending)?;
    stream.write_all(payload)
}

#[derive(Clone, Copy)]
struct ZcnblkFanWalLeafExpectedResultBatch {
    leaf_idx: usize,
    expected_records: usize,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ZcnblkFanWalCompactWriteExtent {
    leaf_offset: u64,
    logical_offset: u64,
    payload_len: u32,
    record_count: u32,
    mode_selector: u64,
    io_contract_word: u32,
    lease_id: u64,
}

impl ZcnblkFanWalCompactWriteExtent {
    fn encode(self) -> [u8; ZCNBLK_FAN_WAL_COMPACT_WRITE_EXTENT_LEN] {
        let mut out = [0u8; ZCNBLK_FAN_WAL_COMPACT_WRITE_EXTENT_LEN];
        out[0..8].copy_from_slice(&self.leaf_offset.to_le_bytes());
        out[8..16].copy_from_slice(&self.logical_offset.to_le_bytes());
        out[16..20].copy_from_slice(&self.payload_len.to_le_bytes());
        out[20..24].copy_from_slice(&self.record_count.to_le_bytes());
        out[24..32].copy_from_slice(&self.mode_selector.to_le_bytes());
        out[32..36].copy_from_slice(&self.io_contract_word.to_le_bytes());
        out[40..48].copy_from_slice(&self.lease_id.to_le_bytes());
        out
    }

    fn decode(input: &[u8]) -> io::Result<Self> {
        let input: &[u8; ZCNBLK_FAN_WAL_COMPACT_WRITE_EXTENT_LEN] =
            input.try_into().map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "fan WAL compact write extent length {} is not {}",
                        input.len(),
                        ZCNBLK_FAN_WAL_COMPACT_WRITE_EXTENT_LEN
                    ),
                )
            })?;
        let reserved = u32::from_le_bytes(input[36..40].try_into().expect("u32"));
        if reserved != 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL compact write extent has nonzero reserved contract bytes",
            ));
        }
        Ok(Self {
            leaf_offset: u64::from_le_bytes(input[0..8].try_into().expect("u64")),
            logical_offset: u64::from_le_bytes(input[8..16].try_into().expect("u64")),
            payload_len: u32::from_le_bytes(input[16..20].try_into().expect("u32")),
            record_count: u32::from_le_bytes(input[20..24].try_into().expect("u32")),
            mode_selector: u64::from_le_bytes(input[24..32].try_into().expect("u64")),
            io_contract_word: u32::from_le_bytes(input[32..36].try_into().expect("u32")),
            lease_id: u64::from_le_bytes(input[40..48].try_into().expect("u64")),
        })
    }
}

fn zcnblk_fan_wal_push_source_iov<'a>(
    iovecs: &mut Vec<IoSlice<'a>>,
    source: &'a [u8],
    start: usize,
    len: usize,
    label: &str,
) -> io::Result<()> {
    let end = start.checked_add(len).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} range overflow"),
        )
    })?;
    let payload = source.get(start..end).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} range out of source bounds"),
        )
    })?;
    if payload.is_empty() {
        return Ok(());
    }
    if let Some(last) = iovecs.last_mut() {
        let last_slice: &[u8] = last.as_ref();
        let last_end = unsafe { last_slice.as_ptr().add(last_slice.len()) };
        if last_end == payload.as_ptr() {
            let merged_len = last_slice.len().checked_add(payload.len()).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("{label} iovec overflow"),
                )
            })?;
            // Both slices are subranges of the same source slice and are adjacent.
            let merged = unsafe { slice::from_raw_parts(last_slice.as_ptr(), merged_len) };
            *last = IoSlice::new(merged);
            return Ok(());
        }
    }
    iovecs.push(IoSlice::new(payload));
    Ok(())
}

fn zcnblk_fan_wal_push_owned_payload_range(
    ranges: &mut Vec<ZcnblkFanWalOwnedPayloadRange>,
    source: Arc<Vec<u8>>,
    start: usize,
    len: usize,
) -> io::Result<()> {
    let end = start.checked_add(len).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "fan WAL owned payload range overflow",
        )
    })?;
    if end > source.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "fan WAL owned payload range out of source bounds",
        ));
    }
    if let Some(last) = ranges.last_mut() {
        if let ZcnblkFanWalOwnedPayloadRange::Heap {
            source: last_source,
            start: last_start,
            len: last_len,
        } = last
        {
            let last_end = last_start.checked_add(*last_len).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL owned payload range overflow",
                )
            })?;
            if Arc::ptr_eq(last_source, &source) && last_end == start {
                *last_len = last_len.checked_add(len).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "fan WAL owned payload range length overflow",
                    )
                })?;
                return Ok(());
            }
        }
    }
    ranges.push(ZcnblkFanWalOwnedPayloadRange::Heap { source, start, len });
    Ok(())
}

fn zcnblk_fan_wal_push_owned_memfd_payload_range(
    ranges: &mut Vec<ZcnblkFanWalOwnedPayloadRange>,
    log: Arc<ZcnblkFanWalMemfdLog>,
    start: u64,
    len: usize,
) -> io::Result<()> {
    if let Some(ZcnblkFanWalOwnedPayloadRange::Memfd {
        log: last_log,
        start: last_start,
        len: last_len,
    }) = ranges.last_mut()
    {
        let last_end = last_start.checked_add(*last_len as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "fan WAL owned memfd payload range overflow",
            )
        })?;
        if Arc::ptr_eq(last_log, &log) && last_end == start {
            *last_len = last_len.checked_add(len).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "fan WAL owned memfd payload range length overflow",
                )
            })?;
            return Ok(());
        }
    }
    ranges.push(ZcnblkFanWalOwnedPayloadRange::Memfd { log, start, len });
    Ok(())
}

fn zcnblk_fan_wal_push_commit_range(
    ranges: &mut Vec<(u64, usize, u64)>,
    offset: u64,
    len: usize,
    sequence: u64,
) -> io::Result<()> {
    if let Some((last_offset, last_len, last_sequence)) = ranges.last_mut() {
        let last_end = last_offset
            .checked_add(*last_len as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "commit range overflow"))?;
        if *last_sequence == sequence && last_end == offset {
            *last_len = last_len.checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "commit range length overflow")
            })?;
            return Ok(());
        }
    }
    ranges.push((offset, len, sequence));
    Ok(())
}

