fn zcnblk_fan_wal_dirty_lease_run_covers(
    run: ZcnblkFanWalDirtyLeaseRun,
    record: u64,
) -> io::Result<bool> {
    let first = ZcnblkFanWalDirtyCache::record_index(run.offset);
    let count = run.len / ZC_WAL_RECORD_SIZE;
    let end = first.checked_add(count as u64).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "local dirty lease run record overflow",
        )
    })?;
    Ok(record >= first && record < end)
}

fn zcnblk_fan_wal_read_from_local_dirty_lease_runs(
    source: &Arc<Vec<u8>>,
    runs: &[ZcnblkFanWalDirtyLeaseRun],
    offset: u64,
    len: usize,
) -> io::Result<Option<ZcnblkFanWalLocalRead>> {
    ZcnblkFanWalDirtyCache::validate_range(offset, len, "local cached-ref read")?;
    if runs.is_empty() {
        return Ok(None);
    }
    let first = ZcnblkFanWalDirtyCache::record_index(offset);
    let count = len / ZC_WAL_RECORD_SIZE;
    let end = first.checked_add(count as u64).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "local cached read end overflow",
        )
    })?;
    let mut record = first;
    let mut parts = Vec::new();
    while record < end {
        let Some((run_idx, run)) = runs.iter().copied().enumerate().rev().find(|(_idx, run)| {
            zcnblk_fan_wal_dirty_lease_run_covers(*run, record).unwrap_or(false)
        }) else {
            return Ok(None);
        };
        let run_first = ZcnblkFanWalDirtyCache::record_index(run.offset);
        let run_count = run.len / ZC_WAL_RECORD_SIZE;
        let mut run_end = run_first.checked_add(run_count as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "local dirty lease run end overflow",
            )
        })?;
        run_end = run_end.min(end);
        for later in &runs[run_idx + 1..] {
            let later_first = ZcnblkFanWalDirtyCache::record_index(later.offset);
            if later_first > record && later_first < run_end {
                run_end = later_first;
            }
        }
        let record_offset = usize::try_from(record - run_first).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "local dirty lease read offset overflow",
            )
        })?;
        let run_records = usize::try_from(run_end - record).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "local dirty lease read run overflow",
            )
        })?;
        let byte_offset = record_offset
            .checked_mul(ZC_WAL_RECORD_SIZE)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "local dirty lease byte offset overflow",
                )
            })?;
        let start = run.source_start.checked_add(byte_offset).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "local dirty lease source start overflow",
            )
        })?;
        let run_bytes = run_records.checked_mul(ZC_WAL_RECORD_SIZE).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "local dirty lease read byte overflow",
            )
        })?;
        let source_end = start.checked_add(run_bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "local dirty lease source end overflow",
            )
        })?;
        if source_end > source.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "local dirty lease read outside source range",
            ));
        }
        parts.push(ZcnblkFanWalReadPart::Lease {
            source: Arc::clone(source),
            start,
            len: run_bytes,
        });
        record = run_end;
    }
    Ok(Some(ZcnblkFanWalLocalRead::leased(len, parts)))
}

