    #[test]
    fn zcraid_mirror_lane_owner_layout_disjoins_zlanes() {
        let (_, lane0_first, lane0_last, lane0_wal) = zcraid_mirror_extent_layout(
            0,
            4,
            0,
            ZC_WAL_RECORD_SIZE,
            ZcRaidZlaneCoordMode::LaneOwner,
        )
        .unwrap();
        let (_, lane1_first, lane1_last, lane1_wal) = zcraid_mirror_extent_layout(
            1,
            4,
            0,
            ZC_WAL_RECORD_SIZE,
            ZcRaidZlaneCoordMode::LaneOwner,
        )
        .unwrap();
        let (_, lane0_seq1_first, _, lane0_seq1_wal) = zcraid_mirror_extent_layout(
            0,
            4,
            1,
            ZC_WAL_RECORD_SIZE,
            ZcRaidZlaneCoordMode::LaneOwner,
        )
        .unwrap();

        assert_eq!((lane0_first, lane0_last, lane0_wal), (0, 0, 0));
        assert_eq!(
            (lane1_first, lane1_last, lane1_wal),
            (1, 1, ZC_WAL_RECORD_SIZE as u64)
        );
        assert_eq!(
            (lane0_seq1_first, lane0_seq1_wal),
            (4, (4 * ZC_WAL_RECORD_SIZE) as u64)
        );
    }

