    #[test]
    fn zcnblk_fan_wal_coalescing_preserves_atomic_priority_and_lifetime_boundaries() {
        let frame = |contract: ZcnblkWalIoContract| {
            ZcnblkFanWalFrame {
                op: ZCNBLK_FAN_WAL_OP_WRITE_DESC,
                logical_len: 4096,
                payload_len: 4096,
                ..ZcnblkFanWalFrame::default()
            }
            .with_io_contract(contract)
            .unwrap()
        };
        let normal = frame(ZcnblkWalIoContract::default());
        assert!(zcnblk_wal_leaf_contracts_may_coalesce(normal, normal).unwrap());
        let prioritized = frame(ZcnblkWalIoContract {
            ioprio: 0x4001,
            ..ZcnblkWalIoContract::default()
        });
        assert!(!zcnblk_wal_leaf_contracts_may_coalesce(normal, prioritized).unwrap());
        let atomic = frame(ZcnblkWalIoContract {
            atomic_write: true,
            ..ZcnblkWalIoContract::default()
        });
        assert!(!zcnblk_wal_leaf_contracts_may_coalesce(atomic, atomic).unwrap());
    }

    #[test]
    fn zcfanout_shmlease_zcnblk_request_token_carries_logical_page() {
        let lane = 3usize;
        let sequence = 0x1234_5678_9abc_u64;
        let payload_bytes = 4096usize;
        let logical_page = 0x55aa_0011_2233_u64;
        let request = ZcnblkShmWalRequest::new(lane, sequence, payload_bytes, logical_page);
        let token = request.request_token;

        assert_eq!(
            zcfanout_loglease_zcnblk_decode_logical_page(lane, sequence, payload_bytes, token),
            logical_page
        );
        let descriptor = ZcnblkShmWalDescriptor::from_primary_record(
            "test descriptor",
            lane,
            sequence,
            payload_bytes,
            token,
            8192,
            payload_bytes as u64,
            0x1234,
            Some(logical_page as usize + 1),
        )
        .unwrap();
        assert_eq!(descriptor.request, request);

        let response_token = token ^ 0xfeed_beef_u64;
        let checksum = descriptor.response_checksum(response_token);
        assert_ne!(
            checksum,
            zcfanout_loglease_zcnblk_response_checksum(
                token,
                0x1234,
                response_token,
                logical_page ^ 1,
            )
        );

        let mut dirty_tokens = Some(vec![0u64; 8]);
        let dirty_request = ZcnblkShmWalRequest::new(lane, sequence, payload_bytes, 4);
        assert_eq!(
            dirty_request
                .note_dirty_write(&mut dirty_tokens, "test")
                .unwrap(),
            dirty_request.request_token
        );
        assert!(
            ZcnblkShmWalRequest::new(lane, sequence, payload_bytes, 9)
                .note_dirty_write(&mut dirty_tokens, "test")
                .is_err()
        );
        assert!(
            ZcnblkShmWalDescriptor::from_primary_record(
                "test descriptor",
                lane,
                sequence,
                payload_bytes,
                token,
                8192,
                payload_bytes as u64,
                0x1234,
                Some(1),
            )
            .is_err()
        );
    }

    #[test]
    fn zcfanout_shmlease_arena_dirty_hwm_cache_requires_commit_before_slot_reuse() {
        let owner = ZcLogLeaseArenaMap::create(2, ZC_WAL_RECORD_SIZE).unwrap();
        let arena = Arc::new(owner.duplicate_view().unwrap());
        let mut cache = ZcnblkShmArenaDirtyHwmCache::new(Arc::clone(&arena), 2);

        cache.admit(0, 0, ZC_WAL_RECORD_SIZE, 0).unwrap();
        assert_eq!(cache.read_ref(0, ZC_WAL_RECORD_SIZE).unwrap(), 1);
        assert!(cache.admit(2, 0, ZC_WAL_RECORD_SIZE, 2).is_err());

        cache.commit(0, 0);
        assert!(cache.read_ref(0, ZC_WAL_RECORD_SIZE).is_err());
        cache.admit(2, 0, ZC_WAL_RECORD_SIZE, 2).unwrap();
        assert_eq!(cache.read_ref(2, ZC_WAL_RECORD_SIZE).unwrap(), 1);
        cache.commit_hwm(3);
        assert!(cache.read_ref(2, ZC_WAL_RECORD_SIZE).is_err());
        drop(owner);
    }

    #[test]
    fn zcfanout_shmlease_arena_dirty_hwm_cache_supports_random_pages() {
        let owner = ZcLogLeaseArenaMap::create(8, ZC_WAL_RECORD_SIZE).unwrap();
        let arena = Arc::new(owner.duplicate_view().unwrap());
        let mut cache = ZcnblkShmArenaDirtyHwmCache::new(Arc::clone(&arena), 8);

        cache.admit(5, 0, ZC_WAL_RECORD_SIZE, 0).unwrap();
        cache
            .admit(2, ZC_WAL_RECORD_SIZE, ZC_WAL_RECORD_SIZE, 1)
            .unwrap();
        cache
            .admit(5, ZC_WAL_RECORD_SIZE * 2, ZC_WAL_RECORD_SIZE, 2)
            .unwrap();
        assert_eq!(cache.read_ref(5, ZC_WAL_RECORD_SIZE).unwrap(), 1);
        assert_eq!(cache.read_ref(2, ZC_WAL_RECORD_SIZE).unwrap(), 1);

        cache.commit_hwm(2);
        assert_eq!(cache.read_ref(5, ZC_WAL_RECORD_SIZE).unwrap(), 1);
        assert!(cache.read_ref(2, ZC_WAL_RECORD_SIZE).is_err());
        cache.commit_hwm(3);
        assert!(cache.read_ref(5, ZC_WAL_RECORD_SIZE).is_err());
        drop(owner);
    }

    #[test]
    fn zcnblk_fan_wal_segments_cover_stripe_and_mirror() {
        let stripe = zcnblk_fan_wal_segments(
            ZcnblkFanPlacementMode::Stripe,
            ZCNBLK_OP_READ,
            0,
            8192,
            4096,
            2,
        )
        .unwrap();
        assert_eq!(stripe.len(), 2);
        assert_eq!(stripe[0].leaf_idx, 0);
        assert_eq!(stripe[0].leaf_offset, 0);
        assert_eq!(stripe[0].payload_offset, 0);
        assert_eq!(stripe[0].len, 4096);
        assert_eq!(stripe[1].leaf_idx, 1);
        assert_eq!(stripe[1].leaf_offset, 0);
        assert_eq!(stripe[1].payload_offset, 4096);
        assert_eq!(stripe[1].len, 4096);

        let mirror = zcnblk_fan_wal_segments(
            ZcnblkFanPlacementMode::Mirror,
            ZCNBLK_OP_WRITE,
            16384,
            4096,
            4096,
            2,
        )
        .unwrap();
        assert_eq!(mirror.len(), 2);
        assert_eq!(mirror[0].leaf_idx, 0);
        assert_eq!(mirror[0].leaf_offset, 16384);
        assert_eq!(mirror[0].payload_offset, 0);
        assert_eq!(mirror[1].leaf_idx, 1);
        assert_eq!(mirror[1].leaf_offset, 16384);
        assert_eq!(mirror[1].payload_offset, 0);

        let mirror_read = zcnblk_fan_wal_segments(
            ZcnblkFanPlacementMode::Mirror,
            ZCNBLK_OP_READ,
            0,
            8192,
            4096,
            2,
        )
        .unwrap();
        assert_eq!(mirror_read.len(), 2);
        assert_eq!(mirror_read[0].leaf_idx, 0);
        assert_eq!(mirror_read[0].leaf_offset, 0);
        assert_eq!(mirror_read[0].payload_offset, 0);
        assert_eq!(mirror_read[1].leaf_idx, 1);
        assert_eq!(mirror_read[1].leaf_offset, 4096);
        assert_eq!(mirror_read[1].payload_offset, 4096);

        let mirror_extent = zcnblk_fan_wal_mirror_read_extent_segments(
            2 * 1024 * 1024,
            1024 * 1024,
            4096,
            2,
            1024 * 1024,
        )
        .unwrap();
        assert_eq!(mirror_extent.len(), 1);
        assert_eq!(mirror_extent[0].leaf_idx, 0);
        assert_eq!(mirror_extent[0].leaf_offset, 2 * 1024 * 1024);
        assert_eq!(mirror_extent[0].payload_offset, 0);
        assert_eq!(mirror_extent[0].len, 1024 * 1024);

        let raid10_write = zcnblk_fan_wal_segments(
            ZcnblkFanPlacementMode::Raid10,
            ZCNBLK_OP_WRITE,
            0,
            8192,
            4096,
            4,
        )
        .unwrap();
        assert_eq!(raid10_write.len(), 4);
        assert_eq!(raid10_write[0].leaf_idx, 0);
        assert_eq!(raid10_write[0].leaf_offset, 0);
        assert_eq!(raid10_write[0].payload_offset, 0);
        assert_eq!(raid10_write[1].leaf_idx, 1);
        assert_eq!(raid10_write[1].leaf_offset, 0);
        assert_eq!(raid10_write[1].payload_offset, 0);
        assert_eq!(raid10_write[2].leaf_idx, 2);
        assert_eq!(raid10_write[2].leaf_offset, 0);
        assert_eq!(raid10_write[2].payload_offset, 4096);
        assert_eq!(raid10_write[3].leaf_idx, 3);
        assert_eq!(raid10_write[3].leaf_offset, 0);
        assert_eq!(raid10_write[3].payload_offset, 4096);

        let raid10_read = zcnblk_fan_wal_segments(
            ZcnblkFanPlacementMode::Raid10,
            ZCNBLK_OP_READ,
            0,
            16384,
            4096,
            4,
        )
        .unwrap();
        assert_eq!(raid10_read.len(), 4);
        assert_eq!(raid10_read[0].leaf_idx, 0);
        assert_eq!(raid10_read[0].leaf_offset, 0);
        assert_eq!(raid10_read[0].payload_offset, 0);
        assert_eq!(raid10_read[1].leaf_idx, 2);
        assert_eq!(raid10_read[1].leaf_offset, 0);
        assert_eq!(raid10_read[1].payload_offset, 4096);
        assert_eq!(raid10_read[2].leaf_idx, 1);
        assert_eq!(raid10_read[2].leaf_offset, 4096);
        assert_eq!(raid10_read[2].payload_offset, 8192);
        assert_eq!(raid10_read[3].leaf_idx, 3);
        assert_eq!(raid10_read[3].leaf_offset, 4096);
        assert_eq!(raid10_read[3].payload_offset, 12288);
    }

    #[test]
    fn zcnblk_fan_wal_write_batch_pipeline_rejects_internal_overlap_but_orders_it() {
        let topology = ZcnblkFrameTopology {
            lane_id: 0,
            lane_count: 1,
            preferred_worker: 0,
            queue_id: 0,
            request_id: 1,
            tier_id: 0,
            topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
        };
        let make_plan = |offset: u64, request_id: u64, completed: usize| {
            let mut topology = topology;
            topology.request_id = request_id;
            let frame =
                ZcnblkFrameHeader::with_topology(ZCNBLK_OP_WRITE, 0, 0, 4096, offset, topology)
                    .unwrap();
            let plan = zcnblk_read_fan_plan_frame(frame, 0, 1, 16384, 4096, completed).unwrap();
            assert_eq!(plan.frame.offset, offset);
            assert_eq!(plan.len, 4096);
            plan
        };

        let non_overlapping = vec![make_plan(0, 1, 0), make_plan(4096, 2, 4096)];
        assert!(zcnblk_fan_wal_can_pipeline_write_batch(&non_overlapping));

        let overlapping = vec![make_plan(0, 3, 0), make_plan(0, 4, 4096)];
        assert!(!zcnblk_fan_wal_can_pipeline_write_batch(&overlapping));
        assert!(zcnblk_fan_wal_can_ordered_write_batch(&overlapping));
    }

    fn zcnblk_fan_wal_dirty_cache_with_direct(slot_count: usize) -> ZcnblkFanWalDirtyCache {
        let shard_count = 4usize.min(slot_count.max(1));
        let slots_per_shard = slot_count.max(1).div_ceil(shard_count);
        ZcnblkFanWalDirtyCache {
            shards: Arc::new(
                (0..shard_count)
                    .map(|_| Mutex::new(ZcnblkFanWalDirtyCacheShard::default()))
                    .collect(),
            ),
            extent_shards: Arc::new(
                (0..shard_count)
                    .map(|_| Mutex::new(BTreeMap::new()))
                    .collect(),
            ),
            direct_table: Some(ZcnblkFanWalDirtyDirectTable {
                shards: Arc::new(
                    (0..shard_count)
                        .map(|_| {
                            Mutex::new(
                                std::iter::repeat_with(|| None)
                                    .take(slots_per_shard)
                                    .collect::<Vec<_>>(),
                            )
                        })
                        .collect(),
                ),
                slot_count: slot_count.max(1),
            }),
            extent_shard_records: 16 * 1024,
            record_entries: Arc::new(AtomicUsize::new(0)),
            extent_entries: Arc::new(AtomicUsize::new(0)),
            retain_committed: false,
        }
    }

    #[test]
    fn zcnblk_fan_wal_dirty_direct_cache_clears_on_commit() {
        let cache = zcnblk_fan_wal_dirty_cache_with_direct(8);
        let source = Arc::new(vec![0x5au8; ZC_WAL_RECORD_SIZE]);
        cache
            .admit_write_lease(0, Arc::clone(&source), 0, ZC_WAL_RECORD_SIZE, 10)
            .unwrap();
        let read = cache
            .read_cached_refs(0, ZC_WAL_RECORD_SIZE)
            .unwrap()
            .expect("direct dirty read");
        assert_eq!(read.len(), ZC_WAL_RECORD_SIZE);
        assert_eq!(read.source_part_count(), 1);

        cache.mark_committed(0, ZC_WAL_RECORD_SIZE, 10).unwrap();
        assert!(
            cache
                .read_cached_refs(0, ZC_WAL_RECORD_SIZE)
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn zcnblk_fan_wal_dirty_direct_cache_does_not_resurrect_older_extent() {
        let cache = zcnblk_fan_wal_dirty_cache_with_direct(8);
        let newer = Arc::new(vec![0x22u8; ZC_WAL_RECORD_SIZE]);
        let older = Arc::new(vec![0x11u8; ZC_WAL_RECORD_SIZE]);
        cache
            .admit_write_lease(0, Arc::clone(&newer), 0, ZC_WAL_RECORD_SIZE, 20)
            .unwrap();
        cache
            .direct_table
            .as_ref()
            .unwrap()
            .clear_if_current(0, 20)
            .unwrap();
        cache
            .admit_write_lease(0, Arc::clone(&older), 0, ZC_WAL_RECORD_SIZE, 10)
            .unwrap();

        let read = cache
            .read_cached_refs(0, ZC_WAL_RECORD_SIZE)
            .unwrap()
            .expect("cached read");
        let ZcnblkFanWalLocalRead::Leased { parts, .. } = read else {
            panic!("dirty direct cache should return leased parts");
        };
        assert_eq!(parts.len(), 1);
        let ZcnblkFanWalReadPart::Lease { source, .. } = &parts[0] else {
            panic!("expected lease read part");
        };
        assert!(Arc::ptr_eq(source, &newer));
    }

