    #[test]
    fn zcnblk_fan_wal_dirty_budget_tracks_admit_pressure_and_release() {
        let budget = ZcnblkFanWalDirtyBudget::new(ZcnblkFanWalDirtyBudgetConfig {
            enabled: true,
            soft_bytes: 4096,
            hard_bytes: 8192,
        });
        let mut stats = ZcnblkFanWalDirtyStats::default();

        let lease_a = budget.reserve(4096, &mut stats).unwrap().unwrap();
        assert_eq!(budget.pressure(1).unwrap(), ZcnblkFanWalDirtyPressure::Soft);
        let lease_b = budget.reserve(4096, &mut stats).unwrap().unwrap();
        assert_eq!(budget.pressure(1).unwrap(), ZcnblkFanWalDirtyPressure::Hard);

        let snapshot = budget.snapshot();
        assert_eq!(snapshot.current_bytes, 8192);
        assert_eq!(snapshot.max_observed_bytes, 8192);
        assert_eq!(snapshot.total_admit_bytes, 8192);
        assert_eq!(snapshot.total_admit_events, 2);
        assert_eq!(stats.admit_bytes, 8192);
        assert_eq!(stats.admit_events, 2);
        assert_eq!(stats.soft_pressure_events, 1);

        drop(lease_a);
        assert_eq!(budget.snapshot().current_bytes, 4096);
        drop(lease_b);
        let snapshot = budget.snapshot();
        assert_eq!(snapshot.current_bytes, 0);
        assert_eq!(snapshot.total_release_bytes, 8192);
        assert_eq!(snapshot.total_release_events, 2);
        budget.wait_empty(&mut stats).unwrap();
    }

