    #[test]
    fn zcnblk_fan_wal_leased_read_parts_coalesce_adjacent_iovecs() {
        let source = Arc::new(vec![0x5a; 3 * ZC_WAL_RECORD_SIZE]);
        let local_read = ZcnblkFanWalLocalRead::leased(
            3 * ZC_WAL_RECORD_SIZE,
            vec![
                ZcnblkFanWalReadPart::Lease {
                    source: Arc::clone(&source),
                    start: 0,
                    len: ZC_WAL_RECORD_SIZE,
                },
                ZcnblkFanWalReadPart::Lease {
                    source: Arc::clone(&source),
                    start: ZC_WAL_RECORD_SIZE,
                    len: 2 * ZC_WAL_RECORD_SIZE,
                },
            ],
        );
        let header = [0u8; 16];
        let mut iovecs = vec![libc::iovec {
            iov_base: header.as_ptr() as *mut libc::c_void,
            iov_len: header.len(),
        }];

        local_read.push_iovecs(&mut iovecs).unwrap();

        assert_eq!(iovecs.len(), 2);
        assert_eq!(iovecs[1].iov_len, 3 * ZC_WAL_RECORD_SIZE);
        assert_eq!(iovecs[1].iov_base, source.as_ptr() as *mut libc::c_void);
    }

