    #[test]
    fn zcnblk_fan_wal_request_chunks_bound_write_payload_without_splitting_reads() {
        let topology = ZcnblkFrameTopology {
            lane_id: 0,
            lane_count: 1,
            preferred_worker: 0,
            queue_id: 0,
            request_id: 1,
            tier_id: 0,
            topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
        };
        let mut plans = Vec::new();
        for idx in 0..8usize {
            let op = if idx % 2 == 0 {
                ZCNBLK_OP_WRITE
            } else {
                ZCNBLK_OP_READ
            };
            let frame = ZcnblkFrameHeader::with_topology(
                op,
                0,
                0,
                ZC_WAL_RECORD_SIZE,
                (idx / 2 * ZC_WAL_RECORD_SIZE) as u64,
                topology,
            )
            .unwrap();
            plans.push(ZcnblkFanFramePlan {
                frame,
                len: ZC_WAL_RECORD_SIZE,
                next_completed: (idx + 1) * ZC_WAL_RECORD_SIZE,
                records: vec![(idx / 2) as u64],
            });
        }

        let chunks = zcnblk_fan_wal_split_frame_plan_chunks(plans, 2 * ZC_WAL_RECORD_SIZE);

        assert_eq!(chunks.len(), 2);
        assert_eq!(chunks[0].len(), 4);
        assert_eq!(chunks[1].len(), 4);
        assert_eq!(
            zcnblk_fan_wal_plan_write_payload_bytes(&chunks[0]).unwrap(),
            2 * ZC_WAL_RECORD_SIZE
        );
        assert_eq!(chunks[0][3].frame.op, ZCNBLK_OP_READ);
        assert_eq!(chunks[1][0].frame.op, ZCNBLK_OP_WRITE);
    }

    #[test]
    fn zcnblk_fan_wal_request_leaf_range_guard_allows_only_writes() {
        let topology = ZcnblkFrameTopology {
            lane_id: 0,
            lane_count: 1,
            preferred_worker: 0,
            queue_id: 0,
            request_id: 1,
            tier_id: 0,
            topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
        };
        let write =
            ZcnblkFrameHeader::with_topology(ZCNBLK_OP_WRITE, 0, 0, 4096, 0, topology).unwrap();
        let read =
            ZcnblkFrameHeader::with_topology(ZCNBLK_OP_READ, 0, 0, 4096, 4096, topology).unwrap();
        let order = Arc::new(ZcnblkFanOrder::new());
        let handle = ZcnblkFanOrderHandle::from_guard(order.reserve_records(vec![0, 1]).unwrap());
        let write_segment = ZcnblkFanSegment {
            leaf_idx: 0,
            leaf_offset: 0,
            payload_offset: 0,
            len: 4096,
        };
        let read_segment = ZcnblkFanSegment {
            leaf_idx: 0,
            leaf_offset: 4096,
            payload_offset: 0,
            len: 4096,
        };
        let batch = ZcnblkFanWalSubmittedRequestBatch {
            requests: vec![
                ZcnblkFanWalSubmittedRequest {
                    prepared: ZcnblkFanPreparedFrame {
                        frame: write,
                        len: 4096,
                        next_completed: 4096,
                        order: handle.clone(),
                    },
                    segments: vec![write_segment],
                    local_read: None,
                    response_sent: false,
                    accounted: false,
                    order_released: false,
                },
                ZcnblkFanWalSubmittedRequest {
                    prepared: ZcnblkFanPreparedFrame {
                        frame: read,
                        len: 4096,
                        next_completed: 8192,
                        order: handle,
                    },
                    segments: vec![read_segment],
                    local_read: Some(ZcnblkFanWalLocalRead::materialized(vec![0; 4096])),
                    response_sent: false,
                    accounted: false,
                    order_released: false,
                },
            ],
            leaf_batches: Vec::new(),
            records: vec![0, 1],
            dirty_lease: None,
            owned_leaf_batches: Vec::new(),
        };
        let write_item = ZcnblkFanWalLeafBatchItem {
            request_idx: 0,
            segment_idx: 0,
            segment: write_segment,
        };
        let read_item = ZcnblkFanWalLeafBatchItem {
            request_idx: 1,
            segment_idx: 0,
            segment: read_segment,
        };

        assert!(zcnblk_fan_wal_request_leaf_items_are_writes(
            &batch,
            &[write_item]
        ));
        assert!(!zcnblk_fan_wal_request_leaf_items_are_writes(
            &batch,
            &[write_item, read_item]
        ));
    }

    #[test]
    fn zcnblk_fan_wal_dirty_budget_tracks_pressure_and_release() {
        let budget = ZcnblkFanWalDirtyBudget::new(ZcnblkFanWalDirtyBudgetConfig {
            enabled: true,
            soft_bytes: 4096,
            hard_bytes: 8192,
        });
        let mut stats = ZcnblkFanWalDirtyStats::default();
        let mut lease = budget.reserve(4096, &mut stats).unwrap().unwrap();

        assert_eq!(stats.admit_bytes, 4096);
        assert_eq!(stats.admit_events, 1);
        assert_eq!(
            budget.pressure(4096).unwrap(),
            ZcnblkFanWalDirtyPressure::Soft
        );
        assert_eq!(
            budget.pressure(4097).unwrap(),
            ZcnblkFanWalDirtyPressure::Hard
        );

        lease.release_accounted(&mut stats).unwrap();
        let snapshot = budget.snapshot();
        assert_eq!(snapshot.current_bytes, 0);
        assert_eq!(snapshot.total_release_bytes, 4096);
        assert_eq!(snapshot.total_release_events, 1);
        assert_eq!(snapshot.max_observed_bytes, 4096);
        assert_eq!(stats.release_bytes, 4096);
        assert_eq!(stats.release_events, 1);
    }

    #[test]
    fn zcnblk_fan_prepared_batch_shares_one_order_sequence() {
        let order = Arc::new(ZcnblkFanOrder::new());
        let topology = ZcnblkFrameTopology {
            lane_id: 0,
            lane_count: 1,
            preferred_worker: 0,
            queue_id: 0,
            request_id: 1,
            tier_id: 0,
            topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
        };
        let make_plan = |offset: u64, request_id: u64, completed: usize| {
            let mut topology = topology;
            topology.request_id = request_id;
            let frame =
                ZcnblkFrameHeader::with_topology(ZCNBLK_OP_WRITE, 0, 0, 4096, offset, topology)
                    .unwrap();
            zcnblk_read_fan_plan_frame(frame, 0, 1, 16384, 4096, completed).unwrap()
        };
        let plans = vec![make_plan(0, 1, 0), make_plan(4096, 2, 4096)];
        let records = zcnblk_fan_wal_plan_records(&plans).unwrap();
        let handle = ZcnblkFanOrderHandle::from_guard(order.reserve_records(records).unwrap());
        let prepared = zcnblk_read_fan_prepared_batch_from_plans(plans, handle);
        assert_eq!(prepared.len(), 2);
        assert_eq!(prepared[0].order.seq(), prepared[1].order.seq());
        assert_eq!(prepared[0].order.records(), &[0, 1]);
        prepared[0].order.wait_turn().unwrap();
        prepared[1].order.wait_turn().unwrap();
        prepared[0].order.release();
        prepared[1].order.release();
    }

