    #[test]
    fn zcnblk_fan_result_arena_preserves_sync_identity() {
        let arena = ZcnblkFanWalResultArenaMap::create(2).unwrap();
        let expected = ZcnblkFanWalResultBatchHeader {
            op: ZCNBLK_FAN_WAL_OP_RESULT,
            status: ZCNBLK_FAN_WAL_STATUS_OK,
            branch_id: 1,
            segment_count: 1,
            payload_len: 0,
            sequence: 97,
            sync_epoch: 97,
        };
        arena.publish(0, expected).unwrap();
        let actual = arena.consume(0).unwrap();
        assert_eq!(actual.op, expected.op);
        assert_eq!(actual.sequence, expected.sequence);
        assert_eq!(actual.sync_epoch, expected.sync_epoch);
    }

    #[test]
    fn zcnblk_tier_target_parser_accepts_hot_spill_spec() {
        let plan = zcnblk_parse_tier_target("zctier:/tmp/zc-hot:/tmp/zc-cold:1g:4k:2m")
            .unwrap()
            .unwrap();
        assert_eq!(plan.device_bytes, 1024 * 1024 * 1024);
        assert_eq!(plan.required_alignment, 4096);
        match plan.backend {
            ZcnblkTargetBackend::Tier(target) => {
                assert_eq!(target.hot_path, PathBuf::from("/tmp/zc-hot"));
                assert_eq!(target.spill_path, Some(PathBuf::from("/tmp/zc-cold")));
                assert_eq!(target.device_bytes, 1024 * 1024 * 1024);
            }
            _ => panic!("expected tier target"),
        }
    }

    #[test]
    fn zcnblk_target_rejects_ambiguous_raid0_compatibility_spelling() {
        for target in ["zcraid0:/dev/zcbrd0..1:1m", "zcraid0=/dev/zcbrd0..1:1m"] {
            let err = match parse_zcnblk_target_plans(
                target,
                ZC_WAL_RECORD_SIZE,
                SlotWalBufferMode::SmallPages,
            ) {
                Ok(_) => panic!("legacy zcraid0 spelling must not remain an alias"),
                Err(err) => err,
            };
            assert_eq!(err.kind(), io::ErrorKind::InvalidInput);
            assert!(
                err.to_string()
                    .contains("compatibility spelling has been removed")
            );
        }
    }

